def test_suspect_answer_pasted_from_the_orca_notification_does_not_close():
    a = Env()
    q = [_question("freio-prod", [("Teto por pod (Recomendado)", "x"), ("Sem freio", "y")])]
    a.prompt("You have 1 orchestration message. Run `orca orchestration check`")  # arrives and the prompt hook marks it
    r = a.orq("hook", "ask", stdin=_ask(q, {q[0]["question"]: "Teto por pod (Recomendado)"}))
    assert r.returncode == 0
    assert "suspect answer in freio-prod: confirm" in json.loads(r.stdout)["hookSpecificOutput"]["additionalContext"]
    assert [i["id"] for i in _pending(a)["itens"]] == ["freio-prod", "avisar-x"], "suspeita não fecha"
    kinds = [e["tipo"] for e in a.events()]
    assert "resposta_suspeita" in kinds and "resposta" not in kinds
    assert not [e for e in a.events() if e["tipo"] == "pend" and e["op"] == "done"]
    ctx = json.loads(a.prompt("e agora?").stdout)["hookSpecificOutput"]["additionalContext"]
    assert "suspect answer in freio-prod: confirm" in ctx and len(ctx.splitlines()) <= 5
    # the question asked again and truly answered (arrival already old) closes and clears the notice
    cur = _read_state(os.path.join(a.home, "cursor.json"))
    cur["chegada"]["t"] -= 60
    json.dump(cur, open(os.path.join(a.home, "cursor.json"), "w"))
    a.orq("hook", "ask", stdin=_ask(q, {q[0]["question"]: "Sem freio"}))
    assert [i["id"] for i in _pending(a)["itens"]] == ["avisar-x"]
    assert "suspeita" not in json.loads(a.prompt("depois").stdout)["hookSpecificOutput"]["additionalContext"]


def test_suspect_answer_task_notification_and_notification_text():
    a = Env()
    q = [_question("freio-prod", [("A", "x")])]
    a.prompt("<task-notification><task-id>x</task-id></task-notification>")
    r = a.orq("hook", "ask", stdin=_ask(q, {q[0]["question"]: "A"}))
    assert "suspect answer" in r.stdout and len(_pending(a)["itens"]) == 2
    # old answer (>= 3 s) is not suspicious; and typed text that is Orca's own notice is suspicious without needing timing
    cur = _read_state(os.path.join(a.home, "cursor.json"))
    cur["chegada"]["t"] -= 10
    json.dump(cur, open(os.path.join(a.home, "cursor.json"), "w"))
    r = a.orq("hook", "ask", stdin=_ask(q, {q[0]["question"]: "You have 2 orchestration messages. Run `orca orchestration check`"}))
    assert "suspect answer" in r.stdout and len(_pending(a)["itens"]) == 2
    r = a.orq("hook", "ask", stdin=_ask(q, {q[0]["question"]: "A"}))
    assert (r.returncode, r.stdout) == (0, "") and [i["id"] for i in _pending(a)["itens"]] == ["avisar-x"]


def test_arrival_of_user_or_command_does_not_mark_and_entry_does_not_change():
    a = Env()
    a.prompt("bom dia")
    a.prompt("<command-name>/clear</command-name>")
    assert "chegada" not in _read_state(os.path.join(a.home, "cursor.json"))
    a.prompt("You have 3 orchestration messages")
    assert _read_state(os.path.join(a.home, "cursor.json"))["chegada"]["origem"] == "orca"
    assert [e["id"] for e in orq_mod.open_entries(a.events())] == ["e1"], "notificação continua não virando entrada"


def test_ask_worker_and_exception_exit_with_exit_0():
    a = Env(run=None)
    q = [_question("freio-prod", [("A", "x")])]
    r = a.orq("hook", "ask", stdin=_ask(q, {q[0]["question"]: "A"}))
    assert (r.returncode, r.stdout) == (0, "") and len(_pending(a)["itens"]) == 2 and a.events() == []
    a = Env()
    r = a.orq("hook", "ask", stdin="lixo")
    assert (r.returncode, r.stdout) == (0, "") and "hook ask" in a.log()
    open(a.env["ORQ_PENDENCIAS"], "w").write("{quebrado")
    r = a.orq("hook", "ask", stdin=_ask(q, {q[0]["question"]: "A"}))
    assert r.returncode == 0 and open(a.env["ORQ_PENDENCIAS"]).read() == "{quebrado"


# ---------- fatia 4: orq ingest ----------

FIX = os.path.join(HERE, "fixtures")
REPO_FIX = os.path.join(FIX, "repo")  # sample reports, in the format the automations write to .scratch
REAL_AUDIT = os.path.join(REPO_FIX, ".scratch", "auditoria-diaria", "2026-09-29.md")
REAL_CACHE = os.path.join(REPO_FIX, ".scratch", "acompanhamento-cache", "2026-09-29-manha.md")
SINCE_EARLY = "2026-09-29T00:00:00Z"


def _fix(item_name):
    d = json.load(open(os.path.join(FIX, item_name)))
    if item_name == "automations_runs.json":  # the cited reports live in the fixtures, not in the project's repository
        for r in d["result"]["runs"]:
            if r.get("runContext"):
                r["runContext"]["path"] = REPO_FIX
    return d


def _ingest_env(a, runs=None, inbox=None, since=SINCE_EARLY):
    """Puts the fixtures (or in-memory mutated copies) into the fake Orca and plants the starting cursor (None = first run)."""
    a.set("automations_runs.json", runs if runs is not None else _fix("automations_runs.json"))
    a.set("inbox.json", inbox if inbox is not None else _fix("inbox.json"))
    if since:
        os.makedirs(a.home, exist_ok=True)
        json.dump({"ingest": {"desde": since, "inbox_seq": 0, "runs": []}}, open(os.path.join(a.home, "cursor.json"), "w"))


def _entries(a, origin_name):
    return [e for e in a.events() if e["tipo"] == "entrada" and e["origem"] == origin_name]


def test_action_items_titles_and_formats():
    f = orq_mod.action_items
    new = "# R\n\n## Itens de ação\n\n1. **Um.** detalhe\n2. Dois\n   continuação\n3) Três\n\n## Depois\n\n4. fora\n"
    assert f(new) == ["Um. detalhe", "Dois", "Três"]
    assert f("## O que fazer hoje\n\n1. a\n2. b\n") == ["a", "b"]
    assert f("### O que precisa de ação\n| # | Ação | Número |\n|---|---|---|\n| 1 | Combinar com a Alice | 77 |\n| 2 | Levar o `#101` | 6% |\n\nFecham:\n- x") == ["Combinar com a Alice", "Levar o #101"]
    assert f("# R\n\n## Resumo\n\n1. não é ação\n") is None, "sem a seção"
    assert f("## Itens de ação\n\nnada a fazer\n") is None, "seção sem itens numerados"
    assert len(f("## Itens de ação\n1. " + "x" * 900)[0]) <= 300


def test_items_of_the_example_reports():
    audit_items = orq_mod.action_items(open(REAL_AUDIT).read())
    assert len(audit_items) == 3 and audit_items[0].startswith("Back-merge do `main`".replace("`", "")), audit_items
    cache = orq_mod.action_items(open(REAL_CACHE).read())
    assert len(cache) == 5 and cache[0].startswith("Combinar com a Alice") and cache[1].startswith("Levar o #101"), cache


def test_report_path_in_the_automation_text():
    c = "O relatório está em `.scratch/auditoria-diaria/2026-09-29.md` e o resumo foi salvo."
    assert orq_mod.report_path(c, "/repo") == "/repo/.scratch/auditoria-diaria/2026-09-29.md"
    assert orq_mod.report_path("gravado em /abs/x/.scratch/a/b.md ok", "/repo") == "/abs/x/.scratch/a/b.md"
    assert orq_mod.report_path("sem caminho nenhum", "/repo") is None


def test_ingest_first_run_does_not_dump_the_history():
    a = Env()
    _ingest_env(a, since=None)
    r = a.orq("ingest")
    assert r.returncode == 0, r
    assert a.events() == [], "as fixtures são todas anteriores a 29/09 15:00Z"
    ing = _read_state(os.path.join(a.home, "cursor.json"))["ingest"]
    assert ing["desde"] == "2026-09-29T15:00:00Z", ing
    # whatever is later than the starting point comes in
    runs = _fix("automations_runs.json")
    for r_ in runs["result"]["runs"]:
        r_["createdAt"] = 1790697600000  # 29/09 16:00Z
        if r_.get("outputSnapshot"):
            r_["outputSnapshot"]["capturedAt"] = 1790697660000
    a.set("automations_runs.json", runs)
    assert a.orq("ingest").returncode == 0
    assert len(_entries(a, "relatorio")) == 10, "3 da auditoria + 5 do cache + 1 'ler' de cada Weekday completed (runs 1 e 3), que não citam arquivo"


def test_ingest_run_completed_becomes_one_entry_per_item_with_the_path():
    a = Env()
    _ingest_env(a)
    assert a.orq("ingest").returncode == 0
    rel = _entries(a, "relatorio")
    audit_items = [e for e in rel if e["caminho"] == REAL_AUDIT]
    cache = [e for e in rel if e["caminho"] == REAL_CACHE]
    assert len(audit_items) == 3 and len(cache) == 5, [e["fonte"] for e in rel]
    assert audit_items[0]["fonte"] == "Auditoria diária (demo-app) run 4" and audit_items[0]["ref"] == "99aeaa55-b701-4c22-b99a-66214acd4ac2"
    assert audit_items[0]["item"] == 1 and "Back-merge" in audit_items[0]["texto"]
    assert not [e for e in rel if "run 3" in e["fonte"] or "run 2" in e["fonte"]], "28/09 e run skipped ficam de fora"
    assert [e["id"] for e in orq_mod.open_entries(a.events())] == [e["id"] for e in a.events() if e["tipo"] == "entrada"], "cada item é cobrado pelo Stop"
    n = len(a.events())
    assert a.orq("ingest").returncode == 0 and len(a.events()) == n, "segundo ingest não duplica"
    assert set(_read_state(os.path.join(a.home, "cursor.json"))["ingest"]["runs"]) >= {"99aeaa55-b701-4c22-b99a-66214acd4ac2"}


def test_ingest_report_without_section_or_path_becomes_read_item():
    a = Env()
    runs = _fix("automations_runs.json")
    os.makedirs(os.path.join(a.tmp.name, ".scratch", "x"))
    without_section = os.path.join(a.tmp.name, ".scratch", "x", "solto.md")
    open(without_section, "w").write("# Solto\n\n## Resumo\n\n1. isto não é seção de ação\n")
    ok = [r for r in runs["result"]["runs"] if r["status"] == "completed" and r["createdAt"] > 1790600000000]
    ok[0]["outputSnapshot"]["content"] = f"O relatório está em `{without_section}`."
    ok[1]["outputSnapshot"]["content"] = "Terminei, mas não gravei arquivo nenhum."
    runs["result"]["runs"] = ok
    _ingest_env(a, runs=runs)
    a.orq("ingest")
    rel = _entries(a, "relatorio")
    assert len(rel) == 2
    by_ref = {e["ref"]: e for e in rel}
    assert by_ref[ok[0]["id"]]["texto"].endswith("read solto.md") and by_ref[ok[0]["id"]]["caminho"] == without_section
    assert "read" in by_ref[ok[1]["id"]]["texto"] and not by_ref[ok[1]["id"]].get("caminho")


def test_ingest_run_in_progress_waits_and_enters_when_complete():
    a = Env()
    runs = _fix("automations_runs.json")
    runs["result"]["runs"] = [r for r in runs["result"]["runs"] if r["runNumber"] == 4 and r["title"].startswith("Auditoria")]
    runs["result"]["runs"][0]["status"] = "running"
    _ingest_env(a, runs=runs)
    a.orq("ingest")
    assert _entries(a, "relatorio") == []
    runs["result"]["runs"][0]["status"] = "completed"
    a.set("automations_runs.json", runs)
    a.orq("ingest")
    assert len(_entries(a, "relatorio")) == 3


