def _scout(a, title):
    a.set("tasks_run_44769cae0dc5.json", [{"id": "task_59149fb97408", "status": "completed", "task_title": title,
                                           "created_at": "2026-09-29T13:00:00Z"},
                                          {"id": "task_d23305d9dca3", "status": "completed", "task_title": "[scout] com relatório",
                                           "created_at": "2026-09-29T13:00:00Z"}])


def test_scout_without_reportpath_becomes_alert_in_summary():
    a = Env()
    _ingest_env(a)
    _scout(a, "[scout] Diagnosticar failover")
    a.orq("ingest")
    (al,) = [e for e in a.events() if e["tipo"] == "alerta"]
    assert al["alerta"] == "scout_sem_relatorio" and al["task"] == "task_59149fb97408" and al["run"] == "run_44769cae0dc5"
    assert not [e for e in a.events() if e["tipo"] == "alerta" and e["task"] == "task_d23305d9dca3"], "scout com reportPath não alerta"
    assert not [e for e in a.events() if e["tipo"] == "alerta" and e["task"] == "task_10c7b0acb36e"], "ship sem reportPath é normal"
    ctx = json.loads(a.prompt("oi").stdout)["hookSpecificOutput"]["additionalContext"]
    assert "Alert: scout 'Diagnosticar failover'" in ctx and len(ctx.splitlines()) <= 5, ctx
    n = len(a.events())
    a.orq("ingest")
    assert len(a.events()) == n
    # without [scout] in the title it doesn't alert
    b = Env()
    _ingest_env(b)
    _scout(b, "Implementar failover")
    b.orq("ingest")
    assert not [e for e in b.events() if e["tipo"] == "alerta"]


def test_scout_alert_expires_in_24h():
    from datetime import datetime, timezone
    ev = [{"ts": "2026-09-28T10:00:00Z", "tipo": "alerta", "alerta": "scout_sem_relatorio", "task": "t", "titulo": "[scout] velho"}]
    assert "Alert:" not in orq_mod.summary(ev, None, None, now_at=datetime(2026, 9, 29, 12, 0, tzinfo=timezone.utc))
    assert "Alert:" in orq_mod.summary(ev, None, None, now_at=datetime(2026, 9, 28, 20, 0, tzinfo=timezone.utc))


def test_summary_with_reports_alert_and_suspect_fits_in_5_lines():
    from datetime import datetime, timezone
    ev = []
    for i in range(1, 13):
        ev.append({"tipo": "entrada", "origem": "usuario", "id": f"e{i}", "texto": "mensagem longa " + "x" * 200})
    for i in range(13, 21):
        ev.append({"tipo": "entrada", "origem": "relatorio", "id": f"e{i}", "texto": "item", "fonte": "Auditoria diária (demo-app) run 4" if i < 17 else "Acompanhamento de cache run 9",
                   "caminho": "/r/.scratch/auditoria-diaria/2026-09-29.md"})
    ev.append({"tipo": "entrada", "origem": "relatorio_worker", "id": "e21", "texto": "Escritas no banco secundário: a plataforma não escreve", "fonte": "worker Escritas no banco secundário",
               "caminho": "docs/research/x.md"})
    ev.append({"ts": "2026-09-29T12:00:00Z", "tipo": "alerta", "alerta": "scout_sem_relatorio", "task": "task_1234567890", "titulo": "[scout] " + "y" * 200})
    ev.append({"tipo": "resposta_suspeita", "header": "freio-prod"})
    ctx = orq_mod.summary(ev, None, {"itens": []}, {"id": "e12"}, now_at=datetime(2026, 9, 29, 13, 0, tzinfo=timezone.utc))
    line_list = ctx.splitlines()
    assert len(line_list) <= 5 and all(len(l) <= 500 for l in line_list), ctx
    extra = [l for l in line_list if "Reports not triaged" in l]
    assert extra and "suspect answer in freio-prod" in extra[0] and "Alert: scout" in extra[0], ctx
    assert "Auditoria diária" in extra[0] and "×4" in extra[0] and "e13-e16" in extra[0], extra
    assert "worker_done with report ×1 [e21] research/x.md" in extra[0], extra
    assert "No effect:" in line_list[0] and "e13" not in line_list[0], "l1 é só das mensagens do usuário"
    # only open reports: l1 doesn't say "none" misleadingly
    only_rel = [e for e in ev if e.get("origem") in ("relatorio",)]
    assert "Reports not triaged" in orq_mod.summary(only_rel, None, None)


def test_hook_prompt_triggers_ingest_in_background():
    a = Env()
    a.env.pop("ORQ_NO_BG")
    _ingest_env(a)
    a.set("runs.json", [])
    a.prompt("bom dia")
    for _ in range(50):
        if len(_entries(a, "relatorio")) == 8 and len(_entries(a, "relatorio_worker")) == 2:
            break
        time.sleep(0.1)
    assert len(_entries(a, "relatorio")) == 8 and len(_entries(a, "relatorio_worker")) == 2
    ctx = json.loads(a.prompt("e agora").stdout)["hookSpecificOutput"]["additionalContext"]
    assert "Reports not triaged" in ctx and len(ctx.splitlines()) <= 5, ctx


def test_ingest_fails_open_and_one_source_does_not_take_down_the_other():
    a = Env()
    _ingest_env(a)
    r = a.orq("ingest", FAKE_FAIL="inbox")
    assert r.returncode == 0 and "ingest inbox" in a.log()
    assert len(_entries(a, "relatorio")) == 8 and not _entries(a, "relatorio_worker")
    r = a.orq("ingest", FAKE_FAIL="runs")
    assert r.returncode == 0 and "ingest automations" in a.log()
    assert len(_entries(a, "relatorio_worker")) == 2, "a inbox segue mesmo com as automations fora"
    assert Env(FAKE_CRASH="1").orq("ingest", FAKE_CRASH="1").returncode == 0


def test_ingest_two_at_the_same_time_do_not_duplicate():
    a = Env()
    _ingest_env(a)
    with ThreadPoolExecutor(4) as ex:
        list(ex.map(lambda _: a.orq("ingest"), range(4)))
    assert len(_entries(a, "relatorio")) == 8 and len(_entries(a, "relatorio_worker")) == 2


def test_unreadable_report_does_not_break_the_ingest():
    a = Env()
    runs = _fix("automations_runs.json")
    ok = [r for r in runs["result"]["runs"] if r["status"] == "completed" and r["createdAt"] > 1790600000000]
    ok[0]["outputSnapshot"]["content"] = "O relatório está em `.scratch/nao/existe.md`."
    runs["result"]["runs"] = ok
    _ingest_env(a, runs=runs)
    assert a.orq("ingest").returncode == 0
    rel = [e for e in _entries(a, "relatorio") if e["ref"] == ok[0]["id"]]
    assert len(rel) == 1 and "read existe.md" in rel[0]["texto"]


def _steer_env(a):
    a.set("tasks_run_a.json", [{"id": "task_rodando", "status": "dispatched", "dispatch_id": "ctx_1"},
                               {"id": "task_parada", "status": "ready", "dispatch_id": None},
                               {"id": "task_feita", "status": "completed", "dispatch_id": "ctx_0"}])
    a.set("tasks_run_b.json", [{"id": "task_b", "status": "dispatched", "dispatch_id": "ctx_2"}])
    return a.prompt("ajusta o worker")


def _sent(a):
    try:
        return [json.loads(x) for x in open(os.path.join(a.fake, "sent.log"))]
    except OSError:
        return []


def test_steer_sends_the_send_and_writes_the_event_and_the_intake():
    a = Env()
    _steer_env(a)
    r = a.orq("steer", "task_rodando", "use o índice novo", "--entrada", "e1")
    assert r.returncode == 0, r.stderr
    assert _sent(a) == [["send", "--run", "run_a", "--to", "dispatch:ctx_1", "--subject", "Adjustment",
                             "--body", "use o índice novo\n\n## User request (addition)\najusta o worker", "--priority", "high", "--json"]]
    ev = [e for e in a.events() if e["tipo"] == "steer"]
    assert len(ev) == 1 and (ev[0]["task"], ev[0]["dispatch"], ev[0]["run"], ev[0]["texto"], ev[0]["msg_id"]) == \
        ("task_rodando", "ctx_1", "run_a", "use o índice novo", "msg_9")
    ints = [e for e in a.events() if e["tipo"] == "intake"]
    assert len(ints) == 1 and ints[0]["entrada"] == "e1" and ints[0]["efeito"] == "steer" and ints[0]["ref"] == "task_rodando"


def test_steer_without_entry_writes_implicit_intake_of_the_only_open_entry():
    a = Env()
    _steer_env(a)  # deixa a entrada e1 aberta
    r = a.orq("steer", "task_rodando", "oi")
    assert r.returncode == 0 and len(_sent(a)) == 1
    (i,) = [e for e in a.events() if e["tipo"] == "intake"]
    assert (i["entrada"], i["efeito"], i["ref"], i["run"]) == ("e1", "steer", "task_rodando", "run_a") and "(implicit)" in r.stderr


def test_steer_refuses_task_that_is_not_dispatched_or_does_not_exist():
    a = Env()
    _steer_env(a)
    for t in ("task_parada", "task_feita", "task_fantasma"):
        r = a.orq("steer", t, "oi")
        assert r.returncode == 1 and "orq:" in r.stderr, t
    assert "dispatched" in a.orq("steer", "task_parada", "oi").stderr
    assert not _sent(a) and not [e for e in a.events() if e["tipo"] == "steer"]


def test_steer_in_other_run_links_the_run_by_itself_and_relinks_the_previous():
    a = Env()
    _steer_env(a)
    r = a.orq("steer", "task_b", "oi", "--run", "run_b")
    assert r.returncode == 0, r.stderr
    assert len(_sent(a)) == 1 and [e["task"] for e in a.events() if e["tipo"] == "steer"] == ["task_b"]
    assert json.load(open(os.path.join(a.fake, "run.json")))["id"] == "run_a", "o Run que estava ligado volta"
    without = Env(run=None)  # no Run attached: orq attaches the task's one and nothing needs to come back
    _steer_env(without)
    r = without.orq("steer", "task_rodando", "oi", "--run", "run_a")
    assert r.returncode == 0, r.stderr
    assert len(_sent(without)) == 1


