    ids = [e["id"] for e in a.events() if e["tipo"] == "entrada"]
    assert ids == ["e1", "e2", "e3"], ids
    assert [e["id"] for e in orq_mod.open_entries(a.events())] == ["e3"], "o intake antigo de e1 não pode fechar a entrada nova"
    a.prompt("quarta")
