    assert len(rel) == 1 and "read binario.md" in rel[0]["texto"], "relatório que não é UTF-8 vira o item 'ler'"
    assert _cursor(a)["ingest"]["inbox_seq"] == 933
    size = len(open(a.env["ORQ_LOG"]).read())
    a.orq("ingest")
    assert len(open(a.env["ORQ_LOG"]).read()) == size, "o cursor avançou: o veneno não volta a cada ingest"


