    assert r.returncode == 0, r.stderr
    assert _gates(a) == [["gate-create", "--task", "task_1", "--question", "Sobe o freio?", "--json"]]
    assert next(i for i in _pending(a)["itens"] if i["id"] == "gate-dec")["gate"] == "gate_1"
