def test_review3_b8_worker_done_group_shows_report_count_and_the_newest():
    from datetime import datetime, timezone
    now_at = datetime.now(timezone.utc)

    def entries(*names):
        return [{"tipo": "entrada", "id": f"e{i}", "origem": "relatorio_worker", "texto": "x", "fonte": "worker x",
                 "caminho": f"/r/orquestrador-plan/{n}.md", "ref": f"m{i}"} for i, n in enumerate(names, 3)]
    ev = entries("a", "b", "c", "d", "e")
