def _orca_direct(a, *args):
    p = subprocess.run([a.bin, "orchestration", *args, "--json"], capture_output=True, text=True, env=a.env)
    return json.loads(p.stdout)


def test_review3_b9_fake_orca_refuses_gate_resolve_from_other_run_as_unknown_and_gives_one_id_per_gate():
    a = Env(run="run_a")
    g1 = _orca_direct(a, "gate-create", "--task", "t1", "--question", "q")["result"]["gate"]
    g2 = _orca_direct(a, "gate-create", "--task", "t2", "--question", "q")["result"]["gate"]
    assert g1["id"] != g2["id"] and g1["run_id"] == "run_a" and g1["created_at"][4] == "-" and " " in g1["created_at"]
    assert _orca_direct(a, "gate-resolve", "--id", g1["id"], "--resolution", "x")["ok"] is True
    a.set("run.json", {"id": "run_b"})
    r = _orca_direct(a, "gate-resolve", "--id", g2["id"], "--resolution", "x")
    assert r["ok"] is False and "Gate not found" in r["error"]["message"], r
    assert _orca_direct(a, "gate-resolve", "--id", "gate_999", "--resolution", "x")["ok"] is False
    a.set("run.json", {"id": "run_a"})
    assert _orca_direct(a, "gate-resolve", "--id", g2["id"], "--resolution", "x")["ok"] is True


def test_review3_b10_marked_option_note_is_free_answer():
    a = Env()
    q = _gate_pending(a, "dec1")
    ev = json.loads(_ask(q, {q[0]["question"]: "Sim"}))
    ev["tool_response"]["annotations"] = {q[0]["question"]: {"notes": "só se o deploy passar"}}
    r = a.orq("hook", "ask", stdin=json.dumps(ev))
    assert "dec1" in _pending_ids(a) and not _calls(a, "gate-resolve"), "a nota impede o fechamento"
    (res,) = [e for e in a.events() if e["tipo"] == "resposta"]
    assert res["livre"] is True and res["nota"] == "só se o deploy passar" and res["resposta"] == "Sim", res
    assert 'orq pend done dec1 --answer "<what was decided>"' in json.loads(r.stdout)["hookSpecificOutput"]["additionalContext"]
    a.orq("pend", "done", "dec1")
    (res,) = _resolutions(a)
    assert "Sim" in res and "só se o deploy passar" in res, res
    b = Env()  # annotation without notes (preview only) is the clean option: it closes
    q = _gate_pending(b, "dec2")
    ev = json.loads(_ask(q, {q[0]["question"]: "Sim"}))
    ev["tool_response"]["annotations"] = {q[0]["question"]: {"preview": "x"}}
    b.orq("hook", "ask", stdin=json.dumps(ev))
    assert "dec2" not in _pending_ids(b) and _resolutions(b) == ["Sim"]
    c = Env()  # and the note also counts when the harness puts it in tool_input
    q = _gate_pending(c, "dec3")
    ev = json.loads(_ask(q, {q[0]["question"]: "Sim"}, where="tool_input"))
    ev["tool_input"]["annotations"] = {q[0]["question"]: {"notes": "depois"}}
    c.orq("hook", "ask", stdin=json.dumps(ev))
    assert "dec3" in _pending_ids(c)


# ---------- decision channel through Lavish (section 16 of the design) ----------

def _lote(a, item_list, item_name="poll.json", shape="data"):
    path = os.path.join(a.tmp.name, item_name)
    doc = {"data": {"items": item_list}} if shape == "data" else {"prompts": [{"tag": "tracked-batch", "data": {"items": item_list}}]} \
        if shape == "prompts" else [{"tag": "tracked-batch", "data": {"items": item_list}}]
    json.dump(doc, open(path, "w"))
    return path


def test_lavish_answer_writes_one_event_per_item_and_closes_only_the_explicit_choice():
    a = Env()
    a.orq("pend", "add", "--id", "Indicador", "--tipo", "decisao", "--titulo", "Qual badge?", "--task", "task_1")
    item_list = [{"id": "L1", "header": "freio-prod", "resposta": "Sem freio", "disposicao": "escolha"},
             {"id": "L2", "header": "Indicador", "resposta": "quero ver o protótipo antes", "disposicao": "livre"},
             {"id": "L3", "header": "sem-pendencia", "resposta": "A", "disposicao": "escolha"},
             {"id": "L4", "header": "avisar-x", "resposta": "ok", "disposicao": "escolha"},
             {"id": "L5", "header": "", "resposta": "", "disposicao": "adiar"}]
    file_path = _lote(a, item_list)
    r = a.orq("lavish-resposta", file_path)
    assert r.returncode == 0, r.stderr
    evs = [e for e in a.events() if e["tipo"] == "resposta_lavish"]
    assert [e["item"] for e in evs] == ["L1", "L2", "L3", "L4", "L5"], "um evento por item"
    assert evs[0]["header"] == "freio-prod" and evs[0]["resposta"] == "Sem freio" and evs[0]["disposicao"] == "escolha" and "livre" not in evs[0]
    assert evs[1]["livre"] is True and evs[4]["livre"] is True
    assert sorted(_pending_ids(a)) == ["Indicador", "avisar-x"], "só a decisão com escolha explícita fecha; ação/aviso e texto livre não"
    (done,) = [e for e in a.events() if e["tipo"] == "pend" and e["op"] == "done"]
    assert done["pend"] == "freio-prod" and done["resposta"] == "Sem freio"
    assert 'orq pend done Indicador --answer "<what was decided>"' in r.stdout + r.stderr, "o aviso de resposta livre"
    output = json.loads(r.stdout)
    assert [i["item"] for i in output["itens"]] == ["L1", "L2", "L3", "L4", "L5"] and output["itens"][0]["efeito"] == "fechou"
    ctx = json.loads(a.prompt("e o Indicador?").stdout)["hookSpecificOutput"]["additionalContext"]
    assert 'free-text answer in Indicador: if decided, close it with orq pend done Indicador --answer' in ctx, ctx
    n = len(a.events())
    assert a.orq("lavish-resposta", file_path).returncode == 0 and len(a.events()) == n
    assert len([e for e in a.events() if e["tipo"] == "resposta_lavish"]) == 5, "o mesmo lote duas vezes não duplica"
    r = a.orq("lavish-resposta", _lote(a, [{"id": "L6", "header": "Indicador", "resposta": "A: badge", "disposicao": "escolha"}], "p2.json", "prompts"))
    assert r.returncode == 0 and "Indicador" not in _pending_ids(a), r.stderr
    assert _resolutions(a) == ["A: badge"], "a escolha resolve o gate da decisão"
    assert "free-text answer" not in json.loads(a.prompt("fechou?").stdout)["hookSpecificOutput"]["additionalContext"]


def test_lavish_answer_accepts_the_three_json_forms_and_refuses_what_is_not_a_batch():
    a = Env()
    for i, shape in enumerate(("data", "prompts", "lista")):
        file_path = _lote(a, [{"id": f"F{i}", "header": "x", "resposta": "y", "disposicao": "escolha"}], f"f{i}.json", shape)
        assert a.orq("lavish-resposta", file_path).returncode == 0, shape
    assert [e["item"] for e in a.events() if e["tipo"] == "resposta_lavish"] == ["F0", "F1", "F2"]
    n = len(a.events())
    empty = os.path.join(a.tmp.name, "vazio.json")
    open(empty, "w").write('{"data": {"items": []}}')
    bad = os.path.join(a.tmp.name, "ruim.json")
    open(bad, "w").write("{quebrado")
    for file_path in (empty, bad, os.path.join(a.tmp.name, "nao-existe.json")):
        r = a.orq("lavish-resposta", file_path)
        assert r.returncode == 1 and "orq:" in r.stderr, (file_path, r)
    assert len(a.events()) == n


