def test_ticket100_gate_refused_leaves_the_decision_open_and_the_second_round_closes():
    a = Env()
    _gate_pending(a)
    file_path = _lote(a, [{"id": "L1", "header": "gate-dec", "resposta": "Sim", "disposicao": "escolha"}])
