    assert "gate-dec" in _pending_ids(a) and not [e for e in a.events() if e["tipo"] == "resposta_lavish"]
    r = a.orq("lavish-resposta", file_path)
    assert json.loads(r.stdout)["itens"][0]["efeito"] == "fechou" and "gate-dec" not in _pending_ids(a), r


