# ---------- AskUserQuestion PreToolUse hook (section 16) ----------

def _guard(a, tool="AskUserQuestion", **env):
    return a.orq("hook", "guard", stdin=json.dumps({"session_id": "abcdef123456", "hook_event_name": "PreToolUse", "tool_name": tool,
                                                      "tool_input": {"questions": []}}), **env)


def _workers(a, *line_list):
    a.set("workers.json", [{"handle": h, "run": r, "status": s} for h, r, s in line_list])


def test_guard_refuses_the_box_with_active_dispatch_in_any_run():
    a = Env(run="run_a")
    _workers(a, ("w_ativo", "run_b", "dispatched"), ("w_velho", "run_a", "completed"))  # the active one is in a different Run than the bound one
    t = time.time()
    r = _guard(a)
    assert r.returncode == 0 and time.time() - t < 2, r
    out = json.loads(r.stdout)["hookSpecificOutput"]
    assert out["hookEventName"] == "PreToolUse" and out["permissionDecision"] == "deny"
    reason = out["permissionDecisionReason"]
    assert "Lavish" in reason and "orq lavish-answer" in reason and "1 active dispatch" in reason and "run_b" in reason, reason
    listing = _calls(a, "worker-list")
    assert listing and "--run" not in listing[0], "lista de todos os Runs: o worker-list escopado só veria o Run ligado"


def test_guard_releases_without_active_dispatch_and_outside_orca():
    a = Env(run="run_a")
    _workers(a, ("w1", "run_a", "completed"), ("w2", "run_b", "failed"))
    r = _guard(a)
    assert (r.returncode, r.stdout) == (0, ""), r
    b = Env(run="run_a")
    _workers(b, ("w1", "run_b", "dispatched"))
    b.prompt(PREAMBLE)  # this session is a worker's
    assert "deny" in _guard(b).stdout and _calls(b, "worker-list") == [], "worker não usa a caixa (ticket 52: escala pelo Orca) e nem chama o Orca"
    c = Env(run="run_a")
    _workers(c, ("w1", "run_b", "dispatched"))
    r = _guard(c, ORCA_TERMINAL_HANDLE="")
    assert (r.returncode, r.stdout, _post_dispatch_no_binding(c)) == (0, "", [])
    d = Env(run="run_a")
    _workers(d, ("w1", "run_b", "dispatched"))
    assert _guard(d, tool="Bash").stdout == ""
    e = Env(run=None)  # without a bound Run it is not a coordinator
    _workers(e, ("w1", "run_b", "dispatched"))
    assert _guard(e).stdout == ""


def test_guard_fails_open_and_logs():
    a = Env(run="run_a")
    _workers(a, ("w1", "run_b", "dispatched"))
    r = _guard(a, FAKE_CRASH="1")
    assert (r.returncode, r.stdout) == (0, "") and "hook guard" in a.log(), (r, a.log())
    b = Env(run="run_a")
    _workers(b, ("w1", "run_b", "dispatched"))
    t = time.time()
    r = _guard(b, FAKE_SLEEP="30")  # far beyond the 3 s alarm, so the ceiling holds under load (ticket 328)
    assert (r.returncode, r.stdout) == (0, "") and time.time() - t < 9 and "hook guard" in b.log()
    c = Env(run="run_a")
    _workers(c, ("w1", "run_b", "dispatched"))
    c.env["ORQ_ORCA"] = "/nao/existe/orca"
    r = _guard(c)
    assert (r.returncode, r.stdout) == (0, "") and "hook guard: FileNotFoundError" in c.log()
    d = Env(run="run_a")
    r = d.orq("hook", "guard", stdin="isto não é json")
    assert (r.returncode, r.stdout) == (0, "") and "hook guard" in d.log()


def test_guard_short_cache_avoids_repeating_the_list_and_expires():
    a = Env(run="run_a")
    _workers(a, ("w1", "run_b", "dispatched"))
    assert "deny" in _guard(a).stdout and "deny" in _guard(a).stdout
    assert len(_calls(a, "worker-list")) == 1, "a segunda caixa lê o cache"
    cache = os.path.join(a.home, "active.json")
    c = json.load(open(cache))
    c["t"] -= orq_mod.ASK_GUARD_TTL + 1
    json.dump(c, open(cache, "w"))
    _workers(a)  # o worker terminou
    assert _guard(a).stdout == "" and len(_calls(a, "worker-list")) == 2


def test_guard_reads_the_second_page_and_the_off_file_releases():
    a = Env(run="run_a")
    _workers(a, *[(f"w{i}", "run_b", "completed") for i in range(120)], ("w_ativo", "run_c", "dispatched"))
    r = _guard(a)
    assert "deny" in r.stdout and "run_c" in r.stdout and len(_calls(a, "worker-list")) == 2, r
    os.remove(os.path.join(a.home, "active.json"))
    open(os.path.join(a.home, "ask-guard.off"), "w").close()  # escape hatch: a stuck dispatch that never finishes
    assert _guard(a).stdout == ""



# ---------- heartbeat absorvido (fatia 7) ----------

NOTICE_A = "You have 1 orchestration message. Run `orca orchestration check --run run_a`."


def _no_tip(output):
    """What the prompt hook let through without the `orq inbox <run> --ack` hint it adds to the notice from another Run (ticket 140): "" when there was only the hint."""
    if not (output or "").strip():
        return ""
    ctx = json.loads(output).get("hookSpecificOutput", {}).get("additionalContext", "")
    rest = [l for l in ctx.splitlines() if not l.startswith("orq: read the inbox with `orq inbox ")]
    return "\n".join(rest)


def _hook_ctx(r):
    """The additionalContext of the prompt hook ("" with no output)."""
    return json.loads(r.stdout)["hookSpecificOutput"]["additionalContext"] if (r.stdout or "").strip() else ""


def _hb(phase, dispatch="ctx_1", task="task_1"):
    return ("heartbeat", {"taskId": task, "dispatchId": dispatch, "phase": phase})


def _check_calls(a):
    return _calls(a, "check")


def _blocked(r):
    return r.returncode == 0 and json.loads(r.stdout).get("decision") == "block"


def test_heartbeat_only_heartbeats_blocks_and_confirms():
    a = Env()
    a.inbox(_hb("lendo"), _hb("testando"))
    r = a.prompt(NOTICE_A)
    out = json.loads(r.stdout)
    assert _blocked(r) and out["reason"] == f"{orq_mod.MARK} 2 heartbeats absorbed (run_a)" and "\n" not in out["reason"] and "hookSpecificOutput" not in out, r
    assert set(a.states().values()) == {"acked"}, "consumiu e confirmou o lote"
    calls = _check_calls(a)
    assert [("--peek" in c, "--ack" in c) for c in calls] == [(True, False), (False, False), (False, True)], calls
    assert a.log() == ""


def test_heartbeat_writes_the_event_with_run_ids_and_phase_of_each():
    a = Env()
    a.inbox(_hb("lendo", "ctx_1", "task_1"), _hb("testando", "ctx_2", "task_2"))
    assert _blocked(a.prompt(NOTICE_A))
    (ev,) = [e for e in a.events() if e["tipo"] == "heartbeat_absorvido"]
    assert ev["run"] == "run_a" and ev["entregas"] == ["delivery_1"]
    assert [(h["msg"], h["task"], h["dispatch"], h["fase"]) for h in ev["heartbeats"]] == [
        ("msg_1", "task_1", "ctx_1", "lendo"), ("msg_2", "task_2", "ctx_2", "testando")]
    assert all(h["ts"].startswith("2026-09-29T17:3") for h in ev["heartbeats"])
    assert not any(e["tipo"] == "entrada" for e in a.events()), "absorvido não vira entrada nem ingest"


def test_heartbeat_mixed_passes_and_the_hook_reads_and_confirms():
    a = Env()
    a.inbox(_hb("lendo"), ("worker_done", {"taskId": "task_1"}))
    r = a.prompt(NOTICE_A)
    assert r.returncode == 0 and "msg_2 worker_done" in _hook_ctx(r), r
    assert set(a.states().values()) == {"acked"}, "ticket 182: the hook reads and confirms the mixed inbox"
    assert "--peek" in _check_calls(a)[0], "looked with --peek before reading"
    assert not [e for e in a.events() if e["tipo"] == "heartbeat_absorvido"]
    assert _read_state(os.path.join(a.home, "cursor.json"))["chegada"]["origem"] == "orca", "o aviso segue o caminho de sempre"


