WAITER = os.path.join(HERE, "scripts", "orca-wait-runs.py")


def _waiter(a, *runs):
    return subprocess.run([sys.executable, WAITER, *runs], capture_output=True, text=True, timeout=30,
                          env={**a.env, "ORQ_WAIT_POLL": "0.05", "ORQ_WAIT_MAX": "0.4"})


def _pure_check(a, *args):
    r = subprocess.run([a.bin, "orchestration", "check", "--run", "run_a", *args, "--json"], capture_output=True, text=True, env=a.env)
    return json.loads(r.stdout)


def test_waiter_confirms_heartbeat_writes_event_and_keeps_waiting():
    a = Env()
    a.inbox(_hb("lendo"), _hb("testando"))
    r = _waiter(a)
    assert r.returncode == 0 and json.loads(r.stdout) == {"timeout": True}, r
    assert set(a.states().values()) == {"acked"}
    (ev,) = [e for e in a.events() if e["tipo"] == "heartbeat_absorvido"]
    assert [h["fase"] for h in ev["heartbeats"]] == ["lendo", "testando"]


def test_waiter_confirms_the_heartbeat_and_prints_worker_done_in_same_round():
    a = Env()
    a.inbox(_hb("lendo"), ("worker_done", {"taskId": "t"}))
    r = _waiter(a)
    out = json.loads(r.stdout)
    assert out["run"] == "run_a" and [m["type"] for m in out["messages"]] == ["worker_done"], r
    assert a.states() == {"msg_1": "acked", "msg_2": "out"}, "worker_done impresso e sem ack: o check do coordenador o repete"
    assert _pure_check(a)["result"]["messages"][0]["id"] == "msg_2", "e o check do coordenador o recebe"


def test_waiter_and_hook_together_do_not_double_ack_nor_lose_message():
    a = Env()
    a.inbox(_hb("lendo"))
    d = _pure_check(a)["result"]["deliveryId"]  # the waiter consumed the batch and has not confirmed yet
    assert _blocked(a.prompt(NOTICE_A)), "o hook pega a mesma entrega (repetida) e confirma"
    a.inbox(("worker_done", {"taskId": "t"}))  # arrives later
    late = _pure_check(a, "--ack", d)  # the waiter's late ack, from the same batch
    assert late["ok"] and late["result"]["acknowledged"] == d, "confirmar de novo o mesmo lote é inofensivo"
    assert [m["id"] for m in late["result"]["messages"]] == ["msg_2"], "e devolve o worker_done, que continua para o coordenador"
    assert a.states() == {"msg_1": "acked", "msg_2": "out"}, "o ack repetido não confirmou o lote seguinte"
    r = _waiter(a)
    assert [m["id"] for m in json.loads(r.stdout)["messages"]] == ["msg_2"], "a mensagem não se perdeu"


def test_waiter_without_orq_confirms_alone_as_before():
    a = Env()
    a.inbox(_hb("lendo"))
    env = {**a.env, "ORQ_WAIT_POLL": "0.05", "ORQ_WAIT_MAX": "0.3", "PYTHONPATH": ""}
