    p = os.path.join(a.tmp.name, "w.py")
    open(p, "w").write(src)
    r = subprocess.run([sys.executable, p], capture_output=True, text=True, timeout=30, env=env)
    assert a.states() == {"msg_1": "acked"}, r.stdout


