# ---- A2: automation report ----

def _iso_min(minutes_elapsed):
    return (time.time() - minutes_elapsed * 60) * 1000


def _run_cache(a, created_min=10, snapshot=True, content=None, base=REPO_FIX, plantar=True):
    """The sample run of the cache automation, with the timestamps shifted to now and the report pointing to the fixtures."""
    r = json.load(open(os.path.join(FIX, "automation-run-cache.json")))
    r["createdAt"] = _iso_min(created_min)
    r["runContext"]["path"] = base
    if snapshot:
        r["outputSnapshot"]["capturedAt"] = _iso_min(max(created_min - 8, 0))
        if content is not None:
            r["outputSnapshot"]["content"] = content
    else:
        r.pop("outputSnapshot", None)
    runs = {"ok": True, "result": {"runs": [r]}}
    if plantar:
        _ingest_env(a, runs=runs, inbox={"ok": True, "result": {"messages": []}})
    else:  # the same run seen again, with the cursor and the log as they are
        a.set("automations_runs.json", runs)
    return r


AFTERNOON = os.path.join(REPO_FIX, ".scratch", "acompanhamento-cache", "2026-09-29-tarde.md")


def test_review4_a2_run_completed_without_snapshot_waits_and_enters_with_six_items_once_only():
    a = Env()
    r = _run_cache(a, snapshot=False)
    assert a.orq("ingest").returncode == 0
    assert _entries(a, "relatorio") == []
    ing = _cursor(a)["ingest"]
    assert r["id"] not in ing["runs"] and "auto_desde" not in ing, "run sem snapshot ainda não terminou: não é visto e não segura o resto"
    r2 = _run_cache(a, plantar=False)  # o agente terminou e o Orca capturou o resultado
    a.orq("ingest")
    rel = _entries(a, "relatorio")
    assert len(rel) == 6 and {e["caminho"] for e in rel} == {AFTERNOON} and rel[0]["texto"].startswith("Decidir o que fazer com a janela de promoção"), rel
    n = len(a.events())
    a.orq("ingest")
    a.orq("ingest")
    assert len(a.events()) == n, "seis itens uma vez só"
    assert r2["id"] in _cursor(a)["ingest"]["runs"]


