def test_agents_does_not_list_as_delivered_the_already_released_nor_the_terminal_less():
    a = Env(run="run_a")
    _agents_env(a)
    ws = json.load(open(os.path.join(a.fake, "workers.json")))
    ws.append({"handle": "term_e2", "run": "run_b", "task": "task_e2", "status": "completed", "terminal": "retained"})  # already went through orq liberar
    ws.append({"handle": "term_e3", "run": "run_b", "task": "task_e3", "status": "completed", "terminal": "retained"})  # terminal closed by hand
    a.set("workers.json", ws)
    a.set("terminals.json", ["term_r1", "term_t1", "term_q1", "term_e1", "term_e2"])
    os.makedirs(a.home, exist_ok=True)
    open(os.path.join(a.home, "events.jsonl"), "w").write(json.dumps({"tipo": "liberar", "dispatch": "ctx_term_e2", "fechado": True}) + "\n")
    agent_row = _agents(a)
    assert {d for d, x in agent_row.items() if x["estado"] == "entregue"} == {"ctx_term_e1"}, agent_row
    include_all = _agents(a, "--todos")
    assert include_all["ctx_term_e2"]["estado"] == "liberado" and include_all["ctx_term_e3"]["estado"] == "liberado"
    a.set("runs.json", [{"id": "run_a", "objective": "A"}, {"id": "run_b", "objective": "B"}])
    a.orq("ingest", "--refresh")
    cache = _read_state(os.path.join(a.home, "aberto.json"))["agentes"]
    assert sum(x["estado"] == "entregue" for x in cache) == 1, "o contador do resumo bate com a lista"


