def test_guard_of_worker_routing_covers_orq_dispatch():
    guard = os.path.join(HERE, "hooks", "worker-routing-guard.py")

    def run_cmd(cmd):
        r = subprocess.run([sys.executable, guard], input=json.dumps({"tool_name": "Bash", "tool_input": {"command": cmd}}), capture_output=True, text=True)
        return json.loads(r.stdout)["hookSpecificOutput"]["permissionDecision"] if r.stdout.strip() else "allow"

    assert run_cmd("orq despachar --run r --titulo T --spec-arquivo f --effort low") == "deny"
    assert run_cmd("orq despachar --run r --titulo T --spec-arquivo f --modelo m") == "deny"
    assert run_cmd("orq despachar --run r --titulo T --spec-arquivo f --modelo m --effort low") == "allow"
    assert run_cmd("orca orchestration worker-start --spec x") == "deny", "o guard antigo continua valendo"
    assert run_cmd("orq agentes --json") == "allow"
    assert run_cmd("python3 ~/.claude/orq/orq.py despachar --run r --titulo T --spec-arquivo f") == "deny"
    assert run_cmd("cd /tmp && orq despachar --run r --titulo T --spec-arquivo f --effort low") == "deny"
    assert run_cmd('orca orchestration send --type worker_done --body "usei o orq despachar e o orq liberar"') == "allow", "citar o comando num texto não é despachar"



# ---- a heartbeat from another Run does not wake the coordinator either (user request, slice 8) ----

NOTICE_B = "You have 1 orchestration message. Run `orca orchestration check --run run_b`."


def _hb_inbox(a, dispatch, phase, delta, seq, run="run_b", type_name="heartbeat"):
    """Inbox message of a Run the coordinator does not coordinate: to_handle run:<r>, Orca payload."""
    m = _hbi(seq, dispatch, phase, delta, run)
    return {**m, "type": type_name, "to_handle": f"run:{run}"}


def _calls_of(a, cmd):
    return [c for c in _log(a, "calls.log") if c[0] == cmd]


def test_heartbeat_notice_from_other_run_is_blocked_without_consuming_anything():
    a = Env(run="run_a")
    a.inbox(_hb("lendo"), run="run_b")
    _inbox(a, _hb_inbox(a, "ctx_9", "fase-4", -5, 900))
    r = a.prompt(NOTICE_B)
    assert _blocked(r), r
    assert "run_b" in json.loads(r.stdout)["reason"]
    assert _calls_of(a, "check") == [], "nem peek, nem check, nem ack: consumer_fenced evitado e a caixa daquele Run fica como estava"
    assert a.states() == {"msg_1": "unread"}
    (ev,) = [e for e in a.events() if e["tipo"] == "heartbeat_visto"]
    assert ev["run"] == "run_b" and [(h["dispatch"], h["fase"]) for h in ev["heartbeats"]] == [("ctx_9", "fase-4")], ev


def test_notice_from_other_run_with_other_message_passes():
    for type_name in ("worker_done", "question", "escalation", "tipo_novo"):
        a = Env(run="run_a")
        _inbox(a, _hb_inbox(a, "ctx_9", "fase-4", -5, 900), _hb_inbox(a, "ctx_9", "x", -3, 901, type_name=type_name))
        r = a.prompt(NOTICE_B)
        assert r.returncode == 0 and not _blocked(r) and not [e for e in a.events() if e["tipo"] == "heartbeat_visto"], (type_name, r)
        assert "msg_hb901" in _hook_ctx(r), "ticket 336: it passes with the message read from the global inbox, no Run bound"


def test_notice_from_other_run_without_recent_message_passes():
    a = Env(run="run_a")
    _inbox(a, {**_hb_inbox(a, "ctx_9", "fase-4", -600, 900), "read": 1})  # already read: it is not the notice's (M11: `read` counts, not age)
    assert _no_tip(a.prompt(NOTICE_B).stdout) == ""
    b = Env(run="run_a")
    _inbox(b, _hb_inbox(b, "ctx_9", "fase-4", -5, 900, run="run_c"))  # heartbeat from a third Run
    assert _no_tip(b.prompt(NOTICE_B).stdout) == ""


def test_notice_from_other_run_with_orca_down_passes():
    a = Env(run="run_a")
    _inbox(a, _hb_inbox(a, "ctx_9", "fase-4", -5, 900))
    r = a.prompt(NOTICE_B, FAKE_FAIL="inbox")
    assert (r.returncode, _no_tip(r.stdout)) == (0, ""), r


def test_heartbeat_seen_from_other_run_keeps_the_dispatch_alive_in_the_summary_and_in_agents():
    a = Env(run="run_a")
    a.set("workers.json", [{"handle": "term_o1", "run": "run_b", "task": "task_o1", "status": "dispatched", "desde": _iso(-3000)}])
    _inbox(a, _hb_inbox(a, "ctx_term_o1", "fase-8", -5, 900))
    assert _blocked(a.prompt(NOTICE_B))
    o1 = _agents(a)["ctx_term_o1"]
    assert o1["estado"] == "rodando" and o1["fase"] == "fase-8", o1
    from datetime import datetime, timezone
    ab = _open_agent("travado", ultimo_heartbeat=now_iso(-2000), desde=now_iso(-3000), dispatch="ctx_term_o1")
    evs = orq_mod_events(a.home)
    txt = orq_mod.summary(evs, ab, {"itens": []}, now_at=datetime.now(timezone.utc))
    assert "Stuck" not in txt and "fase-8" in txt, txt


def test_heartbeat_from_blocked_other_run_does_not_lose_the_worker_done_that_arrives_later():
    a = Env(run="run_a")
    a.inbox(_hb("lendo"), run="run_b")
    _inbox(a, _hb_inbox(a, "ctx_9", "fase-4", -5, 900))
    assert _blocked(a.prompt(NOTICE_B))
    a.inbox(("worker_done", {"taskId": "t", "dispatchId": "ctx_9"}), run="run_b")
    _inbox(a, _hb_inbox(a, "ctx_9", "fase-4", -8, 900), {**_hb_inbox(a, "ctx_9", "", -2, 901, type_name="worker_done")})
    r = a.prompt(NOTICE_B)
    assert "msg_hb901 worker_done" in _hook_ctx(r), "the worker_done wakes, already read (ticket 182)"
    assert set(a.states().values()) == {"unread"}, "ticket 336: the hook reads the global inbox and confirms nothing in a Run the coordinator does not command"
    a.set("run.json", {"id": "run_b"})  # o coordenador faz run-use no Run: a caixa sai inteira, lote a lote
    got = subprocess.run([a.bin, "orchestration", "check", "--run", "run_b", "--all", "--json"], env=a.env, capture_output=True, text=True)
    assert [m["type"] for m in json.loads(got.stdout)["result"]["messages"]] == ["heartbeat", "worker_done"]


# ---------- slice 9: tickets in files, map and resume in a new session (section 20 of the design) ----------

ACCEPTANCE = "\n\n## Acceptance criteria\n\n- [ ] X funciona\n- [ ] o teste de X passa\n"


def _spec_tk(a, body_text="Faça X.", item_name="spec.md", acceptance=ACCEPTANCE):
    path = os.path.join(a.tmp.name, item_name)
    with open(path, "w") as f:
        f.write(body_text + acceptance)
    return path


def _new(a, title="Ticket de teste", *extra, spec=None, **env):
    return a.orq("ticket", "novo", "--titulo", title, "--spec-arquivo", spec or _spec_tk(a), *extra, **env)


def _ticket(a, nn):
    (file_path,) = [f for f in os.listdir(a.env["ORQ_ISSUES"]) if f.startswith(f"{nn}-")]
    return os.path.join(a.env["ORQ_ISSUES"], file_path)


def _read_text(a, nn):
    return open(_ticket(a, nn)).read()


def test_ticket_new_creates_file_in_to_tickets_format():
    a = Env(run="run_a")
    r = _new(a, "Ticket de teste")
    assert r.returncode == 0, r.stderr
    out = json.loads(r.stdout)
    assert out["ticket"] == "01" and out["task"] == "task_tk1" and out["run"] == "run_a", out
    assert os.path.basename(out["arquivo"]) == "01-ticket-de-teste.md" and os.path.dirname(out["arquivo"]) == a.env["ORQ_ISSUES"]
    txt = _read_text(a, "01")
    assert txt.startswith("# 01: Ticket de teste\n"), txt
    cab = txt.split("\n## ")[0]
    assert "Status: ready-for-agent" in cab and "Blocked by: (nenhum)" in cab and "Run: run_a" in cab and "Task: task_tk1" in cab, cab
    assert "\n## What to build\n\nFaça X." in txt and "\n## Acceptance criteria\n" in txt and "## Answer" not in txt, txt


