    assert sorted(os.listdir(a.env["ORQ_ISSUES"])) == ["01-primeiro.md", "02-segundo-ticket-com-pontuacao.md"]
    os.remove(_ticket(a, "01"))
    assert json.loads(_new(a, "Terceiro").stdout)["ticket"] == "03", "o número segue o maior existente"


