# o hook SessionStart

def _session(a, sid="abcdef123456", **env):
    return a.orq("hook", "session", stdin=json.dumps({"session_id": sid, "source": "startup", "hook_event_name": "SessionStart"}), **env)


def _ctx_session(a, **env):
    r = _session(a, **env)
    assert r.returncode == 0, r.stderr
    out = json.loads(r.stdout)["hookSpecificOutput"]
    assert out["hookEventName"] == "SessionStart"
    return out["additionalContext"]


def test_hook_session_injects_status_open_tickets_and_the_map_path():
    a = Env(run="run_a")
    _new(a, "Base")
    _new(a, "Depende do base", "--blocked-by", "01")
    _new(a, "Já feito")
    a.orq("ticket", "fechar", "03", "--answer", "ok")
    ctx = _ctx_session(a)
    line_list = ctx.splitlines()
    assert len(line_list) <= 12, ctx
    assert "[orq]" in line_list[0] and "No effect" in line_list[0] and "With you:" in ctx, "o orq status"
    assert "Open tickets (2)" in ctx and "01 Base (ready-for-agent)" in ctx, ctx
    assert "02 Depende do base (ready-for-agent; Blocked by: 01)" in ctx, ctx
    assert "Já feito" not in ctx, "resolvido não aparece"
    assert f"Map: {a.env['ORQ_MAPA']}" in line_list[-1], line_list[-1]


