    a = Env(run="run_a")
    for i in range(9):
        _new(a, f"Ticket numero {i + 1}")
    ctx = _ctx_session(a)
    line_list = ctx.splitlines()
    assert len(line_list) == 12, (len(line_list), ctx)
    assert "Open tickets (9)" in ctx and "+" in line_list[-2] and "orq ticket list" in line_list[-2], line_list[-2]
    assert line_list[-1].startswith("Map:") and "01 Ticket numero 1 " in ctx


