# wrong-place guard (ticket 33)

def _repo(base, branch="main"):
    """Main checkout with one commit, on branch `branch`, and a linked worktree `wt`; returns (main, worktree)."""
    p, w = os.path.join(base, "repo"), os.path.join(base, "wt")
    g = lambda *a, cwd=p: subprocess.run(["git", "-C", cwd, *a], check=True, capture_output=True, env={**os.environ, "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t",
                                                                                                         "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@t"})
    os.makedirs(p)
    g("init", "-q", "-b", "main")
    g("commit", "-q", "--allow-empty", "-m", "x")
    g("worktree", "add", "-q", "-b", "feat/w", w)
    if branch != "main":
        g("checkout", "-q", "-b", branch)
    return p, w


def _place(a, cwd, cmd="git commit -m x", tool="Bash", sid="abcdef123456", **env):
    ti = {"command": cmd} if tool == "Bash" else {"file_path": os.path.join(cwd, "a.txt")}
    return a.orq("hook", "lugar", stdin=json.dumps({"session_id": sid, "cwd": cwd, "hook_event_name": "PreToolUse", "tool_name": tool, "tool_input": ti}), **env)


def _notice(r):
    assert r.returncode == 0, r
    if not r.stdout:
        return ""
    out = json.loads(r.stdout)["hookSpecificOutput"]
    assert out["hookEventName"] == "PreToolUse" and "permissionDecision" not in out, "só avisa, nunca bloqueia"
    return out["additionalContext"]


def test_place_main_checkout_on_default_branch_does_not_notify():
    a = Env(run="run_a")
    a.prompt("oi")  # the session becomes a coordinator (saved Run)
    p, _ = _repo(a.tmp.name)
    assert _notice(_place(a, p)) == ""
    assert _notice(_place(a, p, tool="Edit")) == ""
    assert _notice(_place(a, p, cmd="git status")) == "", "comando que não escreve passa"


def test_place_main_checkout_outside_default_branch_notifies():
    a = Env(run="run_a")
    a.prompt("oi")
    p, _ = _repo(a.tmp.name, branch="feat/outra")
    for r in (_place(a, p), _place(a, p, cmd="cd x && git push origin HEAD"), _place(a, p, tool="Write")):
        msg = _notice(r)
        assert "wrong place" in msg and "feat/outra" in msg and "main" in msg, msg
    assert _notice(_place(a, p, cmd="echo git commit")) == ""


def test_place_cwd_in_worker_worktree_notifies_but_the_coordinator_home_does_not():
    a = Env(run="run_a")
    a.prompt("oi")
    p, w = _repo(a.tmp.name)
    msg = _notice(_place(a, w, CLAUDE_PROJECT_DIR=p))
    assert "wrong place" in msg and os.path.realpath(w) in msg, msg
    assert _notice(_place(a, w, CLAUDE_PROJECT_DIR=w)) == "", "coordenador que mora numa worktree ligada não é engano"


def test_place_only_in_coordinator_and_under_100_ms():
    a = Env(run="run_a")
    p, _ = _repo(a.tmp.name, branch="feat/outra")
    assert _notice(_place(a, p)) == "", "sessão sem Run guardado não é coordenador"
    a.prompt("oi")
    w = Env(run="run_a")  # worker: the dispatch preamble records the role
    pw, _ = _repo(w.tmp.name, branch="feat/outra")
    w.prompt(PREAMBLE)
    assert _notice(_place(w, pw)) == "" and _calls(w, "run-current") == []
    assert _notice(_place(a, p, ORCA_TERMINAL_HANDLE="")) == "", "fora do Orca"
    ev = {"session_id": "abcdef123456", "cwd": p, "tool_name": "Bash", "tool_input": {"command": "git commit -m x"}}
    t = time.perf_counter()
    orq_mod.hook_place(ev, None)
    assert time.perf_counter() - t < 0.1, "o hook em si (git incluído) passa de 100 ms"


