# the migration

MIGRATION_DIR = os.path.join(HERE, "fixtures", "issues-migracao")  # example tickets 01 to 08 (B20: never the real folder, which changes with each `orq ticket new`)


def _check_migration(d):
    """The slice 9 migration: tickets 01 to 08 and the format of each. It does not require the total number of files or the status of 07."""
    files = sorted(os.listdir(d))[:8]
    assert [a[:2] for a in files] == ["01", "02", "03", "04", "05", "06", "07", "08"], files
    def cab(item_name):
        return open(os.path.join(d, item_name)).read().split("\n## ")[0]
    for item_name, chunk in zip(files[:6], (1, 2, 3, 4, 5, 6)):
        txt = open(os.path.join(d, item_name)).read()
        assert txt.startswith(f"# {item_name[:2]}: demo slice {chunk}:") and "Status: resolved" in cab(item_name), item_name
        resp = txt.split("\n## Answer\n")[1]
        assert "docs/design.md" in resp, f"{item_name}: o Answer aponta para o design"
        assert "## What to build" in txt and "## Acceptance criteria" in txt
    f8, f9 = files[6], files[7]
    assert open(os.path.join(d, f8)).read().startswith("# 07: demo slice 7: agent manager") and "Task: task_demo00000007" in cab(f8)
    assert "Task: task_demo00000008" in cab(f9) and open(os.path.join(d, f9)).read().startswith("# 08: demo slice 8:")
    for item_name in (f8, f9):
        assert "## What to build" in open(os.path.join(d, item_name)).read() and "## Acceptance criteria" in open(os.path.join(d, item_name)).read()


def test_migration_one_ticket_per_delivered_slice_and_one_for_each_open():
    _check_migration(MIGRATION_DIR)


