# B21
def test_review5_b21_guard_does_not_block_command_that_only_quotes_orq_dispatch():
    guard = os.path.join(HERE, "hooks", "worker-routing-guard.py")

    def run_cmd(cmd):
        r = subprocess.run([sys.executable, guard], input=json.dumps({"tool_name": "Bash", "tool_input": {"command": cmd}}), capture_output=True, text=True)
        return json.loads(r.stdout)["hookSpecificOutput"]["permissionDecision"] if r.stdout.strip() else "allow"

    assert run_cmd('echo "veja: python3 ~/.claude/orq/orq.py despachar --run r"') == "allow"
    assert run_cmd("echo 'veja: python3 ~/.claude/orq/orq.py despachar --run r'") == "allow"
    assert run_cmd('git commit -m "fix; python3 orq.py despachar sem modelo"') == "allow"
    assert run_cmd("python3 ~/.claude/orq/orq.py despachar --run r --titulo 'a b' --spec-arquivo f") == "deny", "o comando de verdade continua barrado"
    assert run_cmd('cd /tmp && python3 orq.py despachar --run r --titulo "a b" --spec-arquivo f') == "deny"
    assert run_cmd("orq despachar --run r --titulo T --spec-arquivo f --modelo m --effort low") == "allow"


