def test_review7_b38_released_dispatch_does_not_become_stuck_with_cache_from_before_worker_done():
    from datetime import datetime, timedelta, timezone
    now_at = datetime.now(timezone.utc)
    hb = (now_at - timedelta(minutes=60)).strftime("%Y-%m-%dT%H:%M:%SZ")
    for state in ("rodando", "travado"):
        ab = _open_agent(state, ultimo_heartbeat=hb)
        assert orq_mod.alive_line([{"tipo": "liberar", "dispatch": "ctx_1", "fechado": True}], ab, now_at) == "", state
        assert not [a for a in orq_mod.reassess(ab["agentes"], [{"tipo": "liberar", "dispatch": "ctx_1", "fechado": True}], now_at) if a["estado"] == "travado"]
    assert "STUCK" in orq_mod.alive_line([], _open_agent("rodando", ultimo_heartbeat=hb), now_at)


