# ---------- ticket 26: steer with redelivery and alert; orq responder ----------

def _steer_26(a, read_text=0, **line):
    """A steer to a worker that Orca already notified (busy: orq typed nothing), the worker idle at the prompt and the inbox line with `read`."""
    a.set("workers.json", [{"handle": "term_w1", "run": "run_a", "task": "task_rodando", "dispatch": "ctx_1", "status": "dispatched",
                            "desde": _iso(-3000), "agente": "claude"}])
    a.set("terminals.json", ["term_w1", "term_coord"])
    a.set("busy.json", ["term_w1"])
    _steer_env(a)
    r = a.orq("steer", "task_rodando", "use o índice novo")
    assert r.returncode == 0, r.stderr
    assert _log(a, "send.log") == [], "o steer a worker ocupado não digita nada"
    a.set("busy.json", [])
    _stopped_26(a)
    _line_26(a, read_text, **line)


def _stopped_26(a, stopped=True):
    os.makedirs(a.home, exist_ok=True)
    end = now_iso(-300) if stopped else None
    _write_state(os.path.join(a.home, "turnos.json"), {"ctx_1": {"task": "task_rodando", "inicio": now_iso(-600), "fim": end}})


def _line_26(a, read_text=0, **fields):
    """The steer message in the Orca inbox (msg_9 is the id the fake Orca returns on send)."""
    _inbox(a, {"id": "msg_9", "run_id": "run_a", "type": "status", "priority": "high", "subject": "Ajuste", "body": "use o índice novo", "payload": None,
               "from_handle": "term_coord", "to_handle": "dispatch:ctx_1", "read": read_text, "sequence": 900, "created_at": _iso(-5), "delivered_at": None, **fields})


def _age_26(a, seg):
    """Moves the timestamp of the steers and redeliveries back `seg` seconds: the time the manager waits before acting."""
    import calendar
    p = os.path.join(a.home, "events.jsonl")
    line_list = []
    for x in open(p).read().splitlines():
        e = orqlib.to_pt(json.loads(x))
        if e["tipo"] in ("steer", "steer_reentrega"):
            e["ts"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(calendar.timegm(time.strptime(e["ts"], "%Y-%m-%dT%H:%M:%SZ")) - seg))
        line_list.append(json.dumps(e))
    open(p, "w").write("\n".join(line_list) + "\n")


def _typed_26(a):
    return [e[e.index("--text") + 1] for e in _sent_notices(a, "term_w1")]


def test_ticket26_no_reading_after_5_min_with_stopped_worker_retypes_notice():
    a = Env()
    _steer_26(a)
    assert a.orq("steers").returncode == 0 and _typed_26(a) == [], "menos de 300 s: ainda dá tempo de ler"
    _age_26(a, 350)
    r = a.orq("steers")
    assert r.returncode == 0, r.stderr
    (text_value,) = _typed_26(a)
    assert text_value.startswith("You have 1 orchestration message.") and "check --terminal term_w1" in text_value, text_value
    (ev,) = [e for e in a.events() if e["tipo"] == "steer_reentrega"]
    assert (ev["msg_id"], ev["dispatch"], ev["tentativa"]) == ("msg_9", "ctx_1", 1), ev
    assert _typed_26(a) == [text_value] and a.orq("steers").returncode == 0 and len(_typed_26(a)) == 1, "a tentativa recomeça a contagem dos 300 s"


def test_ticket26_busy_worker_receives_nothing():
    a = Env()
    _steer_26(a)
    _stopped_26(a, stopped=False)  # the turn is open: Orca notifies on its own when it finishes
    _age_26(a, 500)
    assert a.orq("steers").returncode == 0
    assert _typed_26(a) == [] and not [e for e in a.events() if e["tipo"] in ("steer_reentrega", "alerta")]
    b = Env()
    _steer_26(b)
    _age_26(b, 500)
    r = b.orq("steers", FAKE_PROMPT_BLOCKED="1")  # the hook says idle, but Orca knows the agent is in the middle of the turn
    assert r.returncode == 0 and not [e for e in b.events() if e["tipo"] == "steer_reentrega"], "o Orca recusou o texto: nenhuma tentativa gasta"
    assert not [e for e in b.events() if e["tipo"] == "alerta"]


def test_ticket26_failed_retry_writes_alert_and_stops_typing():
    a = Env()
    _steer_26(a)
    _age_26(a, 350)
    assert a.orq("steers").returncode == 0
    assert len(_typed_26(a)) == 1 and not [e for e in a.events() if e["tipo"] == "alerta"], "uma tentativa, ainda sem alerta"
    _age_26(a, 350)
    r = a.orq("steers")
    assert "steer not read" in r.stdout, r.stdout
    (al,) = [e for e in a.events() if e["tipo"] == "alerta"]
    assert (al["alerta"], al["task"], al["dispatch"], al["run"], al["msg_id"]) == ("steer_nao_lido", "task_rodando", "ctx_1", "run_a", "msg_9"), al
    _age_26(a, 350)
    a.orq("steers")
    assert len(_typed_26(a)) == 1 and len([e for e in a.events() if e["tipo"] == "alerta"]) == 1, "depois do alerta nada mais é digitado nem gravado"
    assert "steer not read" in a.orq("status").stdout, "o resumo carrega o alerta"
    agent_row = _agents(a)["ctx_1"]
    assert agent_row["alerta"] == "steer not read", agent_row
    assert "steer not read" in a.orq("agentes").stdout
    a.orq("alerta", "visto", "task_rodando")
    assert "steer not read" not in a.orq("status").stdout and "alerta" not in _agents(a)["ctx_1"], "orq alerta visto trata o alerta"


def test_ticket118_worker_with_open_question_receives_neither_notice_nor_alert():
    a = Env()
    _steer_26(a)
    _age_26(a, 350)
    assert a.orq("steers").returncode == 0
    assert len(_typed_26(a)) == 1
    _inbox(a, _ask_question(950, "ctx_1"), {"id": "msg_9", "run_id": "run_a", "type": "status", "priority": "high", "subject": "Ajuste", "body": "x",
                                          "payload": None, "from_handle": "term_coord", "to_handle": "dispatch:ctx_1", "read": 0, "sequence": 900,
                                          "created_at": _iso(-5), "delivered_at": None})
    _age_26(a, 350)
    r = a.orq("steers")
    assert r.returncode == 0 and "steer not read" not in r.stdout, r.stdout
    assert not [e for e in a.events() if e["tipo"] == "alerta"], "a pergunta aberta é a razão do silêncio: sem alerta"
    assert len(_typed_26(a)) == 1


def test_ticket26_no_redelivery_after_reading():
    a = Env()
    _steer_26(a)
    _age_26(a, 350)
    a.orq("steers")
    assert len(_typed_26(a)) == 1
    _line_26(a, read_text=1)  # o worker rodou o check
    for _ in range(4):
        _age_26(a, 350)
        assert a.orq("steers").returncode == 0
    assert len(_typed_26(a)) == 1 and not [e for e in a.events() if e["tipo"] == "alerta"], "lido: sem nova tentativa e sem alerta"
    assert [(e["motivo"], e["fonte"]) for e in a.events() if e["tipo"] == "steer_fim"] == [("lido", "orca")]
    b = Env()
    _steer_26(b, read_text=1)
    _age_26(b, 500)
    b.orq("steers")
    assert _typed_26(b) == []


def _transcribed_26(a, text_value, session="sess26"):
    """Worker session transcript in ORQ_PROJETOS, with `text_value` at the end, and the turnos.json pointing to it."""
    folder = os.path.join(a.tmp.name, "projetos", "p")
    os.makedirs(folder, exist_ok=True)
    open(os.path.join(folder, session + ".jsonl"), "w").write(json.dumps({"type": "user", "message": {"content": "oi"}}) + "\n" + json.dumps({"type": "user", "message": {"content": text_value}}) + "\n")
    _write_state(os.path.join(a.home, "turnos.json"), {"ctx_1": {"task": "task_rodando", "sessao": session, "inicio": now_iso(-600), "fim": now_iso(-300)}})
    return {"ORQ_PROJETOS": os.path.join(a.tmp.name, "projetos")}


def test_ticket26_worker_that_read_by_check_without_ack_counts_as_read_by_transcript():
    a = Env()
