def test_ticket28_pending_alive_future_expired_waiting_and_aged():
    from datetime import date
    today = date(2026, 9, 29)
    base = {"id": "p", "tipo": "acao", "titulo": "t", "desde": "2026-09-25"}
    assert orq_mod.pending_after(base, today) is None, "viva"
    assert orq_mod.pending_after({**base, "ate": "2026-10-05"}, today) == "until 2026-10-05", "data futura"
    assert orq_mod.pending_after({**base, "ate": "2026-09-29"}, today) is None, "data de hoje volta"
    assert orq_mod.pending_after({**base, "ate": "2026-09-20", "espera": "Ana", "desde": "2026-08-01"}, today) is None, "data vencida volta, mesmo esperando e velha"
    assert orq_mod.pending_after({**base, "espera": "Ana"}, today) == "waiting on Ana"
    assert orq_mod.pending_after({**base, "desde": "2026-09-15"}, today) is None, "14 dias ainda é viva"
    assert orq_mod.pending_after({**base, "desde": "2026-09-14"}, today) == "stale for 15 d", "envelhecida"
    assert orq_mod.pending_after({**base, "desde": "2026-08-01", "gate": "g1"}, today) is None, "decisão com gate não some"
    assert orq_mod.pending_after({"id": "sem-desde", "tipo": "avisar", "titulo": "t"}, today) is None, "item antigo sem desde segue vivo"


