def test_audience_check_finds_forbidden_term_and_skips_without_list():
    """scripts/audiencia-check.py: fails with file:line, passes clean, skips without the list; the repository pre-commit calls it"""
    check = os.path.join(HERE, "scripts", "audiencia-check.py")
    with tempfile.TemporaryDirectory() as d:
        subprocess.run(["git", "init", "-q", d], check=True)
        with open(os.path.join(d, "doc.md"), "w") as f:
            f.write("limpo\nfala da Empresa Secreta aqui\n")
        subprocess.run(["git", "-C", d, "add", "doc.md"], check=True)
        listing = os.path.join(d, "termos.txt")
        with open(listing, "w") as f:
            f.write("# comentário\nempresa secreta\nre:host-\\d+\n")

        def run_it(terms):
            return subprocess.run([sys.executable, check, d], capture_output=True, text=True, env={**os.environ, "ORQ_TERMOS": terms})

        r = run_it(listing)
        assert r.returncode == 1 and "doc.md:2:" in r.stdout and "doc.md:1:" not in r.stdout, r.stdout + r.stderr
        with open(os.path.join(d, "doc.md"), "w") as f:
            f.write("limpo\n")
        assert run_it(listing).returncode == 0
        r = run_it(os.path.join(d, "nao-existe.txt"))
        assert r.returncode == 0 and "pulada" in r.stderr, r.stderr
    hook = os.path.join(HERE, "githooks", "pre-commit")
    assert os.access(hook, os.X_OK) and "audiencia-check.py" in open(hook).read()
    # the current repository passes (without the private list the check is skipped, and passes too)
    assert subprocess.run([sys.executable, check], capture_output=True, text=True).returncode == 0


def _repo_git(tmp, dirty=False):
    """Git repository with one commit; returns (path, short sha)."""
    repo = os.path.join(tmp, "r" + str(len(os.listdir(tmp))))
    os.makedirs(repo)
    g = lambda *x: subprocess.run(["git", "-C", repo, *x], capture_output=True, text=True, check=True).stdout.strip()  # noqa: E731
    g("init", "-q")
    open(os.path.join(repo, "f"), "w").write("x")
    g("add", "f")
    g("-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "c")
    for i in range(50):  # a short sha of only digits (1 in 27) is not a sha to SHA_RE: the PR test went red at random (ticket 328)
        if orq_mod.SHA_RE.fullmatch(g("rev-parse", "--short=7", "HEAD")):
            break
        g("-c", "user.name=t", "-c", "user.email=t@t", "commit", "--amend", "-qm", f"c{i}")
    if dirty:
        open(os.path.join(repo, "novo"), "w").write("y")
    return repo, g("rev-parse", "--short=7", "HEAD")


