def test_review8_m16_declared_wait_with_turn_ended_stays_running_and_expired_is_stuck():
    now_at = datetime.now(timezone.utc)
    ws = [{"dispatchId": "ctx_1", "taskId": "task_1", "runId": "run_a", "dispatchStatus": "dispatched"}]
    detail_entry = {"ctx_1": {"agente": "claude", "desde": _iso(-3600).replace(" ", "T") + "Z"}}
    turns = {"ctx_1": {"task": "task_1", "inicio": now_iso(-700), "fim": now_iso(-580)}}  # ended the turn waiting, 10 min ago

    def msgs(phase):
        return [{"id": "m1", "type": "heartbeat", "payload": json.dumps({"taskId": "task_1", "dispatchId": "ctx_1", "phase": phase}), "created_at": _iso(-600)}]
    agent_row = orq_mod.build_agents(ws, msgs(f"esperando: fila de E2E até {_hhmm_25(50)}"), [], now_at, detail_entry, turns=turns)[0]
    assert agent_row["estado"] == "rodando" and agent_row["espera"] == "fila de E2E" and agent_row["turno"] == "parado", agent_row
    ab = {"agentes": [agent_row]}
    assert orq_mod.reassess(ab["agentes"], [], now_at, turns)[0]["estado"] == "rodando"
    assert "stopped at the prompt" not in orq_mod.alive_line([], ab, now_at, turns)
    agent_row = orq_mod.build_agents(ws, msgs(f"esperando: fila de E2E até {_hhmm_25(-5)}"), [], now_at, detail_entry, turns=turns)[0]
    assert agent_row["estado"] == "travado" and agent_row["motivo"] == "wait expired", agent_row
    assert orq_mod.reassess([agent_row], [], now_at, turns)[0]["estado"] == "travado"
    agent_row = orq_mod.build_agents(ws, msgs("compilando"), [], now_at, detail_entry, turns=turns)[0]
    assert agent_row["estado"] == "parado", "sem espera declarada o turno encerrado continua parado"


