# ---------- review-9 (B49 to B53 and the test Runs filter) ----------

def _under_false_lock(seen):
    """Replaces manager_lock with one that only counts depth; returns what to restore."""
    import contextlib
    orig = orq_mod.manager_lock
    prof = [0]

    @contextlib.contextmanager
    def lock():
        prof[0] += 1
        try:
            yield
        finally:
            prof[0] -= 1
    orq_mod.manager_lock = lock
    return orig, prof


def test_review9_b49_reconcile_gates_checks_and_resolves_under_the_manager_lock():
    seen = []
    orig, prof = _under_false_lock(seen)
    old_values = (orq_mod.read_events, orq_mod.coordinator_run, orq_mod._resolve_gate)
    try:
        orq_mod.read_events = lambda: [{"tipo": "pend", "op": "done", "gate": "g1", "gate_run": "run_b", "resposta": "x"}]
        orq_mod.coordinator_run = lambda run, own=None: seen.append(("conferiu", prof[0])) or True
        orq_mod._resolve_gate = lambda g, r, run=None: seen.append(("resolveu", prof[0])) or True
        orq_mod.reconcile_gates()
    finally:
        orq_mod.manager_lock = orig
        orq_mod.read_events, orq_mod.coordinator_run, orq_mod._resolve_gate = old_values
    assert seen == [("conferiu", 1), ("resolveu", 1)], seen


def test_review9_b49_pending_done_checks_and_resolves_gate_under_the_manager_lock():
    seen = []
    orig, prof = _under_false_lock(seen)
    old_values = (orq_mod.read_events, orq_mod._mutate_pending, orq_mod.coordinator_run, orq_mod._resolve_gate)
    try:
        orq_mod.read_events = lambda: []
        orq_mod._mutate_pending = lambda rm, ev: {"id": "d", "gate": "g1", "gate_run": "run_b"}
        orq_mod.coordinator_run = lambda run, own=None: seen.append(("conferiu", prof[0])) or True
        orq_mod._resolve_gate = lambda g, r, run=None: seen.append(("resolveu", prof[0])) or True
        orq_mod.pending_done("d", "sim")
    finally:
        orq_mod.manager_lock = orig
        orq_mod.read_events, orq_mod._mutate_pending, orq_mod.coordinator_run, orq_mod._resolve_gate = old_values
    assert seen == [("conferiu", 1), ("resolveu", 1)], seen


