def test_night_reported_failure_resets_the_count():
    f = orq_mod.consecutive_failures
    night = {"ligada_em": "2026-01-01T00:00:00Z"}
    evs = [{"ts": "2026-09-30T01:00:00Z", "tipo": "despacho", "dispatch": d} for d in ("d1", "d2", "d3", "d4")]
    wd = lambda d, o, rp=False: {"type": "worker_done", "payload": {"dispatchId": d, "outcome": o, **({"reportPath": "/r"} if rp else {})}}
    assert f(evs, [wd("d1", "failed"), wd("d2", "failed"), wd("d3", "failed"), wd("d4", "failed")], night) == 4
    assert f(evs, [wd("d1", "failed"), wd("d2", "failed"), wd("d3", "failed", True), wd("d4", "failed")], night) == 1, "failed com relatório é decisão do worker"
    assert f(evs, [wd("d1", "failed"), wd("d2", "succeeded"), wd("d3", "failed"), wd("d4", "failed")], night) == 2, "succeeded reinicia"
    lib = evs + [{"ts": "2026-09-30T03:00:00Z", "tipo": "liberar", "dispatch": "d1"}]
    assert f(lib[:1] + lib[-1:], [], night) == 1, "liberado sem worker_done conta"
    assert f(evs[:2], [], night) == 0, "ainda rodando não conta"


