    assert [e for e in a.events() if e["tipo"] == "despacho"][0]["ambiente"] == ["GIT_TERMINAL_PROMPT", "GIT_CONFIG_COUNT", "GIT_CONFIG_KEY_0", "GIT_CONFIG_VALUE_0"]


