def _queue_add(a, step="1", item_name="Plano 2 para main", by="Destrava o plano 1", *prs):
    return a.orq("fila", "add", "--passo", step, "--nome", item_name, "--por", by, *(prs or ("1216", "1230")))


def test_queue_add_list_done_and_rm():
    a = _digest_env()
    assert "no step" in a.orq("fila", "lista").stdout
    r = _queue_add(a)
    assert r.returncode == 0, r.stderr
    assert json.loads(r.stdout) == {"passo": 1, "nome": "Plano 2 para main", "por": "Destrava o plano 1", "prs": [1216, 1230], "feito": False}
    _queue_add(a, "2", "Tela", "Depende do 1", "1220")
    listing = a.orq("fila", "lista").stdout.splitlines()
    assert listing[0].startswith("1  Plano 2 para main  [to do]  #1216 open ? no CI reading, #1230 open ? no CI reading") and "Destrava o plano 1" in listing[0] and listing[1].startswith("2  Tela"), listing
    assert listing[-1] == "Next to merge: no step ready", listing
    assert a.orq("fila", "feito", "1").returncode == 0
    assert "[done]" in a.orq("fila", "lista").stdout.splitlines()[0]
    assert a.orq("fila", "rm", "2").returncode == 0
    assert len(a.orq("fila", "lista").stdout.splitlines()) == 2  # the step and the next one's line
    assert [(e["op"], e["passo"]) for e in a.events() if e["tipo"] == "fila"] == [("add", 1), ("add", 2), ("feito", 1), ("rm", 2)]


# ---- orq fila: CI, conflict and next step (ticket 81) ----

def _ck(item_name, conclusion="SUCCESS", status="COMPLETED"):
    return {"__typename": "CheckRun", "name": item_name, "status": status, "conclusion": conclusion}


def _ci_queue(sem_ci=False, **by_pr):
    """Two PRs (1216 and 1220) in two steps; each PR reads the given `mergeable` and checks and the poll runs once."""
    a = Env(run="run_a")
    _neo(a, sem_ci)
    _gh(a)
    for url, k in ((PR1, "pr1"), (PR2, "pr2")):
        _pr(a, url, "OPEN", "development", **{"mergeable": "MERGEABLE", "statusCheckRollup": [_ck("lint")], "headRefName": "feat/" + k, **by_pr.get(k, {})})
    a.orq("pr", "ligar", "task_a", PR1)
    a.orq("pr", "ligar", "task_b", PR2)
    _queue_add(a, "1", "Primeiro", "", "1216")
    _queue_add(a, "2", "Segundo", "", "1220")
    assert a.orq("pr", "poll", "--forcar").returncode == 0
    return a


def test_queue_poll_stores_mergeable_and_checks_with_one_gh_call_for_all_prs():
    a = _ci_queue(pr1={"statusCheckRollup": [_ck("lint", "FAILURE"), _ck("test", None, "IN_PROGRESS"), _ck("build")]})
    call_list = [c for c in _gh_calls(a) if c[:2] == ["pr", "list"]]
    assert len(call_list) == 1, call_list  # one call for both PRs of the same repository
    ci = {i["numero"]: i["ci"] for i in _read_state(os.path.join(a.home, "prs.json"))["itens"]}
    assert (ci[1216]["mergeable"], ci[1216]["falhas"], ci[1216]["rodando"]) == ("MERGEABLE", ["lint"], ["test"]) and ci[1216]["lido_em"] > 0, ci
    assert ci[1220]["falhas"] == [] and ci[1220]["rodando"] == []


def test_queue_list_shows_the_red_check_by_name_the_conflict_and_the_ci_running():
    a = _ci_queue(pr1={"statusCheckRollup": [_ck("lint", "FAILURE"), _ck("e2e", "TIMED_OUT")]}, pr2={"mergeable": "CONFLICTING", "statusCheckRollup": [_ck("test", None, "QUEUED")]})
    l1, l2, end = a.orq("fila", "lista").stdout.splitlines()
    assert "#1216 open ✗ lint, e2e" in l1, l1
    assert "#1220 open ⚠ conflict ⏳ CI running" in l2, l2
    assert end == "Next to merge: no step ready"


