    file_path = os.path.join(a.home, "prs.json")
    d = _read_state(file_path)
    for i in d["itens"]:
        i["ci"]["lido_em"] -= 3600
    json.dump(d, open(file_path, "w"))
    out = a.orq("fila", "lista").stdout.splitlines()
