def test_away_stop_does_not_call_orca_beyond_what_the_stop_already_called():
    with_ref, without = _digest_env(), _digest_env()
    with_ref.orq("ausente", "ligar")
    n_with, n_without = len(_log(with_ref, "calls.log")), len(_log(without, "calls.log"))
    _stop(with_ref, last_assistant_message="oi"), _stop(without, last_assistant_message="oi")
    assert len(_log(with_ref, "calls.log")) - n_with == len(_log(without, "calls.log")) - n_without, "o digest do Stop não faz chamada ao Orca"


