# ---------- ticket 48: orq retomar ----------

def _w48(handle, run="run_a", **kw):
    return {"handle": handle, "run": run, "status": "dispatched", "dispatch": "ctx_" + handle, "task": "task_" + handle, **kw}


def _turn48(a, **per_dispatch):
    json.dump({d: {"task": "task_x", "sessao": v[0], "inicio": "2026-09-30T14:00:00Z", "fim": None, **({"cwd": v[1]} if v[1] else {})} for d, v in per_dispatch.items()},
              open(os.path.join(a.home, "turnos.json"), "w"))


def _outage48(a):
    """After the crash: w1 (opus) and w3 (no saved session) lost the terminal, w2 has a live terminal and w4 already finished."""
    os.makedirs(a.home, exist_ok=True)
    a.wt = os.path.join(a.tmp.name, "wt")
    for n in ("w1", "w2", "w4"):
        os.makedirs(os.path.join(a.wt, n))
    a.set("workers.json", [_w48("term_w1", modelo="claude-opus-5-5"), _w48("term_w2"), _w48("term_w3"), _w48("term_w4", status="completed")])
    a.set("tasks_run_a.json", [{"id": "task_term_w1", "task_title": "Ticket 99"}, {"id": "task_term_w3", "task_title": "Sem sessão"}])
    a.set("terminals.json", ["term_coord", "term_w2"])
    _turn48(a, ctx_term_w1=("sess-w1", a.wt + "/w1"), ctx_term_w2=("sess-w2", a.wt + "/w2"), ctx_term_w4=("sess-w4", a.wt + "/w4"))


def test_ticket48_worker_hook_records_session_and_launch_cwd_per_dispatch():
    a = Env(run=None)
    _hook(a, "prompt", prompt=PREAMBLE_24, cwd="/wt/t24")
    t = _turns(a)["ctx_d24"]
    assert t["sessao"] == "abcdef123456" and t["cwd"] == "/wt/t24", t
    _hook(a, "stop", cwd="/wt/t24/sub")
    _hook(a, "prompt", prompt="ajuste: use o outro arquivo", cwd="/wt/t24/sub")  # the worker did cd: the launch cwd is what counts
    assert _turns(a)["ctx_d24"]["cwd"] == "/wt/t24" and _turns(a)["ctx_d24"]["sessao"] == "abcdef123456"


def test_ticket48_resume_dry_run_lists_only_without_worker_done_and_without_live_terminal():
    a = Env(run="run_a")
    _outage48(a)
    r = a.orq("retomar", "--dry-run", "--json")
    assert r.returncode == 0, r.stderr
    res = json.loads(r.stdout)
    assert [(w["dispatch"], w["estado"]) for w in res["workers"]] == [("ctx_term_w1", "a_retomar"), ("ctx_term_w3", "sem_sessao")], res
    w1 = res["workers"][0]
    assert (w1["sessao"], w1["cwd"], w1["modelo"], w1["titulo"]) == ("sess-w1", a.wt + "/w1", "claude-opus-5-5", "Ticket 99"), w1
    assert not _log(a, "create.log") and res["gerente"] is None
    assert "a_retomar" in a.orq("retomar", "--dry-run").stdout


def test_ticket48_resume_creates_terminal_with_right_command_links_to_dispatch_and_checks_the_screen():
    a = Env(run="run_a", ORQ_RETOMAR_ESPERA_S="2")
    _outage48(a)
    a.set("screens.json", {"term_ret1": ["esc to interrupt"]})
    r = a.orq("retomar", "--json")
    assert r.returncode == 0, r.stderr
    res = json.loads(r.stdout)
    assert [(w["dispatch"], w["estado"], w.get("novo")) for w in res["workers"]] == [("ctx_term_w1", "retomado", "term_ret1"), ("ctx_term_w3", "sem_sessao", None)], res
    (c,) = _log(a, "create.log")
    assert c[c.index("--worktree") + 1] == "path:" + a.wt + "/w1" and c[c.index("--title") + 1] == "Ticket 99 (resumed)", c
    command = c[c.index("--command") + 1]
    assert command.startswith("claude --resume sess-w1 --model claude-opus-5-5 --dangerously-skip-permissions 'Continue where you left off."), command
    assert "final-report.md" in command
    (ev,) = [e for e in a.events() if e["tipo"] == "retomada"]
    assert (ev["dispatch"], ev["terminal"], ev["anterior"], ev["sessao"], ev["cwd"]) == ("ctx_term_w1", "term_ret1", "term_w1", "sess-w1", a.wt + "/w1"), ev
    assert "head" in ev and "sujo" in ev, "o checkpoint da worktree fica no evento"
    agent_rows = {x["dispatch"]: x for x in json.loads(a.orq("agentes", "--json").stdout)}
    assert agent_rows["ctx_term_w1"]["terminal"] == "term_ret1", "o terminal novo é o do dispatch"
    again = json.loads(a.orq("retomar", "--dry-run", "--json").stdout)
    assert [w["dispatch"] for w in again["workers"]] == ["ctx_term_w3"], "o retomado não volta à lista"


