def test_ticket48_manager_link_after_crash_swaps_coordinator_and_manager_and_keeps_the_runs():
    a = Env(run="run_c")
    os.makedirs(a.home, exist_ok=True)
    a.set("terminals.json", ["term_coord", "term_ger"])
