        _ticket_e2e(queue, "0000000001-1", 1, alive=True, start_time=1000)
        _ticket_e2e(queue, "0000000002-2", 2, alive=True, start_time=1500, project="e2e-y")
        _ticket_e2e(queue, "0000000003-3", 3, alive=True, start_time=1600, project="e2e-z")
        f = orq_mod.e2e_queue(queue, now_at=1000 + 600)
        assert (f["projeto"], f["min"], f["esperam"], f["presa"]) == ("e2e-x", 10, 2, None), f
        assert "e2e-x" in orq_mod.e2e_line(f) and "10 min" in orq_mod.e2e_line(f) and "2 waiting" in orq_mod.e2e_line(f) and "STUCK" not in orq_mod.e2e_line(f)


