        open(fake, "w").write(f"#!/bin/sh\necho \"$@\" >> {log}\n")
        os.chmod(fake, 0o755)
        os.environ["ORQ_OSASCRIPT"] = fake
        orq_mod.HOME, orq_mod.type_text = home, lambda h, t, *_: "rascunho"  # the notice is held (a draft in the box), so the macOS one is the only alert
