def _pause51(a):
    """Four live workers in run_a: security (P1, implementing), failover (P3, implementing), ticket 07 (P2, investigating) and panel (P3, in review)."""
    os.makedirs(a.home, exist_ok=True)
    a.wt = os.path.join(a.tmp.name, "wt")
    names = {"s": "Segurança: rotacionar segredos", "f": "Failover 31", "i": "Ticket 07", "p": "Painel do orq"}
    for n in names:
        os.makedirs(os.path.join(a.wt, n))
    a.set("workers.json", [_w48("term_" + n, modelo="claude-opus-5-5") for n in names])
    a.set("tasks_run_a.json", [{"id": "task_term_" + n, "task_title": t, "status": "dispatched", "dispatch_id": "ctx_term_" + n, "created_at": _iso(-900)} for n, t in names.items()])
    a.set("terminals.json", ["term_coord", *("term_" + n for n in names)])
    _turn48(a, **{"ctx_term_" + n: ("sess-" + n, a.wt + "/" + n) for n in names})
    _inbox(a, _hbi(1, "ctx_term_s", "implementing", -30), _hbi(2, "ctx_term_f", "implementing", -30), _hbi(3, "ctx_term_i", "investigating", -30),
           _hbi(4, "ctx_term_p", "reviewing", -30))


def _write_pause51(a, *names, after=1.0):
    """The worker complies: after `after` s it writes the new PAUSA.md in its worktree."""
    n0 = len(_log(a, "send.log"))

    def write_now():
        end = time.time() + 30  # only after each worker's steer: PAUSA.md's baseline is taken before it, and under load 1 s can come before
        while len(_log(a, "send.log")) < n0 + len(names) and time.time() < end:
            time.sleep(0.05)
        time.sleep(after)
        for n in names:
            f = os.path.join(a.wt, n, "PAUSA.md")
            open(f, "w").write("parei em X; próximo passo Y\n")
            os.utime(f, (time.time() + 5, time.time() + 5))
    t = ThreadPoolExecutor(1)
    return t.submit(write_now)


def test_ticket51_pause_without_argument_pauses_low_and_investigating_and_spares_review_and_high():
    a = Env(run="run_a", ORQ_PAUSA_ESPERA_S="6", ORQ_PAUSA_POLL_S="0.2")
    _pause51(a)
    dry_result = json.loads(a.orq("pausar", "--dry-run", "--json").stdout)
    assert sorted((w["task"], w["estado"]) for w in dry_result["pausados"]) == [("task_term_f", "a_pausar"), ("task_term_i", "a_pausar")], dry_result
    assert [(w["task"], w["fase"]) for w in dry_result["preservados"]] == [("task_term_p", "reviewing")], "P3 em verificação final fica"
    assert not _sent(a) and not _log(a, "close.log")
    f = _write_pause51(a, "f", "i")
    r = a.orq("pausar", "--json")
    f.result()
    assert r.returncode == 0, r.stderr
    res = json.loads(r.stdout)
    assert sorted((w["task"], w["estado"], w["prioridade"]) for w in res["pausados"]) == [("task_term_f", "pausado", 3), ("task_term_i", "pausado", 2)], res
    assert {x[x.index("--to") + 1] for x in _sent(a)} == {"dispatch:ctx_term_f", "dispatch:ctx_term_i"}
    assert all("PAUSE.md" in x[x.index("--body") + 1] for x in _sent(a))
    assert sorted(c[c.index("--terminal") + 1] for c in _log(a, "close.log")) == ["term_f", "term_i"], "só os pausados perdem o terminal"
    p = _cursor(a)["pausados"]
    assert set(p) == {"ctx_term_f", "ctx_term_i"} and (p["ctx_term_f"]["sessao"], p["ctx_term_f"]["cwd"], p["ctx_term_f"]["modelo"]) == ("sess-f", a.wt + "/f", "claude-opus-5-5"), p
    assert {e["dispatch"] for e in a.events() if e["tipo"] == "pausa_plano"} == {"ctx_term_f", "ctx_term_i"}


