def _screen_in_manager52(a, screen="tela-permissao.txt"):
    _multi(a, {"run_a": "term_ger"}, ["run_a"])
    a.set("workers.json", [_w48("term_w1", agente="claude")])
    _turn48(a, ctx_term_w1=("sess-w1", None))
    a.set("terminals.json", ["term_ger", "term_w1", "term_coord"])  # the worker's terminal is alive: without it the state is without_terminal
    a.set("screens.json", {"term_w1": _screen52(screen)})


def test_ticket52_manager_notifies_coordinator_once_and_agents_shows_the_question():
    a = Env(ORCA_TERMINAL_HANDLE="term_ger")
    _screen_in_manager52(a)
    r = a.orq("gerente", "absorver")
    assert r.returncode == 0 and "screen question (permissao)" in r.stdout, r
    (env,) = _sent_notices(a)
    text_value = _whole_notice(env[env.index("--text") + 1])
    assert "Do you want to proceed?" in text_value and "1) Yes" in text_value and "orq answer-screen task_term_w1 <option>" in text_value, text_value
    a.orq("gerente", "absorver")
