# ---------- ticket 79: machine budget and dispatch queue ----------

SONNET, OPUS = "claude-sonnet-5-5", "claude-opus-5-5"


def _fleet79(a, live=(), dead_set=()):
    """In run_a, one live worker per (title, model) in `live` (term_v0…, with terminal) and one down worker per (title, model) in `dead_set` (term_m0…, no terminal, with session and folder)."""
    os.makedirs(a.home, exist_ok=True)
    a.wt = os.path.join(a.tmp.name, "wt")
    ws, ts, sessions = [], [], {}
    for pref, listing in (("v", live), ("m", dead_set)):
        for n, (title, model) in enumerate(listing):
            h = f"term_{pref}{n}"
            ws.append(_w48(h, modelo=model))
            ts.append({"id": "task_" + h, "task_title": title, "status": "dispatched", "dispatch_id": "ctx_" + h, "created_at": _iso(-900)})
            if pref == "m":
                os.makedirs(os.path.join(a.wt, h))
                sessions["ctx_" + h] = ("sess-" + h, os.path.join(a.wt, h))
    a.set("workers.json", ws)
    a.set("tasks_run_a.json", ts)
    a.set("terminals.json", ["term_coord", *(f"term_v{n}" for n in range(len(live)))])
    if sessions:
        _turn48(a, **sessions)


def _release79(a, *handles):
    """Os workers entregaram: o dispatch fecha e o terminal some, a vaga abre."""
    a.set("workers.json", [{**w, "status": "completed"} if w["handle"] in handles else w for w in json.load(open(os.path.join(a.fake, "workers.json")))])
    a.set("terminals.json", [h for h in json.load(open(os.path.join(a.fake, "terminals.json"))) if h not in handles])


def _dispatch79(a, title, priority, model=SONNET, **env):
    return a.orq("despachar", "--run", "run_a", "--titulo", title, "--spec-arquivo", _spec(a), "--modelo", model, "--effort", "medium", "--prioridade", str(priority), **env)


def _queue79(a):
    return _read_state(os.path.join(a.home, "fila-despacho.json"))["itens"] if _state_exists(os.path.join(a.home, "fila-despacho.json")) else []


def _started_titles79(a):
    return [c[c.index("--task-title") + 1] for c in _log(a, "started.log")]


def _panel79():
    return Env(run="run_a", ORCA_TERMINAL_HANDLE="term_ger")


def test_ticket79_machine_json_missing_uses_defaults_and_set_adjusts_and_validates():
    a = Env(run="run_a")
    cfg = json.loads(a.orq("maquina", "--json").stdout)["config"]
    assert (cfg["max_workers"], cfg["max_e2e"], cfg["max_caros"]) == (4, 1, 2) and cfg["modelos_caros"] == ["claude-opus-*", "gpt-6-astra*", "gpt-6-sol*"], cfg
    assert not _state_exists(os.path.join(a.home, "maquina.json")), "ler não grava"
    assert json.loads(a.orq("maquina", "set", "max_workers", "6").stdout)["max_workers"] == 6
    assert json.loads(a.orq("maquina", "set", "modelos_caros", '["claude-opus-*"]').stdout)["modelos_caros"] == ["claude-opus-*"]
    for bad in (("max_workers", "muitos"), ("max_workers", "true"), ("nada", "1"), ("modelos_caros", "3")):
        r = a.orq("maquina", "set", *bad)
        assert r.returncode == 1 and r.stderr.startswith("orq:"), (bad, r)
    assert _read_state(os.path.join(a.home, "maquina.json")) == {"max_workers": 6, "modelos_caros": ["claude-opus-*"]}, "o que foi recusado não grava"
    json.dump({"max_workers": "x", "max_caros": 3}, open(os.path.join(a.home, "machine.json"), "w"))  # the set already wrote with the new name
    cfg = json.loads(a.orq("maquina", "--json").stdout)["config"]
    assert (cfg["max_workers"], cfg["max_caros"]) == (4, 3), "valor de tipo errado vale como ausente"


def test_ticket79_dispatch_with_full_budget_enqueues_and_does_not_raise_worker():
    a = Env(run="run_a")
    _fleet79(a, live=[(f"Vivo {n}", SONNET) for n in range(4)])
    r = _dispatch79(a, "Ticket 05", 2)
    assert r.returncode == 0, r.stderr
    out = json.loads(r.stdout)
    assert (out["estado"], out["posicao"], out["prioridade"]) == ("enfileirado", 1, 2) and "4/4 live workers" in out["motivo"] and "dispatchId" not in out, out
    assert "orq dispatch-queue list" in r.stderr, "o aviso diz como ver a fila"
    assert not _log(a, "started.log"), "nada subiu"
    (it,) = _queue79(a)
    assert (it["tipo"], it["run"], it["titulo"], it["modelo"], it["effort"], it["prioridade"]) == ("despacho", "run_a", "Ticket 05", SONNET, "medium", 2), it
    assert open(it["spec_arquivo"]).read() == open(_spec(a)).read() and it["spec_arquivo"].startswith(a.home), "o spec fica numa cópia em ORQ_HOME"
    assert _dispatch79(a, "Ticket 05", 2).returncode == 0 and len(_queue79(a)) == 1, "o mesmo pedido não entra duas vezes"
    assert "P2 despacho Ticket 05" in a.orq("fila-despacho", "lista").stdout
    assert [e["op"] for e in a.events() if e["tipo"] == "despacho_fila"] == ["entrou"]
    assert a.orq("fila-despacho", "rm", "fd_que_nao_existe").returncode == 1
    assert a.orq("fila-despacho", "rm", it["id"]).returncode == 0 and not _queue79(a) and not os.path.exists(it["spec_arquivo"])
    assert a.orq("fila-despacho", "lista").stdout.strip() == "dispatch queue empty"


def test_ticket79_open_slot_raises_p1_before_p2_and_one_per_panel_round():
    a = _panel79()
    _manager(a)
    _fleet79(a, live=[(f"Vivo {n}", SONNET) for n in range(4)])
    assert _dispatch79(a, "Segunda", 2).returncode == 0 and _dispatch79(a, "Primeira", 1).returncode == 0 and _dispatch79(a, "Terceira", 2).returncode == 0
    assert [i["titulo"] for i in sorted(_queue79(a), key=lambda i: (i["prioridade"], i["ts"]))] == ["Primeira", "Segunda", "Terceira"]
    a.orq("gerente", "absorver")
    assert not _log(a, "started.log"), "sem vaga o painel não sobe nada"
    _release79(a, "term_v0", "term_v1")
    r = a.orq("gerente", "absorver")
    assert r.returncode == 0, r.stderr
    assert _started_titles79(a) == ["Primeira"], "duas vagas, mas o painel sobe um por volta: o P1 antes do P2"
    assert "Primeira started" in r.stdout
    a.set("terminals.json", [*json.load(open(os.path.join(a.fake, "terminals.json"))), "term_novo5"])  # the new worker's terminal (the fake Orca does not create it)
    a.orq("gerente", "absorver")
    assert _started_titles79(a) == ["Primeira", "Segunda"], "a segunda vaga leva o próximo da fila; o worker novo já ocupa a primeira"
    a.set("terminals.json", [*json.load(open(os.path.join(a.fake, "terminals.json"))), "term_novo6"])
    a.orq("gerente", "absorver")
    assert _started_titles79(a) == ["Primeira", "Segunda"] and [i["titulo"] for i in _queue79(a)] == ["Terceira"], "duas vagas ocupadas por eles: a Terceira espera"


def test_ticket79_panel_raises_by_order_p1_p2_and_tie_by_oldest():
    a = _panel79()
    _manager(a)
    _fleet79(a, live=[(f"Vivo {n}", SONNET) for n in range(4)])
    for t, p in (("Segunda", 2), ("Primeira", 1), ("Terceira", 2)):
        assert _dispatch79(a, t, p).returncode == 0
    _release79(a, "term_v0", "term_v1", "term_v2", "term_v3")
