def test_ticket79_status_panel_and_digest_show_slots_busy_free_and_the_queue():
    a = Env(run="run_a")
    _pause51(a)
    out = json.loads(_dispatch79(a, "Ticket 06", 2).stdout)
    assert out["estado"] == "enfileirado"
    a.orq("ingest", "--refresh")
    ab = _read_state(os.path.join(a.home, "aberto.json"))["maquina"]
    assert (ab["max_workers"], ab["ocupadas"], ab["livres"], ab["caros"]) == (4, 4, 0, 4) and [i["titulo"] for i in ab["fila"]] == ["Ticket 06"], ab
    st = a.orq("status").stdout
    assert "Machine: 4/4 workers (4/2 expensive), 0 free slots; 1 in the dispatch queue: P2 Ticket 06" in st, st
    a.orq("digest", "--html")
    d = json.load(open(os.path.join(a.home, "digest", "atual.json")))
    assert "maquina" not in d, "o contrato do digest não muda"
    page_data = open(os.path.join(a.home, "digest", [f for f in os.listdir(os.path.join(a.home, "digest")) if f.endswith(".html")][0])).read()
    assert "Machine: 4/4 slots busy, 0 free, 1 in the dispatch queue" in page_data


