    assert _dispatch79(b, "Ticket 07", 2).returncode == 0
    _release79(b, "term_v0")
    (it,) = _queue79(b)
    _write_state(os.path.join(b.home, "fila-despacho.json"), {"itens": [{**it, "run": "run_que_nao_e_do_gerente"}]})
