def _mate_queue351(a, run, **extra):
    """The mate `orq` is alive and owns `run`; the dispatch queue holds one item of that Run (the coordinator queued it, so it carries no `mate`)."""
    _group(a)
    _manager(a)
    _fleet79(a)
    _mate_alive(a)
    c = _read_state(os.path.join(a.home, "cursor.json"))
    c["mates"]["orq"]["runs"] = ["run_mate"]
    _write_state(os.path.join(a.home, "cursor.json"), c)
    item = {"id": "fd351", "tipo": "despacho", "run": run, "titulo": "orq: Ticket 88", "modelo": SONNET, "effort": "medium", "prioridade": 1, "ticket": "88", "worktree": "current", "ts": "2026-10-02T10:00:00Z", "falhas": 0}
    _write_state(os.path.join(a.home, "fila-despacho.json"), {"itens": [{**item, **extra}]})


def test_ticket351_queue_item_of_a_mate_run_goes_to_the_mate_instead_of_giving_up():
    a = _panel79()
    _mate_queue351(a, "run_mate")
    r = a.orq("gerente", "absorver")
    assert r.returncode == 0, r.stderr
    assert not _queue79(a) and not _log(a, "started.log"), "the item left the queue and the coordinator started nothing"
    ev = a.events()
    assert not [e for e in ev if e["tipo"] == "despacho_fila" and e["op"] == "desistiu"], "forwarding to the mate is not giving up"
    assert [e["op"] for e in ev if e["tipo"] == "despacho_fila"][-1] == "mate", ev
    (pedido,) = [e for e in ev if e["tipo"] == "mate_pedido"]
    assert pedido["grupo"] == "orq" and pedido["fila"] == "fd351", pedido
    cmd = f"orq dispatch --run run_mate --ticket 88 --model {SONNET} --effort medium --priority 1 --worktree current"
    assert cmd in pedido["texto"], pedido["texto"]
    assert any("request p1" in " ".join(e) for e in _sent_notices(a, "term_mate")), "the mate's terminal received the request"  # the typed text is cut at NOTICE_MAX; the event keeps it whole


def test_ticket351_queue_item_of_the_coordinator_run_keeps_giving_up_after_three_errors():
    a = _panel79()
    _mate_queue351(a, "run_a")
    for _ in range(orq_mod.QUEUE_FAILURES):
        a.orq("gerente", "absorver", FAKE_FAIL_START_MODEL=SONNET)
    assert not _queue79(a) and [e["op"] for e in a.events() if e["tipo"] == "despacho_fila"][-1] == "desistiu"
    assert not [e for e in a.events() if e["tipo"] == "mate_pedido"], "a Run the mate does not own never goes to it"


def test_ticket79_real_system_reading_has_four_measures_on_macos():
    if sys.platform != "darwin":
        return
    before = os.environ.pop("ORQ_MAQUINA_LEITURA", None)
    try:
        l = orq_mod.machine_read()
    finally:
        if before:
            os.environ["ORQ_MAQUINA_LEITURA"] = before
    assert l["mem_livre_mb"] > 0 and 0 <= l["livre_pct"] <= 100 and l["carga"] >= 0 and l["ncpu"] >= 1, l
    assert set(l["rss_mb"]) == {"claude", "codex", "node", "docker"} and all(v >= 0 for v in l["rss_mb"].values()), l


# ---------- ticket 84: pausing stops the worker's background processes ----------

SNAP84 = "/bin/zsh -c source /Users/leo/.claude/shell-snapshots/snapshot-zsh-1.sh && eval '%s'"


def _procs84(a, stubborn=False):
    """Two claudes (f and i) with a folder each; f has a test shell with a node below it and a monitor (`until`) that, with `stubborn`, ignores SIGTERM; i has its own."""
    cl = "claude --dangerously-skip-permissions --model claude-opus-5-5"
    ps = [{"pid": 7, "ppid": 1, "rss": 1000, "args": "/usr/bin/outro-programa", "cwd": None},
          {"pid": 100, "ppid": 1, "rss": 600_000, "args": cl, "cwd": a.wt + "/f"},
          {"pid": 101, "ppid": 100, "rss": 150_000, "args": "node /opt/mcp/server.js", "cwd": None},
          {"pid": 150, "ppid": 100, "rss": 5000, "args": SNAP84 % "python3 -m pytest test_orq.py", "cwd": None},
          {"pid": 151, "ppid": 150, "rss": 5000, "args": "python3 -m pytest test_orq.py", "cwd": None},
          {"pid": 152, "ppid": 100, "rss": 5000, "args": SNAP84 % "until false; do sleep 1; done", "cwd": None, **({"ignora_term": True} if stubborn else {})},
          {"pid": 200, "ppid": 1, "rss": 600_000, "args": cl, "cwd": a.wt + "/i"},
          {"pid": 250, "ppid": 200, "rss": 5000, "args": SNAP84 % "bash scripts/e2e-infra.sh test", "cwd": None}]
    a.set("../procs.json", ps)
    a.env["ORQ_PROCESSOS"] = os.path.join(a.tmp.name, "procs.json")


def _pause84(stubborn=False):
    a = Env(run="run_a", ORQ_PAUSA_ESPERA_S="6", ORQ_PAUSA_POLL_S="0.2", ORQ_ENCERRA_ESPERA_S="1")
    _pause51(a)
    _procs84(a, stubborn)
    f = _write_pause51(a, "f")
    r = a.orq("pausar", "task_term_f", "--json")
    f.result()
    assert r.returncode == 0, r.stderr
    return a, json.loads(r.stdout)["pausados"][0], {p["pid"] for p in json.load(open(os.path.join(a.tmp.name, "procs.json")))}


def test_ticket84_pause_ends_worker_children_and_preserves_what_is_outside_the_tree():
    a, w, live = _pause84()
    assert w["estado"] == "pausado" and {p["pid"] for p in w["encerrados"]} == {150, 151, 152}, w
    assert live == {7, 100, 101, 200, 250}, "o agente e o MCP dele (o close leva), o outro worker e o programa alheio ficam"
    assert all(p["sinal"] == "TERM" for p in w["encerrados"])


def test_ticket84_child_that_ignores_sigterm_receives_sigkill():
    a, w, live = _pause84(stubborn=True)
    assert {p["pid"]: p["sinal"] for p in w["encerrados"]} == {150: "TERM", 151: "TERM", 152: "KILL"}, w
    assert 152 not in live and 250 in live


def test_ticket84_pause_event_lists_what_left():
    a, w, _ = _pause84(stubborn=True)
    ev = next(e for e in a.events() if e["tipo"] == "pausa_plano")
    assert sorted((p["pid"], p["sinal"]) for p in ev["encerrados"]) == [(150, "TERM"), (151, "TERM"), (152, "KILL")], ev
    assert "pytest" in next(p for p in ev["encerrados"] if p["pid"] == 151)["args"]


def test_ticket84_pressure_notice_shows_how_many_background_processes_each_worker_has():
    a = _panel79()
    _manager(a)
    _pause51(a)
    _procs84(a)
