def test_ticket60_hibernate_and_wake_by_hand_with_the_refusals_and_the_force():
    a = Env(run="run_a", **HIBERNATE60)
    _hibernate60(a)
    _procs60(a, extra=[{"pid": 150, "ppid": 100, "rss": 5000, "args": CHILD60, "cwd": None}])
    r = a.orq("hibernar", "task_term_w1", "--run", "run_a", "--forcar")
    assert r.returncode == 1 and "live child process" in r.stderr and not _log(a, "close.log"), "nem --forcar passa processo filho"
    _procs60(a, without=("w1",))
    r = a.orq("hibernar", "task_term_w1", "--run", "run_a")
    assert r.returncode == 1 and "--force" in r.stderr and not _log(a, "close.log"), r.stderr
    assert a.orq("hibernar", "task_term_w1", "--run", "run_a", "--forcar").returncode == 0 and _log(a, "close.log")
    r = a.orq("hibernar", "task_term_w1", "--run", "run_a")
    assert r.returncode == 1 and "hibernado" in r.stderr, "já hibernado"
    assert a.orq("hibernar", "task_nao_existe", "--run", "run_a").returncode == 1
    r = a.orq("acordar", "task_term_w1", "--texto", "o PR passou no CI")
    assert r.returncode == 0 and "retomado" in r.stdout, (r.stdout, r.stderr)
    (c,) = _log(a, "create.log")
    assert "o PR passou no CI" in c[c.index("--command") + 1]
    r = a.orq("acordar", "task_term_w1")
    assert r.returncode == 1 and "is not hibernated" in r.stderr, r.stderr


def test_ticket60_resume_defers_next_hibernation_and_the_pure_criterion():
    cfg = {"min": 15, "externa_min": 2}
    now_at = datetime.now(timezone.utc)
    base = {"estado": "parado", "turno": "parado", "task": "task_t", "turno_inicio": _z60(40), "turno_fim": _z60(20)}
    m = orq_mod.hibernate_reason
    assert m(base, now_at, cfg) == "idle at the prompt"
    assert m(base, now_at, cfg, woken_at=_z60(1)) is None, "acordado há 1 min: o turno novo ainda não está no turnos.json"
    assert m(base, now_at, cfg, woken_at=_z60(30)) == "idle at the prompt"
    assert m({**base, "turno_fim": _z60(10)}, now_at, cfg) is None
    assert m({**base, "turno_fim": _z60(10)}, now_at, cfg, pending=[{"id": "p", "task": "task_t"}]) == "waiting: pending item p"
    assert m({**base, "turno_inicio": _z60(5)}, now_at, cfg) is None, "turno aberto depois do fim"
    for state in ("travado", "perguntando", "nao_comecou", "hibernado", "liberado"):
        assert m({**base, "estado": state}, now_at, cfg) is None, state
    assert m({**base, "tela": "1 shell still running (tela)"}, now_at, cfg) is None
    assert m({**base, "turno": "aberto"}, now_at, cfg) is None
    assert m({**base, "estado": "entregue", "turno": "unknown"}, now_at, cfg) == "delivered and not released"
    assert m({**base, "estado": "entregue", "turno": "unknown", "retido": "external_terminal"}, now_at, cfg) is None


def test_ticket60_rss_and_child_process_over_the_process_list():
    ps = [{"pid": 1, "ppid": 0, "rss": 9_000_000, "args": "/sbin/launchd", "cwd": None},
          {"pid": 10, "ppid": 1, "rss": 512_000, "args": "claude --model x", "cwd": "/wt/a"}, {"pid": 11, "ppid": 10, "rss": 256_000, "args": "node mcp.js", "cwd": None},
          {"pid": 12, "ppid": 11, "rss": 256_000, "args": "node filho-do-mcp.js", "cwd": None},
          {"pid": 20, "ppid": 1, "rss": 1_024_000, "args": "codex --yolo", "cwd": "/wt/b"}]
    assert orq_mod.agents_rss_mb(ps) == 2000 and orq_mod.agents_rss_mb(None) is None
    assert orq_mod._worker_process(ps, "/wt/a", "claude") == ([10], False)
    assert orq_mod._worker_process(ps + [{"pid": 30, "ppid": 12, "rss": 1, "args": CHILD60, "cwd": None}], "/wt/a", "claude") == ([10], True), "o filho do filho conta"
    assert orq_mod._worker_process(ps, "/wt/outra", "claude") == ([], None)
    assert orq_mod._worker_process(ps, "/wt/b", "codex") == ([20], None), "o Codex não tem padrão de filho: sem prova"
    assert orq_mod._worker_process(None, "/wt/a", "claude") == ([], None)


# ---------- ticket 78: orq retro (deterministic collector of failure signals) ----------

def _ev78(type_name, ts, **kw):
    return {"ts": ts, "tipo": type_name, **kw}


def _events78():
    """A week of fixture with at least one case of each event signal; the transcript and PR ones come from other tests."""
    d = {"run": "run_x", "task": "task_a", "dispatch": "ctx_a"}
    return [
        _ev78("despacho", "2026-09-29T10:00:00Z", **d, titulo="orq: coisa A", modelo="claude-sonnet-5-5", effort="high", worktree="/wt/a"),
        _ev78("despacho", "2026-09-29T10:05:00Z", run="run_x", task="task_b", dispatch="ctx_b", titulo="orq: coisa B", modelo="claude-opus-5-5", effort="xhigh", worktree="/wt/b"),
        _ev78("nao_iniciou", "2026-09-29T10:06:00Z", run="run_x", task="task_b", dispatch="ctx_b", terminal="term_b"),
        _ev78("controle", "2026-09-29T10:07:00Z", acao="relancar", resultado="iniciado", run="run_x", task="task_b", dispatch="ctx_b", nota="a sessão abriu mas nunca recebeu o spec"),
        _ev78("controle", "2026-09-29T10:08:00Z", acao="relancar", resultado="falhou", run="run_x", task="task_b", dispatch="ctx_b", erro="cannot retry"),
        _ev78("controle", "2026-09-29T10:09:00Z", acao="interromper", resultado="ok", run="run_x", task="task_a", dispatch="ctx_a"),
        _ev78("steer", "2026-09-29T11:00:00Z", **d, texto="use outra chave", msg_id="msg_1"),
        _ev78("steer", "2026-09-29T11:10:00Z", **d, texto="outro ajuste", msg_id="msg_2"),
        _ev78("steer_fim", "2026-09-29T11:20:00Z", **d, msg_id="msg_2", motivo="lido", fonte="transcrito"),
        _ev78("steer_reentrega", "2026-09-29T11:05:00Z", **d, msg_id="msg_1", tentativa=1),
        _ev78("resposta_worker", "2026-09-29T12:00:00Z", **d, msg_id="msg_9", texto="serve a leitura padrão"),
        _ev78("worker_done", "2026-09-29T13:00:00Z", **d, msg="msg_d1", outcome="failed", subject="não deu"),
        _ev78("worker_done", "2026-09-29T13:01:00Z", run="run_x", task="task_b", dispatch="ctx_b", msg="msg_d2", outcome="succeeded", subject="pronto"),
        _ev78("entrega", "2026-09-29T13:02:00Z", run="run_x", task="task_b", dispatch="ctx_b", msg="msg_d2", avisos=[f"delivery without commit: árvore suja em {orq_mod.ORQ_INSTALL}"]),
        _ev78("fim_dispatch", "2026-09-29T13:10:00Z", run="run_x", task="task_a", dispatch="ctx_a", motivo="sem worker_done", caminho="/wt/a", sujo=3, sem_push=0),
        _ev78("fim_dispatch", "2026-09-29T13:11:00Z", run="run_x", task="task_b", dispatch="ctx_b", motivo="entregue", caminho="/wt/b", sujo=0, sem_push=2),
        _ev78("gate_aviso", "2026-09-29T14:00:00Z", abertas=["e1", "e2"], sessao="s1"),
        _ev78("gate_aviso", "2026-09-29T14:05:00Z", abertas=["e2"], sessao="s1"),
        _ev78("intake", "2026-09-29T14:10:00Z", entrada="e1", efeito="descartado", nota="já tratado"),
        _ev78("intake", "2026-09-29T14:11:00Z", entrada="e2", efeito="tarefa", ref="task_a"),
        _ev78("alerta", "2026-09-29T15:00:00Z", alerta="steer_nao_lido", **d),
        _ev78("binding_perdido", "2026-09-29T15:30:00Z", run="run_x", sessao="s1"),
        _ev78("entrada", "2026-09-29T13:20:00Z", origem="usuario", texto="não, era o outro arquivo", id="e7"),
        _ev78("entrada", "2026-09-29T20:00:00Z", origem="usuario", texto="não sei se vale, o que acha?", id="e8"),  # far from any delivery: it is not a correction
    ]


def _signals78(r):
    return {k: v["n"] for k, v in r["sinais"].items()}


def test_ticket78_retro_counts_and_groups_each_signal_from_events():
    r = orq_mod.retro_collection(_events78(), "2026-09-29T00:00:00Z", "2026-10-01T00:00:00Z")
    n = _signals78(r)
    assert n["nao_iniciou"] == 1 and n["retry"] == 1 and n["controle_falhou"] == 1 and n["intervencao"] == 1, n
    assert n["steer_sem_leitura"] == 1 and n["steer_reentregue"] == 1, n  # msg_2 was read; msg_1 was not
    assert n["pergunta_de_worker"] == 1 and n["worker_falhou"] == 1 and n["sem_entrega"] == 1, n
    assert n["liberado_sujo"] == 1 and n["liberado_sem_push"] == 1 and n["entrega_com_aviso"] == 1 and n["checkout_em_uso"] == 1, n
    assert n["entrada_sem_tratamento"] == 2 and n["intake_descartado"] == 1 and n["alerta"] == 1 and n["binding_perdido"] == 1, n  # e2 twice counts as one
    assert n["correcao_do_usuario"] == 1, n
    by = r["sinais"]["nao_iniciou"]["casos"][0]
    assert by["titulo"] == "orq: coisa B" and by["modelo"] == "claude-opus-5-5" and by["effort"] == "xhigh", by
    assert "nunca recebeu o spec" in by["detalhe"], by  # the reason comes from the relaunch note
    assert by["ponteiro"].startswith("events.jsonl"), by
    assert r["falhas"] == sum(v for v in n.values() if v is not None) and r["falhas"] > 10, r["falhas"]
    m = r["por_modelo"]
    assert m["claude-opus-5-5/xhigh"]["despachos"] == 1 and m["claude-opus-5-5/xhigh"]["retry"] == 1, m
    assert m["claude-sonnet-5-5/high"]["worker_falhou"] == 1 and m["claude-sonnet-5-5/high"]["pergunta_de_worker"] == 1, m


def test_ticket78_retro_steer_after_delivery_says_worker_delivered_without_the_adjustment():
    ev = [_ev78("steer", "2026-09-29T11:00:00Z", task="t", dispatch="ctx_z", texto="x", msg_id="msg_z"),
          _ev78("worker_done", "2026-09-29T11:09:00Z", task="t", dispatch="ctx_z", outcome="succeeded")]
    case_item = orq_mod.retro_collection(ev, "2026-09-29T00:00:00Z", "2026-10-01T00:00:00Z")["sinais"]["steer_sem_leitura"]["casos"][0]
    assert "delivered" in case_item["detalhe"], case_item


def test_ticket78_retro_respects_the_window_and_project_filter():
    r = orq_mod.retro_collection(_events78(), "2026-09-30T00:00:00Z", "2026-10-01T00:00:00Z")
    assert r["falhas"] == 0 and all(v["n"] == 0 for k, v in r["sinais"].items() if v["n"] is not None), r
    p = orq_mod.retro_collection(_events78(), "2026-09-29T00:00:00Z", "2026-10-01T00:00:00Z", project="/wt/b")
    assert _signals78(p)["nao_iniciou"] == 1 and _signals78(p)["sem_entrega"] == 0 and _signals78(p)["liberado_sujo"] == 0, _signals78(p)


def test_ticket78_retro_fix_only_counts_right_after_a_delivery_and_with_the_right_word():
    base = [_ev78("worker_done", "2026-09-29T10:00:00Z", task="t", dispatch="ctx_c", outcome="succeeded")]
    def n(text_value, ts):
        ev = base + [_ev78("entrada", ts, origem="usuario", texto=text_value, id="e1")]
        return orq_mod.retro_collection(ev, "2026-09-29T00:00:00Z", "2026-10-01T00:00:00Z")["sinais"]["correcao_do_usuario"]["n"]
    assert n("Ops, errei o nome", "2026-09-29T10:10:00Z") == 1
    assert n("ajuste: troque o título", "2026-09-29T10:10:00Z") == 1
    assert n("Não era isso", "2026-09-29T10:10:00Z") == 1
    assert n("ótimo, siga", "2026-09-29T10:10:00Z") == 0
    assert n("não era isso", "2026-09-29T12:00:00Z") == 0, "duas horas depois já não é reação à entrega"
    assert n("nota: o ajuste ficou bom", "2026-09-29T10:10:00Z") == 0, "só a primeira palavra conta"


def _transcribed78(d, session, call_list, cwd="/wt/a"):
    """A Claude Code transcript with one assistant line per tool call, plus a message that only quotes the commands."""
    os.makedirs(os.path.join(d, "proj"), exist_ok=True)
    with open(os.path.join(d, "proj", session + ".jsonl"), "w") as f:
        f.write(json.dumps({"type": "assistant", "cwd": cwd, "message": {"content": [{"type": "text", "text": "não vou rodar git push nem editar ~/.agents/skills/x"}]}}) + "\n")
        for item_name, entry in call_list:
            f.write(json.dumps({"type": "assistant", "cwd": cwd, "timestamp": "2026-09-29T10:30:00Z", "message": {"content": [{"type": "tool_use", "name": item_name, "input": entry}]}}) + "\n")


def test_ticket78_retro_finds_user_rules_violated_in_worker_transcript():
    with tempfile.TemporaryDirectory() as d:
        _transcribed78(d, "sess1", [
            ("Bash", {"command": "git push origin feat/x"}),
            ("Bash", {"command": 'git commit -m "feat: x\n\nCo-Authored-By: Claude <noreply@anthropic.com>"'}),
            ("Edit", {"file_path": "/Users/leo/.agents/skills/retro/SKILL.md", "old_string": "a", "new_string": "b"}),
            ("Bash", {"command": "gh pr merge 12 --squash"}),
            ("Bash", {"command": "git merge feat/outra", "cwd": "x"}),
            ("Bash", {"command": "git status && git commit -m 'fix: ok'"}),
            ("Read", {"file_path": "/Users/leo/.agents/AGENTS.md"}),
        ], cwd=orq_mod.ORQ_INSTALL)
        ev = [_ev78("despacho", "2026-09-29T10:00:00Z", run="r", task="task_a", dispatch="ctx_a", titulo="orq: A", modelo="m", effort="high", worktree="/wt/a")]
        turns = {"ctx_a": {"task": "task_a", "sessao": "sess1", "inicio": "2026-09-29T10:00:00Z"}}
        r = orq_mod.retro_collection(ev, "2026-09-29T00:00:00Z", "2026-10-01T00:00:00Z", turns=turns, projects=d)
        cases = r["sinais"]["regra_violada"]["casos"]
        rules = sorted(c["regra"] for c in cases)
        assert rules == ["agents_global", "checkout_em_uso_do_orq", "producao", "push_de_worker", "trailer"], rules
        assert all("sess1.jsonl" in c["ponteiro"] and c["dispatch"] == "ctx_a" for c in cases), cases
        without = orq_mod.retro_collection(ev, "2026-09-29T00:00:00Z", "2026-10-01T00:00:00Z")
        assert without["sinais"]["regra_violada"]["n"] is None, "sem transcritos o sinal é 'não consultado', não zero"


def test_ticket78_retro_rule_only_counts_in_real_command_not_in_heredoc_or_quoted_text():
    with tempfile.TemporaryDirectory() as d:
        _transcribed78(d, "sess2", [
            ("Bash", {"command": "python3 - <<'E'\ns = 'git push origin x; gh pr merge 1'\nE"}),
            ("Bash", {"command": 'echo "git push" && grep -n \'gh workflow run\' README.md'}),
            ("Bash", {"command": "cat > /tmp/x <<'E'\ngit commit -m y Co-Authored-By: z\nE"}),
        ])
        _transcribed78(d, "sess3", [
            ("Bash", {"command": "cd " + orq_mod.ORQ_INSTALL + " && git merge feat/x"}),
            ("Bash", {"command": "git commit -m \"$(cat <<'EOF'\nfeat: x\n\nCo-Authored-By: Claude <n@a.com>\nEOF\n)\""}),
            ("Bash", {"command": "ln -s ~/.claude/orq/skills/x ~/.agents/skills/x"}),
        ], cwd="/wt/a")
        ev = [_ev78("despacho", "2026-09-29T10:00:00Z", run="r", task="ta", dispatch="ctx_1", titulo="A", modelo="m", effort="high"),
              _ev78("despacho", "2026-09-29T10:01:00Z", run="r", task="tb", dispatch="ctx_2", titulo="B", modelo="m", effort="high")]
        turns = {"ctx_1": {"sessao": "sess2"}, "ctx_2": {"sessao": "sess3"}}
        cases = orq_mod.retro_collection(ev, "2026-09-29T00:00:00Z", "2026-10-01T00:00:00Z", turns=turns, projects=d)["sinais"]["regra_violada"]["casos"]
        assert [(c["dispatch"], c["regra"]) for c in cases if c["dispatch"] == "ctx_1"] == [], cases
        assert sorted(c["regra"] for c in cases if c["dispatch"] == "ctx_2") == ["agents_global", "checkout_em_uso_do_orq", "trailer"], cases


