def _alive_repo55(branches):
    """Temporary repository in the installation format (orq.py, orqlib.py, scripts/integrar.py) with one branch per item of `branches`
    ({name: {file: text}}). Returns (live, environment) with the test ORQ_WT_DIR."""
    t = tempfile.mkdtemp()
    alive = os.path.join(t, "orq")
    os.makedirs(os.path.join(alive, "scripts"))
    for f in sorted(os.listdir(HERE)):  # the root modules that orqlib imports (fail_safe, backlog, ...), without the tests
        if f.endswith(".py") and not f.startswith(("test_", "suite_")) and os.path.isfile(os.path.join(HERE, f)):
            shutil.copy(os.path.join(HERE, f), alive)
    shutil.copy(os.path.join(HERE, "scripts", "integrar.py"), os.path.join(alive, "scripts"))
    open(os.path.join(alive, "nota.txt"), "w").write("a\nb\nc\n")
    env = {**os.environ, "ORQ_WT_DIR": os.path.join(t, "orq-wt"), "ORQ_TESTES": "true", "ORQ_LOG": os.path.join(t, "orq.log"),
           "ORQ_HOME": os.path.join(t, "home"), "ORQ_ISSUES": os.path.join(t, "issues"), "ORQ_ORCA": "/nao/existe/orca", "ORQ_NO_BG": "1",  # the integrator cycle writes to the orq: never to the real one
           "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t", "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@t"}
    g = lambda *a, cwd=alive: subprocess.run(["git", *a], cwd=cwd, env=env, capture_output=True, text=True, check=True)  # noqa: E731
    g("init", "-q", "-b", "main")
    g("add", "-A")
    g("commit", "-qm", "base")
    for item_name, files_set in branches.items():
        g("checkout", "-qb", item_name, "main")
        for file_path, txt in files_set.items():
            open(os.path.join(alive, file_path), "w").write(txt)
        g("add", "-A")
        g("commit", "-qm", item_name)
    g("checkout", "-q", "main")
    return alive, env, g


def test_ticket55_conflict_in_integration_does_not_touch_installed_orq():
    alive, env, g = _alive_repo55({"um": {"nota.txt": "a\num\nc\n"}, "dois": {"nota.txt": "a\ndois\nc\n"}})
    before = g("rev-parse", "HEAD").stdout
    r = subprocess.run([sys.executable, os.path.join(alive, "scripts", "integrar.py"), "um", "dois"], cwd=alive, env=env, capture_output=True, text=True)
    assert r.returncode != 0 and "conflict" in r.stdout + r.stderr, r.stdout + r.stderr
    assert g("rev-parse", "HEAD").stdout == before and g("status", "--porcelain").stdout == "", "a main viva não anda nem suja"
    wt = os.path.join(env["ORQ_WT_DIR"], "integra-um-dois")
    assert "<<<<<<<" in open(os.path.join(wt, "nota.txt")).read(), "o conflito vive só na worktree"
    # the simulated conflict also in the worktree's orqlib.py: the installed orq keeps importing
    open(os.path.join(wt, "orqlib.py"), "a").write("\n<<<<<<< HEAD\nx\n=======\ny\n>>>>>>> dois\n")
    ok = subprocess.run([sys.executable, os.path.join(alive, "orq.py"), "--help"], capture_output=True, text=True)
    assert ok.returncode == 0 and "SyntaxError" not in ok.stderr, ok.stderr
    assert subprocess.run([sys.executable, "-c", "import ast,sys; ast.parse(open(sys.argv[1]).read())", os.path.join(wt, "orqlib.py")],
                          capture_output=True).returncode != 0, "a worktree de fato quebrou"


def test_ticket55_main_only_advances_by_fast_forward_after_the_tests():
    alive, env, g = _alive_repo55({"um": {"um.txt": "1\n"}, "dois": {"dois.txt": "2\n"}})
    integrate = os.path.join(alive, "scripts", "integrar.py")
    before = g("rev-parse", "HEAD").stdout
    r = subprocess.run([sys.executable, integrate, "um", "dois"], cwd=alive, env={**env, "ORQ_TESTES": "false"}, capture_output=True, text=True)
    assert r.returncode != 0 and g("rev-parse", "HEAD").stdout == before, "teste vermelho: a main fica onde estava"
    shutil.rmtree(os.path.join(env["ORQ_WT_DIR"], "integra-um-dois"))
    g("worktree", "prune")
    g("branch", "-D", "integra/um-dois")
    r = subprocess.run([sys.executable, integrate, "um", "dois"], cwd=alive, env=env, capture_output=True, text=True)
    assert r.returncode == 0, r.stdout + r.stderr
    assert os.path.exists(os.path.join(alive, "um.txt")) and os.path.exists(os.path.join(alive, "dois.txt")), "a main viva recebeu os dois"
    assert g("rev-list", "--merges", "-n1", "HEAD").stdout.strip(), "o merge foi feito na worktree e chegou por fast-forward"
    assert not os.path.exists(os.path.join(env["ORQ_WT_DIR"], "integra-um-dois")), "worktree removida depois de entrar"


def test_ticket216_a_red_night_replay_keeps_main_and_leaves_a_pending_line_the_manager_reads():
    alive, env, g = _alive_repo55({"um": {"um.txt": "1\n"}})
    integrate, cycles = os.path.join(alive, "scripts", "integrar.py"), os.path.join(env["ORQ_WT_DIR"], "integracao", "ciclos.log")
    before = g("rev-parse", "HEAD").stdout
    r = subprocess.run([sys.executable, integrate, "um"], cwd=alive, env={**env, "ORQ_REPLAY": "false"}, capture_output=True, text=True)
    assert r.returncode != 0 and "night replay failing" in r.stderr and g("rev-parse", "HEAD").stdout == before, r.stdout + r.stderr
    (line,) = open(cycles).read().splitlines()
    assert line.startswith("[PENDENTE: main did not advance, night replay failed]") and "integra/um" in line, line
    cycles_before = orq_mod.CYCLES_LOG
    orq_mod.CYCLES_LOG = cycles
    try:
        assert orq_mod._integrator_pending([])["linha"] == line, "the manager's ticket 137 reader turns it into a notice"
    finally:
        orq_mod.CYCLES_LOG = cycles_before
    shutil.rmtree(os.path.join(env["ORQ_WT_DIR"], "integra-um"))
    g("worktree", "prune")
    g("branch", "-D", "integra/um")
    r = subprocess.run([sys.executable, integrate, "um"], cwd=alive, env={**env, "ORQ_REPLAY": "true"}, capture_output=True, text=True)
    assert r.returncode == 0 and re.search(r"night replay ok in \d+\.\d s", r.stdout), r.stdout + r.stderr


def test_ticket55_advance_refuses_forgotten_conflict_marker():
    alive, env, g = _alive_repo55({"um": {"nota.txt": "a\num\nc\n"}, "dois": {"nota.txt": "a\ndois\nc\n"}})
    integrate = os.path.join(alive, "scripts", "integrar.py")
    subprocess.run([sys.executable, integrate, "um", "dois"], cwd=alive, env=env, capture_output=True, text=True)
    wt = os.path.join(env["ORQ_WT_DIR"], "integra-um-dois")
    g("add", "nota.txt", cwd=wt)  # "resolved" without removing the markers
    g("commit", "-qm", "merge", cwd=wt)
    before = g("rev-parse", "HEAD").stdout
    r = subprocess.run([sys.executable, integrate, "--avancar", wt], cwd=alive, env=env, capture_output=True, text=True)
    assert r.returncode != 0 and "marker" in r.stdout + r.stderr and g("rev-parse", "HEAD").stdout == before, r.stdout + r.stderr
    open(os.path.join(wt, "nota.txt"), "w").write("a\num e dois\nc\n")
    g("commit", "-qam", "resolve", cwd=wt)
    r = subprocess.run([sys.executable, integrate, "--avancar", wt], cwd=alive, env=env, capture_output=True, text=True)
    assert r.returncode == 0 and open(os.path.join(alive, "nota.txt")).read() == "a\num e dois\nc\n", r.stdout + r.stderr



def test_ticket328_advance_after_a_conflict_only_in_tests_or_docs_runs_the_affected_tests():
    light = {"um": {"README.md": "um\n", "x.txt": "1\n"}, "dois": {"README.md": "dois\n"}}
    for branches, resolved, expected in ((light, "README.md", "affected"), ({"um": {"nota.txt": "um\n"}, "dois": {"nota.txt": "dois\n"}}, "nota.txt", "full")):
        alive, env, g = _alive_repo55(branches)
        integrate, wt = os.path.join(alive, "scripts", "integrar.py"), os.path.join(env["ORQ_WT_DIR"], "integra-um-dois")
        ran = os.path.join(alive, "..", "ran.txt")  # the tests run in the worktree, which goes away
        env = {**env, "ORQ_TESTES": f"echo full > {ran}", "ORQ_TESTES_AFETADOS": f"echo affected > {ran}"}
        r = subprocess.run([sys.executable, integrate, "um", "dois"], cwd=alive, env=env, capture_output=True, text=True)
        assert r.returncode != 0 and "conflict" in r.stderr, r.stderr
        open(os.path.join(wt, resolved), "w").write("um e dois\n")
        g("commit", "-qam", "resolve", cwd=wt)
        r = subprocess.run([sys.executable, integrate, "--avancar", wt], cwd=alive, env=env, capture_output=True, text=True)
        assert r.returncode == 0 and open(ran).read() == expected + "\n", (expected, r.stdout + r.stderr)
        assert ("running the affected tests" in r.stdout) == (expected == "affected"), r.stdout
    alive, env, g = _alive_repo55({"um": {"um.txt": "1\n"}})
    ran = os.path.join(alive, "..", "ran.txt")
    r = subprocess.run([sys.executable, os.path.join(alive, "scripts", "integrar.py"), "um"], cwd=alive, env={**env, "ORQ_TESTES": f"echo full > {ran}"}, capture_output=True, text=True)
    assert r.returncode == 0 and open(ran).read() == "full\n", "a cycle without a conflict runs the full suite once, on the final tree"

def test_ticket55_hook_with_failed_import_exits_0_with_no_output_and_writes_the_log():
    t = tempfile.mkdtemp()
    for f in ("orq.py", "precompact.py", "fail_safe.py", "orqpaths.py"):
        shutil.copy(os.path.join(HERE, f), t)
    open(os.path.join(t, "orqlib.py"), "w").write("<<<<<<< HEAD\nx = 1\n=======\nx = 2\n>>>>>>> outro\n")
    log = os.path.join(t, "orq.log")
    env = {**os.environ, "ORQ_LOG": log, "ORCA_TERMINAL_HANDLE": "term_x", "ORQ_HOME": os.path.join(t, "home")}
    outs = []
    for cmd in (["orq.py", "hook", "session"], ["orq.py", "hook", "prligar"], ["precompact.py"], ["precompact.py", "retomar"]):
        r = subprocess.run([sys.executable, os.path.join(t, cmd[0]), *cmd[1:]], input="{}", env=env, capture_output=True, text=True)
        assert (r.returncode, r.stderr) == (0, ""), (cmd, r.returncode, r.stdout, r.stderr)
        outs.append(r.stdout)
    assert [bool(x) for x in outs] == [True, False, False, False], "only the first failure warns (ticket 228); the rest stay silent for 10 min"
    assert open(log).read().count("import failed") == 4, open(log).read()
    # the cleanup hook imports the orq of the installation (HOME/.claude/orq)
    home_dir = os.path.join(t, "casa")
    os.makedirs(os.path.join(home_dir, ".claude", "orq"))
    for f in ("orq.py", "orqlib.py", "fail_safe.py", "orqpaths.py"):
        shutil.copy(os.path.join(t, f), os.path.join(home_dir, ".claude", "orq"))
    r = subprocess.run([sys.executable, CLEAN_SCRIPT], input="{}", env={**env, "HOME": home_dir}, capture_output=True, text=True)
    assert (r.returncode, r.stdout, r.stderr) == (0, "", ""), (r.returncode, r.stdout, r.stderr)
    # outside a hook the error stays loud: whoever types `orq status` needs to see the cause
    r = subprocess.run([sys.executable, os.path.join(t, "orq.py"), "status"], env=env, capture_output=True, text=True)
    assert r.returncode != 0 and "SyntaxError" in r.stderr, r.stderr


# ---------- ticket 85: pressure separates what belongs to orq from what does not, and orq's Run is exempt ----------

def _p85(pid, ppid, cpu, args, rss=100_000):
    return {"pid": pid, "ppid": ppid, "cpu": cpu, "rss": rss, "args": args}


# the worker (claude and its node) and what runs on the machine outside orq
_WORKER85 = lambda cpu: [_p85(100, 1, 3, "/opt/homebrew/bin/claude --model x"), _p85(101, 100, cpu, "node /x/vitest.js")]
_OUTSIDE85 = [_p85(200, 1, 146, "/System/Library/Frameworks/CoreServices.framework/Metadata.framework/Support/mds_stores"),
           _p85(201, 1, 50, "/Applications/OrbStack.app/Contents/Frameworks/OrbStack Helper.app/Contents/MacOS/OrbStack Helper"),
           _p85(202, 1, 27, "/Applications/OrbStack.app/Contents/MacOS/OrbStack"), _p85(203, 1, 4, "/usr/bin/ssh")]


def _notice_text85(a):
    (env,) = _log(a, "send.log")
    return _whole_notice(env[env.index("--text") + 1])


def test_ticket85_load_from_outside_holds_dispatch_lists_culprits_and_does_not_suggest_pause():
    a = _panel79()
    _manager(a)
    _fleet79(a, live=[("Vivo", SONNET)])
    a.orq("maquina", "set", "pausar_sob_pressao", "true")
    a.machine(carga=14.2, processes=[*_WORKER85(13), *_OUTSIDE85])
    out = json.loads(_dispatch79(a, "Ticket 05", 2).stdout)
    assert out["estado"] == "enfileirado" and "load 14.2 (maximum 12)" in out["motivo"] and "mds_stores 146%, OrbStack 77%" in out["motivo"], out
    a.orq("gerente", "absorver")
    text_value = _notice_text85(a)
    assert "mds_stores 146%, OrbStack 77%" in text_value and "outside orq" in text_value and "does not help" in text_value, text_value
    assert "orq pausar" not in text_value and not _log(a, "close.log"), "nem sugere nem pausa sozinho, mesmo com pausar_sob_pressao ligado"
    assert not _log(a, "started.log") and len(_queue79(a)) == 1, "o despacho novo segue seguro"
    assert [(e["tipo"], e["causa"]) for e in a.events() if e["tipo"] == "maquina_aviso"] == [("maquina_aviso", "fora")]
    assert "load by owner: orq 16% of CPU" in a.orq("maquina").stdout and "outside orq 227%" in a.orq("maquina").stdout


def test_ticket85_load_from_workers_suggests_pausing_the_lowest_priority():
    a = _panel79()
    _manager(a)
    _fleet79(a, live=[("Vivo", SONNET)])
    a.machine(carga=14.2, processes=[*_WORKER85(600), *_OUTSIDE85])
    assert json.loads(_dispatch79(a, "Ticket 05", 2).stdout)["estado"] == "enfileirado"
    a.orq("gerente", "absorver")
    text_value = _notice_text85(a)
    assert "orq pause task_term_v0" in text_value and "outside orq" not in text_value, text_value
    assert [e["causa"] for e in a.events() if e["tipo"] == "maquina_aviso"] == ["orq"]


def test_ticket85_below_limit_nothing_happens_even_with_heavy_outside_process():
    a = _panel79()
    _manager(a)
    _fleet79(a, live=[("Vivo", SONNET)])
