    _manager(a)
    _fleet79(a, live=[("V", SONNET)] * 4)
    _runs85(a, "Orquestrador: x")
    assert json.loads(_dispatch79(a, "Ticket 05", 1).stdout)["dispatchId"], "4/4 workers vivos e o Run isento sobe"
    a.machine(mem_free_mb=800, free_pct=5)
