def test_dispatch_queued_by_the_mate_drains_with_the_mate_handle():
    a = Env()
    os.makedirs(a.home, exist_ok=True)
    with open(os.path.join(a.home, "gerente.json"), "w") as f:
        json.dump({"coordenador": "term_coord", "gerente": "term_ger", "runs": []}, f)
    with InProcess(a):
        os.environ.update(ORQ_MATE="orq", ORCA_TERMINAL_HANDLE="term_mate")
        r = orq_mod._enqueue_dispatch("sem vaga", "run_mate", "orq: t", "# orq: t\n", "claude-sonnet-5-5", "medium", None, None, None, None, None, 2, "claude")
        it = next(i for i in orq_mod.dispatch_queue_items() if i["id"] == r["fila"])
        assert it["coord"] == "term_mate" and it["mate"] == "orq", it
        del os.environ["ORQ_MATE"]
        os.environ["ORCA_TERMINAL_HANDLE"] = "term_ger"
        seen_item, before = {}, orq_mod.dispatch_worker
        orq_mod.dispatch_worker = lambda *x, **k: seen_item.update(h=os.environ.get("ORCA_TERMINAL_HANDLE"), m=os.environ.get("ORQ_MATE")) or {"dispatchId": "ctx_1"}
        try:
            orq_mod._promoted_from_queue(it)
        finally:
            orq_mod.dispatch_worker = before
        assert seen_item == {"h": "term_mate", "m": "orq"}, seen_item
        assert os.environ["ORCA_TERMINAL_HANDLE"] == "term_ger" and "ORQ_MATE" not in os.environ


