# ---------- orq perguntar: decision through Lavish in both harnesses (ticket 75) ----------

FALSE_LAVISH = """#!/usr/bin/env python3
import os, sys
if sys.argv[1] == "poll":
    sys.stdout.write(open(os.environ["FAKE_POLL"]).read() if os.environ.get("FAKE_POLL") else "session:\\n  status: ended\\n")
    sys.exit(0)
print('session:\\n  url: "http://127.0.0.1:4387/session/abc"\\n  status: opened')
"""


def _ask_user(a, poll=None, *args, **env):
    bin_ = os.path.join(a.tmp.name, "lavish")
    with open(bin_, "w") as f:
        f.write(FALSE_LAVISH)
    os.chmod(bin_, 0o755)
    if poll is not None:
        env["FAKE_POLL"] = _lote(a, poll, "poll-perg.json")
    return a.orq("perguntar", "--id", "badge", "--pergunta", "Qual badge?", "--opcao", "A: ponto", "--opcao", "B: texto", *args, ORQ_LAVISH=bin_, **env)


def _all_calls(a):
    return [json.loads(x) for x in open(os.path.join(a.fake, "calls.log"))]


def test_ask_builds_the_page_with_the_options_and_the_recommended_and_opens_in_orca():
    a = Env()
    r = _ask_user(a, None, "--recomendada", "2", "--sem-poll")
    assert r.returncode == 0, r.stderr
    output = json.loads(r.stdout)
    page_data = open(output["pagina"]).read()
    assert 'value="A: ponto"' in page_data and 'value="B: texto"' in page_data and "Qual badge?" in page_data
    assert page_data.count('class="rec"') == 1 and page_data.index("B: texto") < page_data.index('class="rec"'), "só a recomendada leva a marca"
    assert " checked" not in page_data, "nenhuma opção pré-selecionada: Enter solto não decide pelo usuário"
    assert output["url"] == "http://127.0.0.1:4387/session/abc" and output["efeito"] == "aberta"
    assert "badge" in _pending_ids(a), "a decisão nasce como pendência"
    assert any("http://127.0.0.1:4387/session/abc" in " ".join(c) for c in _all_calls(a)), "a aba abre no browser do Orca"


