def test_ticket77_installer_appends_at_the_end_and_never_reorders_existing_groups():
    example = {"hooks": {"Stop": [{"hooks": [{"type": "command", "command": "python3 ~/.claude/orq/orq.py hook stop codex"}]}],
                         "SessionStart": [{"hooks": [{"type": "command", "command": "novo-do-orq"}]}]}}
    current = {"hooks": {"SessionStart": [{"hooks": [{"command": "a"}]}, {"hooks": [{"command": "b"}]}],
                       "Stop": [{"hooks": [{"command": "graphify hook-check"}]}]}}
    new, add = orq_mod.merge_codex_hooks(current, example)
    assert new["hooks"]["SessionStart"][:2] == current["hooks"]["SessionStart"], "os grupos existentes ficam nas mesmas posições"
    assert new["hooks"]["SessionStart"][2]["hooks"][0]["command"] == "novo-do-orq" and add == [("Stop", 1), ("SessionStart", 2)]
    assert new["hooks"]["Stop"][0] == current["hooks"]["Stop"][0]
    again, add2 = orq_mod.merge_codex_hooks(new, example)
    assert add2 == [] and again == new, "rodar de novo não duplica"
    empty, add3 = orq_mod.merge_codex_hooks({}, example)
    assert len(add3) == 2 and empty["hooks"]["Stop"] == example["hooks"]["Stop"]
    assert current["hooks"]["Stop"] == [{"hooks": [{"command": "graphify hook-check"}]}], "a entrada não é mutada"


# ---------- ticket 97: `orq start` binds the coordinator that is already open, in any harness ----------

def _harness_hooks(a, agent, trust=True):
    """Installs the harness's orq hooks in the Amb (the repository example); on Codex, with the trust of all of them in [hooks.state] when `trust`."""
    example = os.path.join(os.path.dirname(ORQ), "settings.hooks.example.json" if agent == "claude" else "codex.hooks.example.json")
    if agent == "claude":
        shutil.copy(example, a.env["ORQ_CLAUDE_SETTINGS"])
        return
    shutil.copy(example, a.env["ORQ_CODEX_HOOKS"])
    hooks = json.load(open(example))["hooks"]
    keys = [f"{a.env['ORQ_CODEX_HOOKS']}:{re.sub(r'(?<!^)(?=[A-Z])', '_', ev).lower()}:{g}:{h}" for ev, group_map in hooks.items() for g, group_name in enumerate(group_map) for h, _ in enumerate(group_name["hooks"])]
    open(a.env["ORQ_CODEX_CONFIG"], "w").write("[hooks.state]\n" + "".join(f'[hooks.state."{k}"]\ntrusted_hash = "sha256:ab"\n' for k in keys if trust))


def _env97(agent="claude", **env):
    a = Env(run=None, ORQ_CLAUDE_SETTINGS=os.path.join(tempfile.mkdtemp(), "settings.json"), **env)
    a.set("terminals.json", ["term_coord"])
    _harness_hooks(a, agent)
    return a


def test_ticket97_it_should_check_the_hooks_bind_a_new_run_raise_the_manager_and_print_the_status_in_claude():
    a = _env97("claude")
