# ---------- ticket 87: orq passar, a worker continues in another harness in the same worktree ----------

def _handoff_env(a, repo, **w):
    """A Claude worker (Sonnet high) running in the worktree; Claude is at the weekly limit and Codex at 40%."""
    _ctl_env(a, repo, **w)
    _account73(a, codex_week=40, claude_week=95)


def _flag(cmd, item_name):
    return cmd[cmd.index(item_name) + 1]


def test_it_should_hand_a_claude_worker_over_to_codex_in_the_same_worktree_handover():
    with tempfile.TemporaryDirectory() as t:
        repo, _ = _repo_git(t, dirty=True)
        a = Env(run="run_a")
        _handoff_env(a, repo)
        before = _head(repo)
        assert a.orq("steer", "task_w1", "use a branch nova").returncode == 0
        a.set("../pendencias.json", {"itens": [{"id": "indice-novo", "tipo": "decisao", "titulo": "Qual índice criar?", "task": "task_w1"}, {"id": "outra", "tipo": "decisao", "titulo": "de outra task", "task": "task_x"}]})
        r = a.orq("passar", "ctx_w1", "--para", "codex")
        assert r.returncode == 0, r.stderr
        out = json.loads(r.stdout)
        assert out["novo_dispatch"] == "ctx_term_novo2" and out["resultado"] == "ok", out
        (stop,) = _log(a, "stopped.log")
        assert stop[:3] == ["worker-stop", "--dispatch", "ctx_w1"]
        (launch,) = _log(a, "started.log")
        assert (_flag(launch, "--task"), _flag(launch, "--retry-of"), _flag(launch, "--agent")) == ("task_w1", "ctx_w1", "codex"), launch
        assert (_flag(launch, "--model"), _flag(launch, "--effort")) == ("gpt-6-luna", "xhigh"), "Sonnet high vira Luna xhigh (tabela do worker-routing)"
        assert _flag(launch, "--worktree") == "id:repo_1::" + repo and "--spec" not in launch, launch
        text_value = open(os.path.join(repo, "HANDOFF.md"), encoding="utf-8").read()
        assert text_value.splitlines()[0] == "<!-- orq-passagem v1 de=ctx_w1 para=codex -->", text_value
        titles = ["## Next step", "## Open questions", "## Decisions already made", "## Git state", "## Partial report", "## End of the transcript",
                   "## Where the rest is", "## How to act"]
        pos = [text_value.index(x) for x in titles]
        assert pos == sorted(pos), "ação antes da prosa: as seções seguem a ordem do desenho"
        assert "use a branch nova" in text_value[pos[2]:pos[3]], "o steer da task é decisão já tomada"
        assert "indice-novo: Qual índice criar?" in text_value[pos[1]:pos[2]] and "de outra task" not in text_value, "pergunta aberta é a decisão pendente da própria task"
        assert "novo" in text_value[pos[3]:pos[4]] and before[:12] in text_value[pos[3]:pos[4]], "o estado do git traz o head e os caminhos sujos"
        note = _sent(a)[-1]
        assert note[note.index("--to") + 1] == "dispatch:ctx_term_novo2" and "HANDOFF.md" in _flag(note, "--body"), note
        (ev,) = [e for e in a.events() if e["tipo"] == "passagem"]
        assert (ev["de"], ev["agente_de"], ev["para"], ev["agente_para"], ev["head"], ev["sujo"], ev["escrito_por"]) == \
            ("ctx_w1", "claude", "ctx_term_novo2", "codex", before[:12], 1, "orq"), ev
        assert ev["pacote"] == hashlib.sha256(text_value.encode("utf-8")).hexdigest()[:12], ev
        assert ev["aceita"] is True, "o hook do worker novo registrou o primeiro turno"
        assert _head(repo) == before and os.path.exists(os.path.join(repo, "novo"))
        assert "HANDOFF.md" not in subprocess.run(["git", "-C", repo, "status", "--porcelain"], capture_output=True, text=True).stdout, "o pacote não vai no commit do worker novo"
        assert _log(a, "released.log"), "o terminal do worker antigo é liberado depois que o novo sobe"
        (ctl,) = [e for e in _ctl_events(a, "passar") if e["resultado"] == "ok"]
        assert ctl["novo_dispatch"] == "ctx_term_novo2", ctl


