# ---------- ticket 88: PASSAGEM.md written by orq when the worker has no turn ----------

def _worker_at_limit(a, repo, t, open_state=True):
    """W1 stopped at the plan limit: the screen shows the notice (fixture; the real Claude text still needs to be checked), with no PAUSA.md and no new turn; the transcript ends
    on a tool (`open_state`) or on an answer; in the inbox there is one unanswered question and another already answered."""
    _handoff_env(a, repo)
    a.set("screens.json", {"term_w1": open(os.path.join(FIX, "tela-claude-limite.txt"), encoding="utf-8").read().splitlines()})
    file_path = os.path.join(t, "w1.jsonl")
    line_list = [{"type": "user", "message": {"role": "user", "content": "faça o ticket"}},
              {"type": "assistant", "message": {"role": "assistant", "content": [{"type": "thinking", "thinking": "segredo"}, {"type": "text", "text": "criei o índice, falta rodar a suíte"}]}}]
    line_list.append({"type": "assistant", "message": {"role": "assistant", "content": [{"type": "tool_use", "name": "Bash", "input": {"command": "pytest"}}]}} if open_state
                  else {"type": "assistant", "message": {"role": "assistant", "content": [{"type": "text", "text": "pronto para a suíte"}]}})
    open(file_path, "w", encoding="utf-8").write("\n".join(json.dumps(x) for x in line_list) + "\n")
    a.set("search.json", [{"agent": "claude", "sessionId": "sess-w1", "cwd": repo, "source": {"filePath": file_path}, "evidence": {"role": "user"}}])
    q = lambda i, seq, type_name, from_, to_, subject: {"id": i, "run_id": "run_a", "type": type_name, "subject": subject, "body": "detalhe de " + subject, "sequence": seq,  # noqa: E731
                                                  "from_handle": from_, "to_handle": to_, "created_at": "2026-10-01T10:00:00Z", "payload": json.dumps({"dispatchId": "ctx_w1", "taskId": "task_w1"})}
    a.set("inbox.json", {"result": {"messages": [q("msg_q1", 1, "question", "dispatch:ctx_w1", "run:run_a", "Qual índice criar?"),
                                                 q("msg_r1", 2, "reply", "term_coord", "dispatch:ctx_w1", "re"),
                                                 q("msg_q2", 3, "question", "dispatch:ctx_w1", "run:run_a", "Posso apagar a coleção velha?")]}})
    with open(os.path.join(a.home, "events.jsonl"), "a", encoding="utf-8") as f:
        f.write(json.dumps({"ts": now_iso(-300), "tipo": "resposta_worker", "msg_id": "msg_q1", "dispatch": "ctx_w1", "texto": "o índice parcial"}) + "\n")
    return file_path


def test_it_should_write_the_package_for_a_worker_with_no_turn_within_the_deadline_handover():
    with tempfile.TemporaryDirectory() as t:
        repo, _ = _repo_git(t, dirty=True)
        a = Env(run="run_a")
        os.makedirs(a.home, exist_ok=True)
        file_path = _worker_at_limit(a, repo, t)
        before = _head(repo)
        t0 = time.monotonic()
        r = a.orq("passagem", "ctx_w1")
        assert r.returncode == 0, r.stderr
        assert time.monotonic() - t0 <= 20 and json.loads(r.stdout)["segundos"] <= 20, "o pacote sai em até 20 s"
        text_value = open(os.path.join(repo, "HANDOFF.md"), encoding="utf-8").read()
        assert text_value.splitlines()[0] == "<!-- orq-passagem v1 de=ctx_w1 para=codex -->", "o outro harness é o padrão"
        titles = ["## Next step", "## Open questions", "## Decisions already made", "## Git state", "## Partial report", "## End of the transcript",
                   "## Where the rest is", "## How to act"]
        pos = [text_value.index(x) for x in titles]
        assert pos == sorted(pos), "as seções seguem a ordem da 2.3"
        section = lambda i: text_value[pos[i]:pos[i + 1] if i + 1 < len(pos) else None]  # noqa: E731
        assert "stopped without closing the turn" in section(0) and "Unknown" in section(0), "o transcrito termina numa ferramenta e não há nota do worker"
        assert "Posso apagar a coleção velha?" in section(1) and "Qual índice criar?" not in section(1), "só a pergunta sem resposta"
        assert "Qual índice criar? → o índice parcial" in section(2), "a pergunta respondida vira decisão"
        assert before[:12] in section(3) and "dirty files, 1" in section(3) and "novo" in section(3), section(3)
        assert "criei o índice, falta rodar a suíte" in section(4), "sem relatório do worker, vale a última resposta visível dele"
        assert "segredo" not in text_value and file_path in section(6) and "claude --resume sess-w1" in section(6), section(6)
        assert "is not in the E2E queue" in section(7)
        assert not _log(a, "stopped.log") and not _log(a, "started.log") and not _sent(a), "o worker não é parado, relançado nem consultado"
        assert _head(repo) == before and not [e for e in a.events() if e["tipo"] == "passagem"]
        (ctl,) = _ctl_events(a, "passagem")
        assert ctl["resultado"] == "ok" and ctl["de"] == "claude" and ctl["para"] == "codex" and len(ctl["pacote"]) == 12, ctl


