# ticket 92: relatorio-final.md as a fallback worker_done and handoff open in the status

def _reserve92(a, report="# Entrega\n\nfeito", end=-300, mtime=-400, start_time=-600, cwd=True, done=False):
    """A worker without worker_done: turnos.json with cwd, `report-final.md` in the worktree and, if `done`, its worker_done already in the log."""
    _ingest_env(a)
    wt = os.path.join(a.tmp.name, "wt92")
    os.makedirs(wt)
    file_path = os.path.join(wt, "relatorio-final.md")
    if report is not None:
        open(file_path, "w").write(report)
        os.utime(file_path, (time.time() + mtime, time.time() + mtime))
    _write_state(os.path.join(a.home, "turnos.json"), {"ctx_92": {"task": "task_92", "inicio": now_iso(start_time), "fim": now_iso(end) if end is not None else None, "harness": "claude",
                          **({"cwd": wt} if cwd else {})}})
    line_list = [{"ts": now_iso(-900), "tipo": "despacho", "run": "run_a", "task": "task_92", "dispatch": "ctx_92", "titulo": "t"}]
    if done:
        line_list.append({"ts": now_iso(-100), "tipo": "worker_done", "msg": "msg_real", "run": "run_a", "task": "task_92", "dispatch": "ctx_92", "outcome": "succeeded", "subject": "x"})
    open(os.path.join(a.home, "events.jsonl"), "w").write("".join(json.dumps(e) + "\n" for e in line_list))
    return file_path


def test_ticket_92_final_report_without_worker_done_becomes_worker_done_and_entry():
    a = Env()
    file_path = _reserve92(a)
    assert a.orq("ingest").returncode == 0
    (wd,) = [e for e in a.events() if e["tipo"] == "worker_done" and e.get("dispatch") == "ctx_92"]
    assert wd["dispatch"] == "ctx_92" and wd["task"] == "task_92" and wd["run"] == "run_a" and wd["origem"] == "relatorio-final"
    (entry_event,) = [e for e in _entries(a, "relatorio_worker") if e.get("task") == "task_92"]
    assert entry_event["caminho"] == file_path and entry_event["task"] == "task_92" and entry_event["ref"] == wd["msg"]
    a.orq("ingest")
    assert len([e for e in a.events() if e["tipo"] == "worker_done" and e.get("dispatch") == "ctx_92"]) == 1, "o segundo ingest não repete"
    assert len([e for e in _entries(a, "relatorio_worker") if e.get("task") == "task_92"]) == 1


def test_ticket_92_final_report_does_not_count_with_real_worker_done_open_turn_or_old_file():
    for fields in ({"done": True}, {"end": None}, {"mtime": -700}, {"cwd": False}, {"report": None}):
        a = Env()
        _reserve92(a, **fields)
        assert a.orq("ingest").returncode == 0
        assert [e for e in a.events() if e.get("origem") == "relatorio-final"] == [], fields
        assert [e for e in _entries(a, "relatorio_worker") if e.get("task") == "task_92"] == [], fields


def test_ticket_92_real_worker_done_after_reserve_does_not_duplicate():
    a = Env()
    _reserve92(a)
    a.orq("ingest")
    ib = _fix("inbox.json")
    ib["result"]["messages"].append({**ib["result"]["messages"][0], "id": "msg_tardio", "sequence": 990, "run_id": "run_a", "type": "worker_done",
                                     "created_at": "2099-01-01T00:00:00Z", "payload": json.dumps({"taskId": "task_92", "dispatchId": "ctx_92", "outcome": "succeeded", "reportPath": "/x/r.md"})})
    a.set("inbox.json", ib)
    a.orq("ingest")
    assert len([e for e in a.events() if e["tipo"] == "worker_done" and e.get("dispatch") == "ctx_92"]) == 1
    assert len([e for e in _entries(a, "relatorio_worker") if e.get("task") == "task_92"]) == 1, "só a entrada da reserva: a do worker_done tardio é descartada"


def _handoff92(a, minutes_elapsed, accepted=False, new_start=False):
    os.makedirs(a.home, exist_ok=True)
    ts = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() - minutes_elapsed * 60))
    open(os.path.join(a.home, "events.jsonl"), "w").write(json.dumps(
        {"ts": ts, "tipo": "passagem", "de": "ctx_A", "agente_de": "claude", "para": "ctx_B", "agente_para": "codex", "aceita": accepted, "task": "task_92", "run": "run_a"}) + "\n")
    _write_state(os.path.join(a.home, "turnos.json"), {"ctx_B": {"task": "task_92", "inicio": now_iso(-60), "fim": None}} if new_start else {})


