def test_ticket_92_status_silences_recent_accepted_handoff_or_with_new_turn():
    for minutes_elapsed, fields in ((5, {}), (30, {"accepted": True}), (30, {"new_start": True})):
        a = Env()
        _handoff92(a, minutes_elapsed, **fields)
        assert "Open handoffs" not in a.orq("status").stdout, (minutes_elapsed, fields)



# ---------- ticket 105: orq unlocks on its own what gets stuck ----------

def _tk105(a, number, title, status="ready-for-agent", is_blocked="(nenhum)", task=None, run="run_a", extra=""):
    """Writes `NN-t.md` in ORQ_ISSUES with the header of a /to-tickets ticket; `extra` are extra header lines (Modelo, Effort)."""
    os.makedirs(a.env["ORQ_ISSUES"], exist_ok=True)
    with open(os.path.join(a.env["ORQ_ISSUES"], f"{number}-t.md"), "w") as f:
        f.write(f"# {number}: {title}\n\nStatus: {status}\nBlocked by: {is_blocked}\nRun: {run}\n" + (f"Task: {task}\n" if task else "") + extra +
                "\n## What to build\n\nx\n\n## Acceptance criteria\n\n- [ ] y\n")


def _tasks105(a, *tasks, run="run_a"):
    a.set(f"tasks_{run}.json", [{"id": i, "task_title": "x", "status": s, "dispatch_id": None, "deps": "[]"} for i, s in tasks])


def _header105(a, number):
    return _read_text(a, number).split("\n## ")[0]


MODEL105 = "Modelo: claude-sonnet-5-5\nEffort: medium\n"


def _case_87(a):
    """The real case of 01/10: 88, 91 and 93 stayed 'Blocked by: 87' after 87 was resolved."""
    _tk105(a, "87", "Orq passar de harness", "claimed", task="task_87")
    _tk105(a, "88", "Passagem escrita", is_blocked="87", task="task_88", extra=MODEL105)
    _tk105(a, "91", "Segurança do limiar", is_blocked="87", task="task_91")
    _tk105(a, "93", "Painel de passagem", is_blocked="87", task="task_93", extra=MODEL105)
    _tk105(a, "90", "Ainda aberto", "claimed", task="task_90")
    _tk105(a, "95", "Espera dois", is_blocked="87, 90", task="task_95", extra=MODEL105)
    _tk105(a, "96", "Já em andamento", "claimed", is_blocked="87", task="task_96", extra=MODEL105)
    _tasks105(a, ("task_87", "dispatched"), ("task_88", "blocked"), ("task_91", "pending"), ("task_93", "blocked"), ("task_90", "dispatched"), ("task_95", "blocked"), ("task_96", "blocked"))


def test_ticket105_close_87_releases_88_91_and_93_and_removes_87_from_all_blocked_by():
    a = Env(run="run_a")
    _case_87(a)
    r = a.orq("ticket", "fechar", "87", "--answer", "feito")
    assert r.returncode == 0, r.stderr
    for n in ("88", "91", "93", "96"):
        assert "Blocked by: (nenhum)" in _header105(a, n), (n, _header105(a, n))
    assert "Blocked by: 90" in _header105(a, "95"), "o que ainda tem outro bloqueio aberto só perde o 87"
    out = json.loads(r.stdout)
    assert [(x["ticket"], x["prioridade"]) for x in out["liberados"]] == [("91", 1), ("88", 2), ("93", 3)], "liberado = ficou sem bloqueio e ainda é ready-for-agent; a ordem é a de prioridade"
    ev = [e for e in a.events() if e["tipo"] == "ticket" and e["op"] == "fechar"][-1]
    assert [x["ticket"] for x in ev["liberados"]] == ["91", "88", "93"], "o orq status lê do evento"


def test_ticket105_released_p1_or_p2_with_model_enters_the_dispatch_queue_and_p3_never():
    a = Env(run="run_a")
