def _waiting105(a, with_queue=True):
    """The t80 of the real case: idle for 12 min at the prompt, waiting for the integrator to take its branch to main."""
    a.set("workers.json", [{"handle": "term_t80", "run": "run_a", "status": "dispatched", "desde": _iso(-3000), "agente": "claude"}])
    os.makedirs(a.home, exist_ok=True)
    _write_state(os.path.join(a.home, "turnos.json"), {"ctx_term_t80": {"task": "task_term_t80", "inicio": now_iso(-1200), "fim": now_iso(-720)}})
    with open(os.path.join(a.home, "events.jsonl"), "a") as f:
        f.write(json.dumps({"tipo": "despacho", "run": "run_a", "task": "task_term_t80", "dispatch": "ctx_term_t80", "ticket": "80", "titulo": "Secondmate por grupo"}) + "\n")
    if with_queue:
        assert a.orq("integrar", "fila", "add", "feat/secondmate-por-grupo", "80").returncode == 0


def test_ticket105_worker_in_integrator_queue_stays_awaiting_integration_and_not_stopped():
    a = Env(run="run_a")
    _waiting105(a, with_queue=False)
    assert _agents(a)["ctx_term_t80"]["estado"] == "parado" and 'orq steer task_term_t80' in a.orq("agentes").stdout, "sem a fila é o parado de sempre"
    _waiting105(a)
    t80 = _agents(a)["ctx_term_t80"]
    assert t80["estado"] == "aguardando_integracao" and t80["integracao"]["branch"] == "feat/secondmate-por-grupo" and t80["integracao"]["ticket"] == "80", t80
    txt = a.orq("agentes").stdout
    assert "awaiting integration" in txt and "feat/secondmate-por-grupo" in txt and "orq steer" not in txt, txt
    assert a.orq("integrar", "fila", "rm", "80").returncode == 0
    assert _agents(a)["ctx_term_t80"]["estado"] == "parado", "saiu da fila: volta ao critério normal"


def test_ticket105_open_cache_also_becomes_awaiting_integration_without_suggesting_the_steer():
    now_at = datetime.now(timezone.utc)
    ab = _open_agent("parado", agente="claude", desde=now_iso(-3000), turno_inicio=now_iso(-1200), turno_fim=now_iso(-720), idade_s=720)
    task = ab["agentes"][0]["task"]
    evs = [{"tipo": "despacho", "task": task, "dispatch": ab["agentes"][0]["dispatch"], "ticket": "80"}]
    queue = {"80": {"branch": "feat/secondmate-por-grupo", "ticket": "80"}}
    (r,) = orq_mod.reassess(ab["agentes"], evs, now_at, integration=queue)
    assert r["estado"] == "aguardando_integracao" and r["integracao"]["branch"] == "feat/secondmate-por-grupo", r
    (r2,) = orq_mod.reassess(ab["agentes"], evs, now_at, integration={})
    assert r2["estado"] == "parado", "fila vazia: o critério normal"
    a = Env(run="run_a")  # orq status (the prompt hook) reads aberto.json and the queue from disk
    os.makedirs(a.home, exist_ok=True)
    _write_state(os.path.join(a.home, "aberto.json"), ab)
    _write_state(os.path.join(a.home, "turnos.json"), {"ctx_1": {"task": task, "inicio": now_iso(-1200), "fim": now_iso(-720)}})
    open(os.path.join(a.home, "events.jsonl"), "w").write("".join(json.dumps(e) + "\n" for e in evs))
    assert 'Stopped at prompt: ' + task in a.orq("status").stdout, "sem a fila o status pede o steer"
    assert a.orq("integrar", "fila", "add", "feat/secondmate-por-grupo", "80").returncode == 0
    txt = a.orq("status").stdout
    assert "Stopped at prompt" not in txt and "orq steer" not in txt and "waiting for integration of feat/secondmate-por-grupo" in txt, txt


