def test_ticket120_panel_shell_sleeps_what_orq_says_and_10_s_if_orq_breaks():
    for orq_body, expected in (('[ "$2" = interval ] && echo 25', "25"), ("exit 1", "10")):
        with tempfile.TemporaryDirectory() as t:
            bin_ = os.path.join(t, "bin")
            os.makedirs(bin_)
            for item_name, body_text in (("orq", orq_body), ("clear", ":"), ("sleep", f'echo "$1" > {t}/dormiu; kill $PPID')):
                with open(os.path.join(bin_, item_name), "w") as f:
                    f.write("#!/bin/sh\n" + body_text + "\n")
                os.chmod(os.path.join(bin_, item_name), 0o755)
            home = os.path.join(t, "orq")
            os.makedirs(home)
            subprocess.run(["sh", os.path.join(HERE, "painel-agent-manager.sh")], env={**os.environ, "PATH": bin_ + os.pathsep + os.environ["PATH"], "ORQ_HOME": home},
                           capture_output=True, timeout=20)
            assert open(os.path.join(t, "dormiu")).read().strip() == expected


