def test_ticket114_done_with_proof_closes_the_obligation_and_the_last_closes_the_entry():
    a = _prs_env()
    e = _merge_main(a)
    assert a.orq("feito", e, "comentario").returncode == 2, "sem --prova não fecha"
    r = a.orq("feito", e, "nao-existe", "--prova", "x")
    assert r.returncode == 1 and "deploy" in r.stderr, r
    r = a.orq("feito", e, "comentario", "--prova", "https://github.com/acme/app/issues/2045#issuecomment-1")
    assert r.returncode == 0, r.stderr
    assert "comentario" not in _find_obligation(a, e) and e in {x["id"] for x in orq_mod.open_entries(a.events())}
    assert a.orq("feito", e, "comentario", "--prova", "de novo").returncode == 1, "já fechada"
    a.orq("feito", e, "deploy", "--prova", "v776")
    a.orq("feito", e, "limpeza", "--prova", "branch e worktree removidas")
    assert not _find_obligation(a, e) and e not in {x["id"] for x in orq_mod.open_entries(a.events())}, "sem obrigação aberta a entrada se fecha"
    assert "To do by you" not in _ctx(a.prompt("e agora?"))


