def test_ticket114_the_same_flow_runs_with_the_codex_hook_payload():
    a = _prs_env(ORQ_OBRIGACAO_MIN="0")
    e = _merge_main(a)
    r = _hook_codex(a, "prompt", _codex("userpromptsubmit", session_id="abcdef123456", prompt="e agora?"))
    assert f"To do by you: {e} →" in _ctx(r), r.stdout
    assert a.orq("intake", "e2", "conversa").returncode == 0  # the Stop blocks an entry without the turn's intake; this test is about the obligation
    m = _stop_notice(_hook_codex(a, "stop", _codex("stop", session_id="abcdef123456")).stdout)
    assert "Obligation open" in m and f"{e} deploy" in m, m  # barra (reason): o Codex recebe o mesmo bloqueio
    for key_name in ("deploy", "comentario", "limpeza"):
        assert a.orq("feito", e, key_name, "--prova", "ok").returncode == 0
    assert "To do by you" not in _ctx(_hook_codex(a, "prompt", _codex("userpromptsubmit", session_id="abcdef123456", prompt="e agora?")))


def test_ticket107_without_away_mode_a_held_notice_reaches_the_next_prompt():
    a = Env()
    with tempfile.TemporaryDirectory() as queue:
        before, dig = orq_mod.HOME, orq_mod.type_text
        orq_mod.HOME, orq_mod.type_text = a.home, lambda h, t, *_: "rascunho"  # ticket 182: away off tries to type, and the draft holds it
        try:
            os.makedirs(a.home, exist_ok=True)
            _write_state(os.path.join(a.home, "gerente.json"), {"coordenador": "term_c", "gerente": "term_g", "runs": []})
            _user_spoke(a.home, 60)  # old prompt: ticket 86's rule would not defer
            assert orq_mod.notify_e2e_queue(_stuck_queue(queue))
            assert orq_mod.notify_coordinator("term_c", "orq: wake de teste", minutes_elapsed=orq_mod.WAKE_IDLE_MIN) == "adiado"
            assert orq_mod.deliver_notices() == []
        finally:
            orq_mod.HOME, orq_mod.type_text = before, dig
    ctx = json.loads(a.prompt("e agora?").stdout)["hookSpecificOutput"]["additionalContext"]
    assert "STUCK" in ctx and "wake de teste" in ctx, ctx


def test_ticket107_with_away_mode_the_notice_is_typed_keeping_the_old_guards():
    with tempfile.TemporaryDirectory() as home:
        before, dig = orq_mod.HOME, orq_mod.type_text
        sent = []
        orq_mod.HOME, orq_mod.type_text = home, lambda h, t: sent.append(t) or "enviado"
        try:
            orq_mod.away_on()
            _user_spoke(home, 1)
            assert orq_mod.notify_coordinator("term_c", "orq: a") == "adiado" and sent == []
            os.remove(os.path.join(home, "events.jsonl"))
            assert orq_mod.notify_coordinator("term_c", "orq: b") == "enviado" and sent == ["orq: b"]
        finally:
            orq_mod.HOME, orq_mod.type_text = before, dig


# ---- ticket 115: environments (branches) declared per project ----

def _remote_repo(a, default):
    """A git repo with origin/HEAD pointing to `default`; returns the folder."""
    d = os.path.join(a.tmp.name, "repo-" + default)
    os.makedirs(d)
    g = lambda *x: subprocess.run(["git", "-C", d, *x], check=True, capture_output=True, env={**os.environ, "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t",
                                                                                         "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@t"})
    g("init", "-q", "-b", default)
    g("commit", "-q", "--allow-empty", "-m", "x")
    g("update-ref", f"refs/remotes/origin/{default}", "HEAD")
    g("symbolic-ref", "refs/remotes/origin/HEAD", f"refs/remotes/origin/{default}")
    return d


def _pr_status(a, cwd=None):
    (line,) = [x for x in a.orq("status", cwd=cwd).stdout.splitlines() if x.startswith("PR task_")]
    return line


def _entered(a, url, base, cwd=None):
    _pr(a, url, "MERGED", base)
    assert a.orq("pr", "ligar", "task_feat1", url, cwd=cwd).returncode == 0
    assert a.orq("pr", "poll", "--forcar", cwd=cwd).returncode == 0


def test_ticket115_project_with_dev_and_main_says_ready_for_main_after_dev_pr():
    a = Env(run="run_a")
    _gh(a)
    _project(a, "app", {"repo": f"path:{os.getcwd()}", "ambientes": [{"branch": "dev"}, {"branch": "main", "producao": True}], "fluxo": "promocao"})
    _entered(a, PR1, "dev")
    line = _pr_status(a)
    assert "ready for main (dev entered: open the one for main)" in line and "staging" not in line, line
    _entered(a, PR2, "main")
    assert "in main" in _pr_status(a) and "ready for" not in _pr_status(a)


