def test_ticket115_projects_validates_the_environments_and_lists_the_flow():
    a = Env(run="run_a")
    _project(a, "bom", {"repo": "path:/r/bom", "ambientes": [{"branch": "dev"}, {"branch": "main", "producao": True}]})
    _project(a, "malformado", {"repo": "path:/r/m", "ambientes": ["dev"]})
    _project(a, "duas-producoes", {"repo": "path:/r/d", "ambientes": [{"branch": "a", "producao": True}, {"branch": "b", "producao": True}]})
    _project(a, "fluxo-ruim", {"repo": "path:/r/f", "fluxo": "cascata"})
    out = a.orq("projetos").stdout.splitlines()
    assert any(l.startswith("bom") and "environments dev > main (promocao, production main)" in l and "invalid" not in l for l in out), out
    for item_name, reason in (("malformado", "ambientes"), ("duas-producoes", "production"), ("fluxo-ruim", "cascata")):
        assert any(l.startswith(item_name) and "invalid" in l and reason in l for l in out), (item_name, out)
    js = {p["nome"]: p for p in json.loads(a.orq("projetos", "--json").stdout)}
    assert js["bom"]["ambientes"] == ["dev", "main"] and js["bom"]["producao"] == "main" and js["bom"]["fluxo"] == "promocao", js["bom"]


