def _tk126(number, state="ready-for-agent", model="claude-sonnet-5-5", is_blocked=(), task="t"):
    return {"num": number, "titulo": f"ticket {number}", "status": state, "blocked_by": list(is_blocked), "task": task, "run": "run_a", "modelo": model, "effort": "medium"}


def test_ticket126_next_without_user_delivery_not_integrated_and_cycle_without_push():
    agent_row = {"dispatch": "d1", "task": "t1", "estado": "entregue"}
    ev = [{"tipo": "despacho", "dispatch": "d1", "task": "t1", "ticket": "50"}]
    next_item = lambda **k: orq_mod.next_without_user(**{"tks": [_tk126("50", "claimed")], "agent_rows": [agent_row], "integration": {}, "queue": [], "events": ev, "cfg": orq_mod.machine_cfg(), "without_push": 0, **k})
    assert "50" in next_item() and "orq integrate queue add" in next_item(), "entregue, ticket aberto e fora da fila do integrador"
    assert next_item(integration={"50": {"ticket": "50"}}) is None, "já espera o integrador"
    assert next_item(tks=[_tk126("50", "resolved")]) is None, "ticket fechado: integrado"
    assert next_item(agent_rows=[{**agent_row, "estado": "liberado"}]) is None
    cycle = ev + [{"tipo": "ciclo", "dispatch": "dI", "hash": "abc1234"}]
    assert next_item(agent_rows=[], events=cycle, without_push=2) and "abc1234" in next_item(agent_rows=[], events=cycle, without_push=2) and "push" in next_item(agent_rows=[], events=cycle, without_push=2)
    assert next_item(agent_rows=[], events=cycle, without_push=0) is None and next_item(agent_rows=[], events=cycle, without_push=None) is None, "sem commit a enviar, ou sem saber: deixa parar"
    assert "2 commit(s) unpushed" in next_item(agent_rows=[], events=ev, without_push=2) and "abc1234" not in next_item(agent_rows=[], events=ev, without_push=2), "o integrador não grava o ciclo (ticket 180): os commits sem push bastam"


def test_ticket126_next_without_user_ready_ticket_asks_priority_model_and_slot():
    base = {"agent_rows": [], "integration": {}, "events": [], "without_push": 0, "cfg": {**orq_mod.machine_cfg(), "max_workers": 2}}
    next_item = lambda tks, **k: orq_mod.next_without_user(tks=tks, queue=[], **{**base, **k})
    assert "orq dispatch --ticket 07" in next_item([_tk126("07")])
    assert next_item([_tk126("07", is_blocked=["06"])]) is None and next_item([_tk126("07", model=None)]) is None
    full_agents = [{"dispatch": f"d{i}", "estado": "rodando", "modelo": "claude-sonnet-5-5"} for i in range(2)]
    assert next_item([_tk126("07")], agent_rows=full_agents) is None, "sem slot livre"
    hib = [{**x, "estado": "hibernado"} for x in full_agents]
    assert next_item([_tk126("07")], agent_rows=hib), "worker hibernado não ocupa slot"
    assert orq_mod.next_without_user(tks=[_tk126("07")], queue=[{"ticket": "07"}], **base) is None, "já está na fila de despacho"


def test_ticket126_machine_occupancy_does_not_count_hibernated_worker():
    before = (orq_mod._alive_terminals, orq_mod._all_workers, orq_mod._hibernated, orq_mod.read_events)
    try:
        orq_mod.read_events = lambda: []  # without this it reads the real events.jsonl, where a recent dispatch also takes a slot
        orq_mod._alive_terminals = lambda: None  # without a terminal list every `dispatched` counted as alive
        orq_mod._all_workers = lambda: [{"dispatchId": "dH", "dispatchStatus": "dispatched", "agentTerminalHandle": "term_h"},
                                          {"dispatchId": "dV", "dispatchStatus": "dispatched", "agentTerminalHandle": "term_v"}]
        orq_mod._hibernated = lambda: {"dH": {"desde": "x"}}
        orq_mod._details = lambda still_missing: {w["dispatchId"]: {"modelo": "claude-sonnet-5-5"} for w in still_missing}
        assert set(orq_mod.machine_occupancy()["vivos"]) == {"dV"}
    finally:
        orq_mod._alive_terminals, orq_mod._all_workers, orq_mod._hibernated, orq_mod.read_events = before


