# ---- ticket 125: orq projeto add registers in Orca with the generated orca.yaml; the mate runs in Orca's project

def _project_git_repo(a, item_name="app", files_set=()):
    folder = os.path.join(a.tmp.name, item_name)
    os.makedirs(folder)
    subprocess.run(["git", "init", "-q", "-b", "main", folder], check=True)
    for file_path in files_set:
        os.makedirs(os.path.dirname(os.path.join(folder, file_path)), exist_ok=True)
        open(os.path.join(folder, file_path), "w").write("")
    return os.path.realpath(folder)


def _repo_calls(a):
    return [c[:-1] for c in _log(a, "calls.log") if c[0] in ("add", "set-base-ref")]  # without the --json that orca() appends


TRUST_CLAUDE = "python3 ~/.claude/scripts/trust-cwd.py"


def test_ticket125_add_without_record_registers_in_orca_writes_project_and_orca_yaml_only_with_what_repo_has():
    a = Env()
    repo = _project_git_repo(a, files_set=["package-lock.json"])
    r = a.orq("projeto", "add", repo)
    assert r.returncode == 0, r.stderr
    assert _repo_calls(a) == [["add", "--path", repo], ["set-base-ref", "--repo", f"path:{repo}", "--ref", "origin/main"]], _repo_calls(a)
    assert _read_state(os.path.join(a.home, "projects", "app.json"))["repo"] == f"path:{repo}"
    y = open(os.path.join(repo, "orca.yaml")).read()
    assert TRUST_CLAUDE in y and "npm ci" in y and ".scratch" in y, y
    # only package-lock.json: no Meteor, E2E, graphify nor the worktree setup script
    for away_alias in ("meteor", ".meteor", "e2e", "graphify", "setup-worktree", "docker"):
        assert away_alias not in y, (away_alias, y)
    assert orq_mod.read_orca_yaml(y)[0]["setup"][0] == TRUST_CLAUDE


def test_ticket125_each_block_enters_only_by_the_marker_the_repo_has():
    a = Env()
    everything = _project_git_repo(a, "tudo", ["pnpm-lock.yaml", "scripts/setup-worktree.sh", "graphify-out/graph.json", "web/.meteor/release", "docker-compose.e2e.yml"])
    open(os.path.join(everything, "scripts", "e2e-infra.sh"), "w").write("case $1 in\n  destroy) :;;\nesac\n")
    y = orq_mod.build_orca_yaml(everything, "claude", {})[0]
    assert "pnpm install" in y and "sh scripts/setup-worktree.sh" in y and "graphify update" in y, y
    assert "rm -rf web/.meteor/local web/_build" in y and "sh scripts/e2e-infra.sh destroy" in y, y
    nothing = _project_git_repo(a, "nada")
    y = orq_mod.build_orca_yaml(nothing, "claude", {})[0]
    assert TRUST_CLAUDE in y and "install" not in y and "meteor" not in y and "e2e" not in y, y


def test_ticket125_project_can_enable_and_disable_blocks_and_add_commands():
    a = Env()
    repo = _project_git_repo(a, files_set=["package-lock.json", "web/.meteor/release"])
    cfg = {"blocos": {"meteor": False, "install": False, "graphify": True}, "setup_extra": ["make bootstrap"], "archive_extra": ["rm -rf .cache"]}
    y = orq_mod.build_orca_yaml(repo, "claude", cfg)[0]
    assert "npm ci" not in y and "meteor" not in y and "graphify update" in y, y
    setup, archive = (orq_mod.read_orca_yaml(y)[0][k] for k in ("setup", "archive"))
    assert setup[-1] == "make bootstrap" and archive[-1] == "rm -rf .cache", (setup, archive)
    for bad in ({"blocos": {"docker": True}}, {"blocos": {"meteor": "sim"}}, {"setup_extra": "x"}, {"setup_extra": [1]}):
        try:
            orq_mod.build_orca_yaml(repo, "claude", bad)
        except ValueError:
            continue
        raise AssertionError(f"aceitou {bad}")


