# ---------- cleanup of PR closed without merge (ticket 104) ----------

def _closed_env(**env):
    """A bare origin, the `repo` checkout (main, development, staging), the feat/x branch with one pushed commit and a worktree of it with relatorio-final.md; the project points to the repo."""
    a = Env(run="run_a", **{"ORQ_FECHADO_DIAS": "1", **env})
    a.env["ORQ_RELATORIOS"] = os.path.join(a.tmp.name, "relatorios")
    base = a.tmp.name
    a.origin, a.repo, a.wt = (os.path.join(base, n) for n in ("origin.git", "repo", "wt-x"))
    g = lambda *args, cwd=None: subprocess.run(["git", "-C", cwd or a.repo, "-c", "user.name=t", "-c", "user.email=t@t", *args], check=True, capture_output=True, text=True).stdout.strip()
    a.g = g
    subprocess.run(["git", "init", "-q", "--bare", a.origin], check=True)
    subprocess.run(["git", "clone", "-q", a.origin, a.repo], check=True, capture_output=True)
    g("checkout", "-q", "-b", "main")
    g("commit", "-q", "--allow-empty", "-m", "x")
    for envs in ("development", "staging"):
        g("branch", envs)
    g("push", "-q", "origin", "main", "development", "staging")
    g("worktree", "add", "-q", "-b", "feat/x", a.wt)
    os.makedirs(os.path.join(a.wt, ".scratch/x"))
    open(os.path.join(a.wt, ".scratch/x/relatorio-final.md"), "w").write("feito")
    g("commit", "-q", "--allow-empty", "-m", "trabalho", cwd=a.wt)
    g("push", "-q", "origin", "feat/x", cwd=a.wt)
    a.set("worktrees.json", [{"path": a.wt, "branch": "refs/heads/feat/x", "repo": a.repo}])
    os.makedirs(os.path.join(a.home, "projects"), exist_ok=True)
    with open(os.path.join(a.home, "projects", "p.json"), "w") as f:
        json.dump({"repo": f"path:{a.repo}", "ambientes": [{"branch": "development"}, {"branch": "staging"}, {"branch": "main", "producao": True}], "fluxo": "promocao"}, f)
    _gh(a)
    return a


def _closed(a, *urls, states=("CLOSED", "CLOSED"), head="feat/x"):
    for u in urls:
        _pr(a, u, "OPEN", "development", headRefName=head)
        assert a.orq("pr", "ligar", "task_feat1", u, cwd=a.repo).returncode == 0
    for u, check_state in zip(urls, states):
        _pr(a, u, check_state, "development", headRefName=head)
    r = a.orq("pr", "poll", "--forcar", cwd=a.repo)
    assert r.returncode == 0
    return r.stdout


def _branches(a):
    return {"local": "feat/x" in a.g("branch", "--list", "feat/x"), "remota": bool(a.g("ls-remote", "--heads", "origin", "feat/x"))}


def test_it_should_mark_the_task_closed_and_clean_it_after_the_grace_period():
    a = _closed_env()
    _closed(a, PR1, PR2)
    assert [e["op"] for e in a.events() if e["tipo"] == "pr" and e["op"] == "fechada"] == ["fechada"], "marca uma vez, quando o último PR fecha"
    assert a.orq("pr", "poll", "--forcar", cwd=a.repo).stdout.count("limpa") == 0 and _branches(a) == {"local": True, "remota": True}, "dentro do prazo nada sai"
    r = a.orq("limpar", "--fechados", "--dry-run", cwd=a.repo)
    assert "would clean feat/x" in r.stdout and "#1216, #1220" in r.stdout and _branches(a) == {"local": True, "remota": True} and os.path.isdir(a.wt), r
    r = a.orq("limpar", "--fechados", cwd=a.repo)
    assert r.returncode == 0 and "Restore branch" in r.stdout, r
    assert _branches(a) == {"local": False, "remota": False} and not os.path.exists(a.wt)
    (rm,) = _log(a, "wtrm.log")
    assert "--run-hooks" in rm["args"] and rm["relatorios"] == ["wt-x-.scratch-x-relatorio-final.md"], "o relatório é guardado antes de tirar a worktree"
    (ev,) = [e for e in a.events() if e.get("op") == "limpou_fechado"]
    assert ev["removidos"] == ["local", "remota"] and "Restore branch" in ev["restaurar"], ev


def test_it_should_not_clean_a_task_with_an_open_pr():
    a = _closed_env()
    _closed(a, PR1, PR2, states=("CLOSED", "OPEN"))
    r = a.orq("limpar", "--fechados", cwd=a.repo)
    assert "no task" in r.stdout and _branches(a) == {"local": True, "remota": True} and os.path.isdir(a.wt), r
    assert not [e for e in a.events() if e.get("op") in ("fechada", "limpou_fechado")]


def test_it_should_never_touch_an_environment_branch_or_a_branch_with_an_open_pr():
    a = _closed_env()
    _closed(a, PR1, states=("CLOSED",), head="development")
    assert "environment branch" in a.orq("limpar", "--fechados", cwd=a.repo).stdout
    assert a.g("ls-remote", "--heads", "origin", "development") and "development" in a.g("branch", "--list", "development")
    b = _closed_env()  # another open PR uses the branch as head (another task): nothing goes out
    _closed(b, PR1, states=("CLOSED",))
    _pr(b, PR2, "OPEN", "development", headRefName="feat/x")
    assert "has an open PR" in b.orq("limpar", "--fechados", cwd=b.repo).stdout and _branches(b) == {"local": True, "remota": True}


def test_it_should_only_preview_the_automatic_cleanup_until_the_first_real_one():
    a = _closed_env(ORQ_FECHADO_DIAS="0")
    out = _closed(a, PR1, states=("CLOSED",))
    assert "would clean feat/x" in out and _branches(a) == {"local": True, "remota": True}, "a primeira vez é só prévia"
    assert "would clean" not in a.orq("pr", "poll", "--forcar", cwd=a.repo).stdout, "a prévia sai uma vez por task"
    assert a.orq("limpar", "--fechados", cwd=a.repo).returncode == 0 and _branches(a) == {"local": False, "remota": False}
    assert os.path.exists(os.path.join(a.home, "limpar-fechados.json"))


# ---------- ticket 127: o mate ocioso dorme, o pedido o acorda ----------

NOW127 = datetime(2026, 10, 1, 15, 0, 0, tzinfo=timezone.utc)


def _m127(end_min=11, opened_min=None, **kw):
    """The mate's record in the cursor: turn that ended `end_min` min ago relative to AGORA127 (None: no turn)."""
    ts = lambda min_: (NOW127 - timedelta(minutes=min_)).strftime("%Y-%m-%dT%H:%M:%SZ")  # noqa: E731
    return {"terminal": "term_mate", "sessao": "sess-mate", "runs": ["run_m"],
            "turnos": [[ts(end_min + 5), ts(end_min)]] if end_min is not None else [],
            **({"aberto_em": ts(opened_min)} if opened_min is not None else {}), **kw}


def test_ticket127_idle_only_with_closed_turn_no_request_and_no_live_worker():
    without = lambda: False  # noqa: E731
    with_ref = lambda: True  # noqa: E731
    assert orq_mod.mate_status(_m127(11), NOW127, [], without) == "idle for 11 min"
    assert orq_mod.mate_status(_m127(9), NOW127, [], without) == "working", "turno fechado há menos de 10 min"
    assert orq_mod.mate_status(_m127(11), NOW127, [{"corr": "p1"}], without) == "working", "pedido aberto do coordenador"
    assert orq_mod.mate_status(_m127(11), NOW127, [], with_ref) == "working", "worker do Run dele vivo (ou entrega sem integrar)"
    open_state = _m127(11)
    open_state["turnos"][-1][1] = None
    assert orq_mod.mate_status(open_state, NOW127, [], without) == "working", "turno ainda aberto"
    assert orq_mod.mate_status(_m127(None), NOW127, [], without) == "working", "sem turno nem abertura gravados não há como medir"
    assert orq_mod.mate_status(_m127(40, opened_min=3), NOW127, [], without) == "working", "o resume zera o relógio: o turno antigo não vale"
    assert orq_mod.mate_status(_m127(40, opened_min=12), NOW127, [], without) == "idle for 12 min"
    assert orq_mod.mate_status(_m127(30, terminal=None, dormiu="2026-10-01T14:40:00Z"), NOW127, [], without) == "sleeping"
    assert orq_mod.mate_status(_m127(11), NOW127, [], without, minimum=15) == "working", "ORQ_MATE_OCIOSO_MIN"
    called = []
    assert orq_mod.mate_status(_m127(9), NOW127, [], lambda: called.append(1)) == "working" and not called, "o worker só é consultado com o resto ocioso"


def _env127(end_min, ready=(), group_cfg=True, **mate):
    """A live mate with the turn closed `end_min` min ago (real clock), the idle screen and the coordinator in gerente.json; `ready`: `ready` tickets of the group."""
    a = Env(run="run_m", **HIBERNATE60)
    _group(a)
    cur = {"mates": {"orq": {"terminal": "term_mate", "sessao": "sess-mate", "cwd": a.home, "runs": ["run_m"],
                             "turnos": [[_z60(end_min + 5), _z60(end_min)]], **mate}}}
    json.dump(cur, open(os.path.join(a.home, "cursor.json"), "w"))
    _write_state(os.path.join(a.home, "gerente.json"), {"coordenador": "term_coord", "gerente": "term_ger", "runs": []})
    a.set("terminals.json", ["term_coord", "term_ger", "term_mate"])
    a.set("screens.json", {"term_mate": _screen52("tela-claude-ocioso.txt"), "term_ret1": ["❯ ", "  ⏵⏵ bypass permissions on (shift+tab to cycle)"]})
    a.set("workers.json", [])
    os.makedirs(a.env["ORQ_ISSUES"], exist_ok=True)
    for n in ready:
        with open(os.path.join(a.env["ORQ_ISSUES"], f"{n}-x.md"), "w") as f:
            f.write(f"# {n}: orq: ticket {n}\n\nStatus: ready\nBlocked by: (nenhum)\n\n## What to build\nx\n\n## Acceptance criteria\n- x\n")
    return a


def test_ticket127_idle_for_20_min_without_ready_ticket_manager_hibernates_and_writes_mate_slept():
    a = _env127(25)
    with InProcess(a):
        r = orq_mod.mates_sleep()
    assert r == ["mate orq: slept (idle for 25 min)"], r
    assert [c[c.index("--terminal") + 1] for c in _log(a, "close.log")] == ["term_mate"]
    m = _cursor(a)["mates"]["orq"]
    assert m["terminal"] is None and m["sessao"] == "sess-mate" and m["dormiu"], m
    ev = next(e for e in a.events() if e["tipo"] == "mate_dormiu")
    assert (ev["grupo"], ev["terminal"], ev["sessao"]) == ("orq", "term_mate", "sess-mate"), ev
    assert not _log(a, "create.log")
    with InProcess(a):
        assert orq_mod.mates_sleep() == [], "dormindo não dorme de novo"
    assert len(_log(a, "close.log")) == 1
    with InProcess(a):
        assert not any("went down" in x for x in orq_mod.mate_lap()), "dormir de propósito não é queda"


