    a.set("workers.json", [_w48("term_w1", run="run_m", agente="claude", modelo="claude-opus-5-5")])
    a.set("tasks_run_m.json", [{"id": "task_term_w1", "task_title": "x", "status": "dispatched", "dispatch_id": "ctx_term_w1", "created_at": _iso(-3600)}])
