def _serve128(a, **env):
    """A background `orq manager serve` in the Amb (0.2 s loop); waits for the pid file to hold its pid."""
    p = subprocess.Popen([sys.executable, ORQ, "gerente", "serve"], env={**a.env, "ORQ_GERENTE_VOLTA_S": "0.2", **env},
                         stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    pid = os.path.join(a.home, orq_mod.SERVE_PID)
    end = time.time() + 15
    while time.time() < end and not (os.path.exists(pid) and open(pid).read().strip() == str(p.pid)):
        time.sleep(0.05)
    assert open(pid).read().strip() == str(p.pid), p
    return p


def test_ticket128_serve_locks_a_single_manager_and_status_and_stop_find_the_pid():
    a = Env(run="run_a")
    _manager(a)
    p = _serve128(a)
    try:
        r = a.orq("gerente", "serve", "--voltas", "1")
        assert r.returncode == 1 and f"pid {p.pid}" in r.stderr, r
        before = len(_calls(a, "check"))
        r = a.orq("gerente", "absorver", ORCA_TERMINAL_HANDLE="term_ger")
        assert r.returncode == 3 and "serve" in r.stdout, "o painel não absorve com o serve vivo: dois gerentes leriam a mesma caixa"
        assert len(_calls(a, "check")) - before <= 2, "só as voltas do próprio serve leram a caixa"
        st = json.loads(a.orq("gerente", "serve", "--status").stdout)
        assert st["rodando"] and st["pid"] == p.pid and st["log"].endswith(os.path.join("logs", "gerente.log")), st
        r = a.orq("gerente", "serve", "--parar")
        assert r.returncode == 0, r.stderr
        assert p.wait(timeout=15) == 0
    finally:
        p.kill()
    st = json.loads(a.orq("gerente", "serve", "--status").stdout)
    assert not st["rodando"] and st["pid"] is None, st
    assert a.orq("gerente", "absorver", ORCA_TERMINAL_HANDLE="term_ger").returncode == 0, "serve parado: o painel volta a absorver"
    assert "parou" in open(os.path.join(a.home, "logs", "gerente.log")).read()


def test_ticket128_serve_runs_one_round_without_tty_with_manager_handle():
    a = Env(run="run_a")  # the serve inherits term_coord and the pane key of whoever called it: the return uses the handle from gerente.json
    _manager(a)
    a.inbox(_hb("lendo"), _hb("testando"))
    r = subprocess.run([sys.executable, ORQ, "gerente", "serve", "--voltas", "1"], stdin=subprocess.DEVNULL, capture_output=True, text=True,
                       env={**a.env, "ORCA_PANE_KEY": "x:y"}, timeout=60)
    assert r.returncode == 0, r.stderr
    assert set(a.states().values()) == {"acked"}, "a volta absorveu os heartbeats pelo handle do gerente"
    assert time.time() - os.path.getmtime(os.path.join(a.home, orq_mod.PANEL_ALIVE)) < 30, "carimbo de vida tocado"
    check_state = _read_state(os.path.join(a.home, orq_mod.SERVE_STATE))
    assert check_state["terminal"] == "term_ger" and any("heartbeat" in x for x in check_state["linhas"]), check_state
    assert isinstance(check_state["agentes"], list) and check_state["maquina"]["cfg"]["max_workers"] and check_state["maquina"]["leitura"]["carga"] == 2.0, check_state
    assert "run_a: 2 heartbeat(s)" in open(os.path.join(a.home, "logs", "gerente.log")).read()
    assert os.path.exists(os.path.join(a.home, "digest", "atual.json")), "a primeira volta grava o digest, como o painel"


def test_ticket128_serve_install_writes_launchd_and_uninstall_removes_it():
    a = Env(run="run_a")
    t = os.path.dirname(a.home)
    agents_dir, lctl = os.path.join(t, "LaunchAgents"), os.path.join(t, "launchctl")
    with open(lctl, "w") as f:
        f.write(f"#!/bin/sh\necho \"$@\" >> {t}/launchctl.log\n")
    os.chmod(lctl, 0o755)
    env = {"ORQ_LAUNCH_AGENTS": agents_dir, "ORQ_LAUNCHCTL": lctl}
    r = a.orq("gerente", "serve", "--instalar", **env)
    assert r.returncode == 0, r.stderr
    import plistlib
    pl = plistlib.load(open(os.path.join(agents_dir, orq_mod.LAUNCHD_LABEL + ".plist"), "rb"))
    assert pl["ProgramArguments"][-2:] == ["gerente", "serve"] and pl["ProgramArguments"][1].endswith("orq.py"), pl
    assert pl["KeepAlive"] and pl["RunAtLoad"] and pl["EnvironmentVariables"]["ORQ_HOME"] == a.home, pl
    assert pl["StandardErrorPath"] == os.path.join(a.home, "logs", "gerente.log"), pl
    assert pl["WorkingDirectory"] == orq_mod.orqpaths.CODE, "the service runs in orq's clone, not wherever launchd starts it (ticket 315)"
    assert not [k for k in pl["EnvironmentVariables"] if k.startswith("ORCA_")], "o handle do coordenador não vai para o launchd"
    assert json.loads(a.orq("gerente", "serve", "--status", **env).stdout)["instalado"]
    assert a.orq("gerente", "serve", "--desinstalar", **env).returncode == 0
    assert not os.path.exists(os.path.join(agents_dir, orq_mod.LAUNCHD_LABEL + ".plist"))
    call_list = open(os.path.join(t, "launchctl.log")).read()
    assert "bootstrap" in call_list and "bootout" in call_list, call_list


def _fake_launchctl316(t):
    lctl = os.path.join(t, "launchctl")
    with open(lctl, "w") as f:
        f.write(f"#!/bin/sh\necho \"$@\" >> {t}/launchctl.log\n")
    os.chmod(lctl, 0o755)
    return lctl


def test_ticket316_serve_stop_without_a_launchctl_fake_never_reaches_the_real_one():
    a = Env(run="run_a")
    t = os.path.dirname(a.home)
    agents_dir = os.path.join(t, "LaunchAgents")
    os.makedirs(agents_dir)
    open(os.path.join(agents_dir, orq_mod.LAUNCHD_LABEL + ".plist"), "w").close()  # the plist exists, as the real one does on the machine
    _fake_launchctl316(t)  # a launchctl on PATH: what `serve --stop` would have called
    r = a.orq("gerente", "serve", "--parar", ORQ_LAUNCH_AGENTS=agents_dir, PATH=t + os.pathsep + os.environ["PATH"], ORQ_LAUNCHCTL="")
    assert r.returncode != 0 and "ORQ_LAUNCHCTL" in r.stderr, (r.returncode, r.stderr)
    assert not os.path.exists(os.path.join(t, "launchctl.log")), "o launchctl real (do PATH) foi chamado por um teste"


def test_ticket316_every_launchctl_call_and_stop_records_its_caller():
    a = Env(run="run_a")
    t = os.path.dirname(a.home)
    env = {"ORQ_LAUNCH_AGENTS": os.path.join(t, "LaunchAgents"), "ORQ_LAUNCHCTL": _fake_launchctl316(t)}
    _manager(a)
    p = _serve128(a)
    try:
        assert a.orq("gerente", "serve", "--instalar", cwd=t, **env).returncode == 0
        assert a.orq("gerente", "serve", "--parar", cwd=t, **env).returncode == 0
        p.wait(timeout=15)
    finally:
        p.kill()
    assert a.orq("gerente", "serve", "--desinstalar", cwd=t, **env).returncode == 0
    evs = [e for e in a.events() if e.get("tipo") == "launchd"]
    assert [e["op"] for e in evs] == ["bootout", "bootstrap", "bootout", "stop", "bootout"], evs
    for e in evs:
        assert e["pid"] and e["ppid"] and e["parent"] and os.path.realpath(e["cwd"]) == os.path.realpath(t), e
        assert e["argv"].endswith("orq.py gerente serve --instalar") or "--parar" in e["argv"] or "--desinstalar" in e["argv"], e
    assert evs[3]["target"] == p.pid, "the stop names the pid it sent SIGTERM to"


# ---- ticket 96: E2E queue and transcripts come from the project file ----

class _Home:
    """ORQ_HOME, ~/.cache and the Claude transcripts folder replaced by temporary folders, and the environment queue/transcripts unset."""
    def __enter__(self):
        self.tmp = tempfile.TemporaryDirectory()
        t = self.tmp.name
        self.home, self.cache, self.claude = os.path.join(t, "orq"), os.path.join(t, "cache"), os.path.join(t, "claude-projects")
        self.before = (orq_mod.HOME, orq_mod.PROJECTS, orq_mod.TRANSCRIPTS, {k: os.environ.pop(k, None) for k in ("E2E_LOCK_DIR", "XDG_CACHE_HOME")})
        orq_mod.HOME, orq_mod.PROJECTS, orq_mod.TRANSCRIPTS = self.home, self.claude, None
        os.environ["XDG_CACHE_HOME"] = self.cache
        return self

    def project(self, item_name, dado):
        os.makedirs(os.path.join(self.home, "projects"), exist_ok=True)
        json.dump(dado, open(os.path.join(self.home, "projects", f"{item_name}.json"), "w"))

    def __exit__(self, *a):
        orq_mod.HOME, orq_mod.PROJECTS, orq_mod.TRANSCRIPTS, env = self.before
        for k, v in env.items():
            os.environ.pop(k, None) if v is None else os.environ.__setitem__(k, v)
        self.tmp.cleanup()


