# ticket 93: coordinator handoff between harnesses

def _handoff93(a, *args, **env):
    """`orq handoff coordinator` with a gh and engram that do not exist (the snapshot must not call the network or the machine)."""
    return a.orq("passagem", "coordenador", *args, ORQ_GH="/nao/existe/gh", ORQ_ENGRAM="/nao/existe/engram", **env)


def _session93(a, harness, sid="s_outro", source="startup"):
    r = a.orq("hook", "session", harness, stdin=json.dumps({"session_id": sid, "source": source, "hook_event_name": "SessionStart"}))
    assert r.returncode == 0, r.stderr
    return json.loads(r.stdout)["hookSpecificOutput"]["additionalContext"] if r.stdout else ""


def test_ticket93_coordinator_handoff_writes_snapshot_and_who_wrote_it():
    a = Env(run="run_a")
    _new(a, "Ticket do snapshot")
    r = _handoff93(a, "--para", "codex")
    assert r.returncode == 0, r.stderr
    out = json.loads(r.stdout)
    assert (out["de"], out["para"]) == ("claude", "codex") and out["arquivo"].endswith(".md"), out
    md = open(os.path.join(a.home, "handoff", "ultimo.md")).read()
    assert "## Bound Run\nrun_a" in md and "## Agents" in md and "Ticket do snapshot" in md, md
    reg = _read_state(os.path.join(a.home, "handoff", "passagem.json"))
    assert (reg["de"], reg["para"], reg["run"]) == ("claude", "codex", "run_a") and abs(reg["ts"] - time.time()) < 60 and not reg.get("aceita"), reg


