# ---------- ticket 101: the tasks-axi backlog (M1 reader and writer, M2 migration, M3 pending items, M4 digest) ----------

import backlog as backlog_mod  # noqa: E402

CONVERT_SCRIPT = os.path.join(HERE, "scripts", "converte-backlog.py")


def _bl_json(path, *args):
    return json.loads(backlog_mod.cli(path, *args, "--json"))["task"]


def _env_bl(**env):
    """Environment with ORQ_BACKLOG: the starting pending items (freio-prod, avisar-x) go in through `orq pending add` itself."""
    a = Env(**env)
    a.env["ORQ_BACKLOG"] = os.path.join(a.tmp.name, "data", "backlog.md")
    a.set("../pendencias.json", {"itens": []})
    for id_, type_name in (("freio-prod", "decisao"), ("avisar-x", "avisar")):
        r = a.orq("pend", "add", "--id", id_, "--tipo", type_name, "--titulo", id_.replace("-", " "))
        assert r.returncode == 0, r.stderr
    return a


def _bl_items(a):
    return {i["id"]: i for i in backlog_mod.read_value(a.env["ORQ_BACKLOG"])}


def test_ticket101_contract_the_reader_agrees_with_the_real_tasks_axi():
    """Runs the real tasks-axi 0.2.6 (without it the test fails: it proves that the grammar being read is still the CLI's)."""
    p = os.path.join(tempfile.mkdtemp(), "backlog.md")
    ops = [("add", "a1", "Primeiro (com parênteses): e dois pontos", "--kind", "ticket", "--repo", "orq", "--priority", "2", "--body", "spec: issues/01-a.md\norca: task_1 run_1\n\nParágrafo\n  indentado"),
           ("add", "b2", "Segundo", "--kind", "decisao", "--repo", "pend"),
           ("add", "c3", "Terceiro", "--blocked-by", "a1"),
           ("hold", "b2", "--reason", "decisão pendente", "--kind", "captain", "--until", "2999-01-01"),
           ("hold", "c3", "--reason", "vencido", "--kind", "external", "--until", "2000-01-01"),
           ("start", "a1"),
           ("block", "b2", "--by", "a1"),
           ("add", "d4", "Quarto"),
           ("done", "d4", "--no-prune", "--pr", "https://github.com/o/r/pull/42"),
           ("done", "b2", "--no-prune", "--note", "linha um\nlinha dois"),
           ("update", "a1", "--title", "Primeiro, renomeado", "--body", "spec: issues/01-a.md"),
           ("unhold", "c3"),
           ("add", "e5", "Quinto, livre")]
    for op in ops:
        t = _bl_json(p, *op)
        i = _bl_items_of(p)[t["id"]]
        by_id = _bl_items_of(p)
        assert i["titulo"] == t["title"] and i["kind"] == t["kind"] and i["repo"] == t["repo"] and i["prioridade"] == t["priority"], (op, i, t)
        assert {"queued": "queued", "in_flight": "in_flight", "done": "done"}[i["estado"]] == t["state"], (op, i, t)
        assert (i["closed"] if i["estado"] == "done" else i["since"]) == (t["closed"] if t["state"] == "done" else t["created"]), (op, i, t)
        assert i["bloqueios"] == [d["id"] for d in t["deps"] if d["type"] == "blocked-by"] and i["corpo"] == (t["body"] or ""), (op, i, t)
        h = t["hold"]
        assert (i["hold"] and {"reason": i["hold"]["motivo"], "kind": i["hold"]["kind"], "until": i["hold"]["until"]}) == (h and {"reason": h["reason"], "kind": h.get("kind"), "until": h.get("until")}) or (not i["hold"] and not h), (op, i, t)
        assert backlog_mod.is_blocked(i, by_id) == (t["blocked"] and t["state"] != "done") and backlog_mod.active_hold(i) == t["held"], (op, i, t)
    before = open(p).read()
    backlog_mod.cli(p, "render")
    assert open(p).read() == before, "o arquivo que a CLI escreve já está na forma canônica"
    ids = re.findall(r"^  ([^,\s]+),", backlog_mod.cli(p, "ready").split("ready[", 1)[1], re.M)
    assert ids == [i["id"] for i in backlog_mod.ready(backlog_mod.read_value(p))] == ["e5"], ids
    without_blank = lambda t: [l for l in t.replace("(merged ", "(done ").splitlines() if l.strip()]  # noqa: E731 - the CLI does not separate the sections and swaps done for merged when there is a PR link
    assert without_blank(backlog_mod.emit(backlog_mod.read_value(p))) == without_blank(before), "emite reproduz o que a CLI escreve"


def _bl_items_of(p):
    return {i["id"]: i for i in backlog_mod.read_value(p)}


def test_ticket101_reader_grammar_sections_tags_body_and_old_forms():
    src = """# Backlog

Nota solta no preâmbulo, fora de seção.

## In flight
- **velho** - Linha legada (repo: orq) (since 2026-09-01)
  corpo legado
- [ ] novo - Titulo (com parenteses) (kind: ticket) (priority: 3) (orq + repo: extra) (since 2026-09-02)

  spec: a.md

  segundo parágrafo
nota solta no meio
## Queued
- [ ] q1 - Espera (repo: x) blocked-by: velho - porque sim
- [ ] q2 - Outro blocked-by: fantasma (hold: motivo longo) (hold-kind: parked) (hold-until: 2999-12-31)
## Done (arquivo)
- [x] d1 - Feito (merged 2026-09-03)
## Outra coisa
- [ ] z - não é item
"""
    it = {i["id"]: i for i in backlog_mod.parse(src)}
    assert list(it) == ["velho", "novo", "q1", "q2", "d1"], list(it)
    assert (it["velho"]["estado"], it["velho"]["repo"], it["velho"]["since"], it["velho"]["corpo"]) == ("in_flight", "orq", "2026-09-01", "corpo legado")
    n = it["novo"]
    assert (n["titulo"], n["kind"], n["prioridade"], n["repo"]) == ("Titulo (com parenteses)", "ticket", 3, "extra"), n
    assert n["corpo"] == "\nspec: a.md\n\nsegundo parágrafo", repr(n["corpo"])
    assert it["q1"]["bloqueios"] == ["velho"] and it["q1"]["titulo"] == "Espera" and it["q1"]["repo"] == "x"
    assert it["q2"]["bloqueios"] == ["fantasma"] and it["q2"]["hold"] == {"motivo": "motivo longo", "kind": "parked", "until": "2999-12-31"}
    assert (it["d1"]["estado"], it["d1"]["closed"]) == ("done", "2026-09-03")
    by_id = it
    assert backlog_mod.is_blocked(it["q1"], by_id) and not backlog_mod.is_blocked(it["q2"], by_id), "bloqueador que não existe conta como resolvido"
    assert backlog_mod.active_hold(it["q2"]) and not backlog_mod.active_hold({"estado": "queued", "hold": {"motivo": "x", "until": "2000-01-01"}}) and not backlog_mod.active_hold({"estado": "queued", "hold": {"motivo": "x", "until": today_date()}}), "no dia da data o hold já solta"
    assert backlog_mod.parse("") == [] and backlog_mod.read_value("/nao/existe/backlog.md") == []


def today_date():
    return datetime.now().date().isoformat()


def test_ticket101_body_meta_round_trips_without_confusing_with_the_detail():
    ch = backlog_mod.META_PENDING
    body_text = backlog_mod.body_with_meta({"frente": "cache", "link": "http://x", "espera": "a b\nc"}, "link: isto é detalhe\nsegunda linha", ch)
    assert body_text == "frente: cache\nlink: http://x\nespera: a b c\n\nlink: isto é detalhe\nsegunda linha", body_text
    meta, rest = backlog_mod.body_meta(body_text, ch)
    assert meta == {"frente": "cache", "link": "http://x", "espera": "a b c"} and rest == "link: isto é detalhe\nsegunda linha"
    without = backlog_mod.body_with_meta({}, "link: parece meta", ch)
    assert backlog_mod.body_meta(without, ch) == ({}, "link: parece meta"), "a linha em branco na frente protege o detalhe"
    assert backlog_mod.body_with_meta({}, None, ch) == "" and backlog_mod.body_meta("", ch) == ({}, "")


def test_ticket101_whole_backlog_reader_fits_the_hook_cap():
    item_list = [{"id": f"t{n}", "titulo": f"orq: ticket {n} com um título de tamanho normal", "estado": ("done", "queued", "in_flight")[n % 3], "kind": "ticket", "repo": "orq",
              "bloqueios": [f"t{n - 1}"] if n else [], "since": "2026-10-01", "closed": "2026-10-01", "corpo": f"spec: issues/{n}.md\norca: task_{n} run_{n}"} for n in range(600)]
    p = os.path.join(tempfile.mkdtemp(), "backlog.md")
    open(p, "w").write(backlog_mod.emit(item_list))
    t0 = time.process_time()  # the CPU the parse costs: wall time on a loaded machine (other suites, -j 4) also counts the waits for a core (ticket 328)
    read_handles = backlog_mod.read_value(p)
    ms = (time.process_time() - t0) * 1000
    assert len(read_handles) == 600 and ms < 40, f"{ms:.1f} ms para 600 itens: o teto do hook é 100 ms com tudo junto"


def _fake_tasks_axi(version):
    d = tempfile.mkdtemp()
    exe = os.path.join(d, "tasks-axi")
    open(exe, "w").write(f'#!/bin/sh\n[ "$1" = "--version" ] && echo {version} && exit 0\necho "escreveu" >> "{d}/chamadas"\n')
    os.chmod(exe, 0o755)
    return exe, d


def test_ticket101_write_refuses_wrong_version_file_and_symlink():
    exe, d = _fake_tasks_axi("0.2.5")
    before = os.environ.get("ORQ_TASKS_AXI")
    os.environ["ORQ_TASKS_AXI"] = exe
    try:
        try:
            backlog_mod.cli(os.path.join(d, "b.md"), "add", "x", "y")
            assert False, "devia recusar"
        except backlog_mod.BacklogError as e:
            assert "0.2.5" in str(e) and "npm i -g tasks-axi@0.2.6" in str(e), e
        assert not os.path.exists(os.path.join(d, "chamadas")), "a CLI na versão errada nem chega a escrever"
    finally:
        os.environ.pop("ORQ_TASKS_AXI") if before is None else os.environ.__setitem__("ORQ_TASKS_AXI", before)
    for args in (("--file", "x.md"), ("--file=x.md",)):
        try:
            backlog_mod.cli(os.path.join(d, "b.md"), "list", *args)
            assert False
        except ValueError as e:
            assert "ORQ_BACKLOG" in str(e)
    real = os.path.join(d, "real.md")
    open(real, "w").write("# Backlog\n")
    os.symlink(real, os.path.join(d, "elo.md"))
    try:
        backlog_mod.cli(os.path.join(d, "elo.md"), "list")
        assert False
    except backlog_mod.BacklogError as e:
        assert "symlink" in str(e)


def test_ticket101_ticket_states_follow_the_orq_statuses():
    assert backlog_mod.TICKET_STATE == {"queued": orq_mod.STATUS_NEW, "in_flight": orq_mod.STATUS_IN_PROGRESS, "done": orq_mod.STATUS_CLOSED}


# ---- M2: the conversion ----

def _issues_101(a):
    """Five tickets: 01 resolved, 02 blocked by 01 (resolved), 03 blocked by 02, 04 in progress, 05 with 'Blocked by: none (… 30/09)'."""
    os.makedirs(a.env["ORQ_ISSUES"], exist_ok=True)
    os.makedirs(a.home, exist_ok=True)
    tks = [("01", "orq: Base", "resolved", "(nenhum)", "task_a1", "run_a", ""), ("02", "orq: Segundo", "ready-for-agent", "01", None, None, ""),
           ("03", "Terceiro sem prefixo", "ready-for-agent", "02", "task_c3", "run_a", "Modelo: claude-opus-5-5\nEffort: high\nissue: #2045\n"),
           ("04", "Em curso", "claimed", "(nenhum)", "task_d4", "run_a", ""), ("05", "Paralelo", "ready-for-agent", "none (roda em paralelo numa worktree própria, 30/09)", None, None, "Despacho: manual, só depois da fase 3\nEspera: integrador vazio\n")]
    for nn, title, status, bl, task, run, extra in tks:
        cab = f"# {nn}: {title}\n\nStatus: {status}\nBlocked by: {bl}\n" + (f"Run: {run}\n" if run else "") + (f"Task: {task}\n" if task else "") + extra
        open(os.path.join(a.env["ORQ_ISSUES"], f"{nn}-x.md"), "w").write(cab + "\n## What to build\n\ncorpo\n")
    _evs(a, {"ts": "2026-09-20T10:00:00Z", "tipo": "ticket", "op": "novo", "ticket": "01"}, {"ts": "2026-09-25T10:00:00Z", "tipo": "ticket", "op": "fechar", "ticket": "01"},
         {"ts": "2026-09-21T10:00:00Z", "tipo": "ticket", "op": "novo", "ticket": "02"})


def _convert(a, output, *extra):
    return subprocess.run([sys.executable, CONVERT_SCRIPT, "--saida", output, "--issues", a.env["ORQ_ISSUES"], "--pendencias", a.env["ORQ_PENDENCIAS"],
                           "--eventos", os.path.join(a.home, "events.jsonl"), *extra], capture_output=True, text=True, env=a.env, timeout=60)


def test_ticket101_m2_convert_emits_backlog_checks_counts_and_writes_only_to_new_file():
    a = Env()
    _issues_101(a)
    a.set("../pendencias.json", {"itens": [{"id": "freio-prod", "tipo": "decisao", "titulo": "Freio (teto) de prod?", "detalhe": "linha 1\nlinha 2", "frente": "cache", "desde": "2026-09-30"},
                                          {"id": "esp-x", "tipo": "acao", "titulo": "Girar a chave", "espera": "time de ops (Alice)", "ate": "2999-01-01", "link": "http://x", "desde": "2026-09-29"}]})
    output = os.path.join(a.tmp.name, "data", "backlog.md")
    r = _convert(a, output)
    assert r.returncode == 0, (r.stdout, r.stderr)
    assert "5 tickets (1 Done), 2 pendências, 2 bloqueios, 2 prontos" in r.stdout, r.stdout
    it = _bl_items_of(output)
    assert it["t01"]["estado"] == "done" and it["t01"]["closed"] == "2026-09-25" and it["t02"]["since"] == "2026-09-21", "datas dos eventos"
    assert it["t02"]["bloqueios"] == ["t01"] and it["t03"]["bloqueios"] == ["t02"] and it["t05"]["bloqueios"] == [], "só os números do começo do campo"
    assert it["t02"]["repo"] == "orq" and it["t03"]["repo"] is None and it["t04"]["estado"] == "in_flight"
    assert sorted(i["id"] for i in backlog_mod.ready(backlog_mod.read_value(output)) if i["kind"] == "ticket") == ["t02", "t05"]
    meta, _ = backlog_mod.body_meta(it["t03"]["corpo"], backlog_mod.META_TICKET)
    assert meta == {"spec": "issues/03-x.md", "orca": "task_c3 run_a", "modelo": "claude-opus-5-5", "effort": "high", "issue": "2045"}, meta
    meta5, _ = backlog_mod.body_meta(it["t05"]["corpo"], backlog_mod.META_TICKET)
    assert meta5["despacho"] == "manual, só depois da fase 3" and meta5["espera"] == "integrador vazio", meta5
    assert it["esp-x"]["hold"] == {"motivo": "waiting on time de ops Alice", "kind": "external", "until": "2999-01-01"} and it["esp-x"]["repo"] == "pend"
    assert open(os.path.join(a.tmp.name, "data", ".tasks.toml")).read().count("done_keep = 100000") == 1
    r2 = _convert(a, output)
    assert r2.returncode == 1 and "já existe" in r2.stderr, "não sobrescreve o backlog que existe"
    assert _convert(a, output, "--forcar").returncode == 0


def test_ticket101_m2_backlog_tickets_are_those_of_the_files_except_the_already_resolved_blocker():
    a = Env()
    _issues_101(a)
    a.set("../pendencias.json", {"itens": []})
    output = os.path.join(a.tmp.name, "data", "backlog.md")
    assert _convert(a, output).returncode == 0
    old_values = (orq_mod.ISSUES, orq_mod.BACKLOG, orq_mod.BACKLOG_TICKETS)
    try:
        orq_mod.ISSUES, orq_mod.BACKLOG, orq_mod.BACKLOG_TICKETS = a.env["ORQ_ISSUES"], output, None
        file_path = {t["num"]: t for t in orq_mod.tickets()}
        orq_mod.BACKLOG_TICKETS = "1"
        bl = {t["num"]: t for t in orq_mod.tickets()}
    finally:
        orq_mod.ISSUES, orq_mod.BACKLOG, orq_mod.BACKLOG_TICKETS = old_values
    assert list(file_path) == list(bl) == ["01", "02", "03", "04", "05"]
    for n in file_path:
        assert {k: v for k, v in file_path[n].items() if k != "blocked_by"} == {k: v for k, v in bl[n].items() if k not in ("blocked_by", "fechado_em")}, (n, file_path[n], bl[n])
    assert file_path["02"]["blocked_by"] == ["01"] and bl["02"]["blocked_by"] == [], "o bloqueador resolvido não bloqueia mais"
    assert file_path["05"]["blocked_by"] == ["30", "09"] and bl["05"]["blocked_by"] == [], "o achado do ticket 72: o leitor antigo lia 30 e 09 do comentário"
    assert (bl["05"]["despacho"], bl["05"]["espera"]) == ("manual, só depois da fase 3", "integrador vazio") == (file_path["05"]["despacho"], file_path["05"]["espera"])
    assert bl["03"]["blocked_by"] == ["02"] and bl["03"]["modelo"] == "claude-opus-5-5" and bl["03"]["issue"] == 2045 and bl["03"]["task"] == "task_c3" and bl["03"]["run"] == "run_a"


def test_ticket167_resolved_ticket_in_backlog_keeps_blocked_by_of_file():
    base = {"kind": "ticket", "corpo": [], "closed": None}
    by_id = {"t06": {"estado": "done"}, "t09": {"estado": "queued"}}
    done = backlog_mod.ticket_of_item({**base, "id": "t07", "titulo": "x", "estado": "done", "bloqueios": ["t06", "t09"]}, by_id, "/r")
    open_state = backlog_mod.ticket_of_item({**base, "id": "t08", "titulo": "y", "estado": "queued", "bloqueios": ["t06", "t09"]}, by_id, "/r")
    assert done["blocked_by"] == ["06", "09"], "Done guarda o histórico do cabeçalho"
    assert open_state["blocked_by"] == ["09"], "aberto só mostra quem ainda bloqueia"


# ---- M3: pending items in the backlog ----

def test_ticket101_m3_pending_add_done_writes_to_backlog_mirrors_the_json_and_records_the_event():
    a = _env_bl()
    r = a.orq("pend", "add", "--id", "avisar-alice", "--tipo", "avisar", "--titulo", "Avisar o Alice", "--espera", "Alice", "--frente", "cache")
    assert r.returncode == 0, r.stderr
    it = _bl_items(a)["avisar-alice"]
    assert (it["repo"], it["kind"], it["estado"]) == ("pend", "avisar", "queued") and it["hold"]["kind"] == "external" and "frente: cache" in it["corpo"] and "espera: Alice" in it["corpo"]
    mirror = _pending(a)
    assert [i["id"] for i in mirror["itens"]] == ["freio-prod", "avisar-x", "avisar-alice"] and "atualizadoEm" in mirror
    assert list(mirror["itens"][2]) == ["id", "tipo", "titulo", "frente", "desde", "espera"], mirror["itens"][2]
    assert a.orq("pend", "add", "--id", "outra", "--tipo", "acao", "--titulo", "X", "--detalhe", "d", "--link", "l", "--comando", "c").returncode == 0
    r = a.orq("pend", "done", "avisar-alice", "--resposta", "avisei")
    assert r.returncode == 0, r.stderr
    assert [i["id"] for i in _pending(a)["itens"]] == ["freio-prod", "avisar-x", "outra"], "fechada sai da lista viva"
    end = _bl_items(a)["avisar-alice"]
    assert end["estado"] == "done" and end["corpo"].endswith("avisei"), "a resposta fica no corpo e o histórico no backlog"
    evs = [e for e in a.events() if e["tipo"] == "pend" and e["pend"] in ("avisar-alice", "outra")]
    assert [(e["op"], e["pend"]) for e in evs] == [("add", "avisar-alice"), ("add", "outra"), ("done", "avisar-alice")] and evs[2]["resposta"] == "avisei"
    assert not [f for f in os.listdir(os.path.dirname(a.env["ORQ_PENDENCIAS"])) if f.startswith("tmp")]


