    assert [i["id"] for i in _pending(a2)["itens"]] == ["freio-prod", "avisar-x"], "texto livre não fecha"
    assert "free-text answer in freio-prod" in json.loads(r.stdout)["hookSpecificOutput"]["additionalContext"]


