def test_ticket101_m4_digest_builds_pending_and_orq_tickets_from_backlog_with_same_contract():
    a = Env(run="run_a")
    _issues_101(a)
    a.set("../pendencias.json", {"itens": [{"id": "freio-prod", "tipo": "decisao", "titulo": "Freio", "detalhe": "d", "desde": "2026-09-30"},
                                          {"id": "futura", "tipo": "acao", "titulo": "Adiada", "ate": "2999-01-01", "desde": "2026-09-30"}]})
    os.makedirs(os.path.join(a.home, "..", "orq"), exist_ok=True)
    a.set("../orq/aberto.json", _open_agent("rodando"))
    base = _json_digest(a)
    output = os.path.join(a.tmp.name, "data", "backlog.md")
    assert _convert(a, output).returncode == 0
    a.env["ORQ_BACKLOG"], a.env["ORQ_BACKLOG_TICKETS"] = output, "1"
    a.set("../pendencias.json", {"itens": []})  # the empty mirror and the removed tickets folder prove the source is the backlog
    shutil.rmtree(a.env["ORQ_ISSUES"])
    new = _json_digest(a)
    assert sorted(new) == sorted(base) and new["pendencias"] == base["pendencias"]
    assert [(p["id"], p["depois"]) for p in new["pendencias"]] == [("freio-prod", False), ("futura", True)]
    assert sorted(new["tickets_orq"]) == sorted(base["tickets_orq"]) == ["abertos", "resolvidos"]
    ab = {t["num"]: t for t in new["tickets_orq"]["abertos"]}
    assert sorted(ab) == ["02", "03", "04", "05"] and ab["02"]["grupo"] == "pronto" and ab["04"]["grupo"] == "andamento", ab
    assert (ab["03"]["grupo"], ab["03"]["bloqueios"]) == ("bloqueado", ["02"]) and ab["04"]["task"] == "task_d4" and ab["03"]["arquivo"].endswith("issues/03-x.md")
    assert [(t["num"], t["em"]) for t in new["tickets_orq"]["resolvidos"]] == [("01", "2026-09-25")], "a data é a do fechamento no backlog, não a do arquivo"
    assert json.load(open(a.env["ORQ_PENDENCIAS"]))["itens"] == [], "o digest só lê: o espelho não foi tocado"


