# ---------- ticket 89: orq transcrito, neutral reader for Claude and Codex ----------

def _transcribed_cli(a, item_name, *args):
    os.makedirs(a.home, exist_ok=True)
    _write_state(os.path.join(a.home, "turnos.json"), {"ctx_w1": {"task": "task_w1", "inicio": now_iso(-600), "fim": None, "harness": "claude", "transcrito": os.path.join(FIX, item_name)}})
    return a.orq("transcrito", "ctx_w1", *args)


def test_it_should_be_that_orq_transcript_reads_a_claude_transcript_without_reasoning_or_meta():
    r = json.loads(_transcribed_cli(Env(run="run_a"), "transcrito-claude.jsonl", "--json").stdout)
    assert [(e["tipo"], e["papel"]) for e in r["eventos"]] == [("mensagem", "user"), ("mensagem", "assistant"), ("chamada", "assistant"), ("resultado", "user"), ("mensagem", "assistant")], r
    assert r["eventos"][2]["nome"] == "Bash" and r["eventos"][2]["texto"] == "pytest -q" and r["eventos"][3]["texto"] == "2 failed, 40 passed"
    assert "segredo" not in json.dumps(r["eventos"]) and "caveat" not in json.dumps(r["eventos"])
    assert r["cortes"] == {"reasoning": 1, "meta record (isMeta)": 1, "meta record (summary)": 1} and r["aberto"] is False


def test_it_should_be_that_orq_transcript_reads_a_codex_rollout_with_tool_calls():
    r = json.loads(_transcribed_cli(Env(run="run_a"), "transcrito-codex.jsonl", "--json").stdout)
    kinds = [e["tipo"] for e in r["eventos"]]
    assert kinds == ["mensagem", "mensagem", "mensagem", "chamada", "resultado", "mensagem"], kinds
    assert r["eventos"][3]["texto"] == "bash -lc pytest -q" and r["eventos"][4]["texto"] == "2 failed, 40 passed"
    assert r["cortes"] == {"environment context": 1, "reasoning": 1, "meta record (event_msg)": 1, "meta record (session_meta)": 1}, r["cortes"]


def test_it_should_be_that_orq_transcript_keeps_the_last_n_events_and_lists_the_cuts_in_text():
    p = _transcribed_cli(Env(run="run_a"), "transcrito-claude.jsonl", "--ultimos", "2")
    assert p.returncode == 0 and p.stdout.splitlines()[:2] == ["[result] 2 failed, 40 passed", "[assistant] faltam dois testes"], p.stdout
    assert "cut: meta record (isMeta) ×1, meta record (summary) ×1, reasoning ×1" in p.stdout


def test_it_should_be_that_the_reader_flags_an_open_turn_and_truncates_long_texts():
    with tempfile.TemporaryDirectory() as t:
        file_path = os.path.join(t, "a.jsonl")
        line_list = [{"type": "assistant", "message": {"content": [{"type": "text", "text": "x" * 7000}, {"type": "tool_use", "name": "Bash", "input": {"command": "pytest"}}]}}, "lixo{"]
        open(file_path, "w").write("\n".join(x if isinstance(x, str) else json.dumps(x) for x in line_list))
        r = orq_mod.read_transcript(file_path)
    assert r["aberto"] is True and len(r["eventos"][0]["texto"]) == orq_mod.HANDOFF_MSG_MAX
    assert r["cortes"] == {"truncated text": 1, "unreadable line": 1}, r["cortes"]
    assert orq_mod.read_transcript("/nao/existe.jsonl") == {"eventos": [], "cortes": {}, "aberto": False}


