def test_it_should_type_at_most_notice_max_characters_and_cite_the_file_with_the_full_text():
    import tempfile
    before = (orq_mod.free_terminal, orq_mod.orca, orq_mod.HOME, orq_mod.NOTICE_GAP_S, orq_mod._turn_screen_without_draft)
    sent = []
    orq_mod.orca = lambda *a, **k: sent.append(a[a.index("--text") + 1]) or {"send": {"prompt": {"observation": "unsupported"}}}
    orq_mod.free_terminal, orq_mod._turn_screen_without_draft, orq_mod.NOTICE_GAP_S = lambda h: None, lambda h: True, 0
    try:
        with tempfile.TemporaryDirectory() as d:
            orq_mod.HOME = d
            short = "orq: PR #1 entered development"
            long_text = "orq: worker task_1 terminou " + "x" * 400
            assert orq_mod.type_text("term_c", short) == "enviado" and sent == [short], "o texto curto vai como está e não cria arquivo"
            assert not os.path.exists(os.path.join(d, "avisos"))
            for fn in (orq_mod.type_text, orq_mod.type_text_busy):
                sent.clear()
                fn("term_c", long_text)
                (typed,) = sent
                path = typed.split("full text at ")[1]
                assert len(typed) <= orq_mod.NOTICE_MAX and typed.startswith("orq: worker task_1"), typed
                assert os.path.isabs(path) and open(path, encoding="utf-8").read() == long_text + "\n", "o caminho citado tem o texto inteiro"
    finally:
        orq_mod.free_terminal, orq_mod.orca, orq_mod.HOME, orq_mod.NOTICE_GAP_S, orq_mod._turn_screen_without_draft = before


