def test_it_should_be_that_the_pre_push_hook_refuses_a_bad_push_and_lets_a_clean_one_through():
    hook = os.path.join(HERE, "githooks", "pre-push")
    with tempfile.TemporaryDirectory() as t:
        repo, env, g = _publication_repo(t)
        base = g("rev-parse", "HEAD")
        zero = "0" * 40
        push = lambda: subprocess.run(["sh", hook], cwd=repo, input=f"refs/heads/main {g('rev-parse', 'HEAD')} refs/heads/main {base}\n", capture_output=True, text=True, env=env)  # noqa: E731
        open(os.path.join(repo, "f"), "w").write("a")
        g("commit", "-qam", "feat: bad", GIT_AUTHOR_EMAIL="noreply@anthropic.com")
        r = push()
        assert r.returncode == 1 and "noreply@anthropic.com" in r.stderr, r.stderr
        g("commit", "--amend", "-qC", "HEAD", "--reset-author")
        assert push().returncode == 0
        r = subprocess.run(["sh", hook], cwd=repo, input=f"(delete) {zero} refs/heads/x {base}\n", capture_output=True, text=True, env=env)
        assert r.returncode == 0, r.stderr


# ---------- ticket 143: orq pr abrir ----------

FAKE_GIT143 = """#!/usr/bin/env python3
import json, os, sys
d = os.environ["FAKE_DIR"]
a = sys.argv[3:] if sys.argv[1] == "-C" else sys.argv[1:]
open(os.path.join(d, "git.log"), "a").write(json.dumps(a) + "\\n")
if a[:2] == ["branch", "--show-current"]:
    print(os.environ["FAKE_BRANCH"])
elif a[0] == "merge-tree" and os.environ.get("FAKE_CONFLITO") in a:
    print("treeoid\\nsrc/a.js"); sys.exit(1)
"""
FAKE_GH143 = """#!/usr/bin/env python3
import json, os, sys
d = os.environ["FAKE_DIR"]
open(os.path.join(d, "gh.log"), "a").write(json.dumps(sys.argv[1:]) + "\\n")
file_path = os.path.join(d, "gh.json")
data = json.load(open(file_path)) if os.path.exists(file_path) else {}
if sys.argv[2] == "create":
    url = "https://github.com/acme/app/pull/%d" % (300 + len(data))
    data[url] = {"state": "OPEN", "mergedAt": None, "baseRefName": sys.argv[sys.argv.index("--base") + 1], "title": sys.argv[sys.argv.index("--title") + 1]}
    json.dump(data, open(file_path, "w")); print(url)
elif sys.argv[2] == "view" and sys.argv[3] in data:
    print(json.dumps(data[sys.argv[3]]))
else:
    sys.exit(1)
"""
BODY143 = "## Summary\nx\n\n## Evidence\ny\n\n## Merge Danger\nz\n"


def _open_pr143(branch="leodiegoo/feat/algo", conflict=None):
    a = Env(run="run_a", FAKE_BRANCH=branch, **({"FAKE_CONFLITO": conflict} if conflict else {}))
    _neo(a)
    for item_name, src, var in (("git", FAKE_GIT143, "ORQ_GIT"), ("gh", FAKE_GH143, "ORQ_GH")):
        path = os.path.join(a.tmp.name, item_name + "143")
        with open(path, "w") as f:
            f.write(src)
        os.chmod(path, 0o755)
        a.env[var] = path
    wt = os.path.join(a.tmp.name, "wt")
    os.makedirs(wt)
    a.set("workers.json", [{"handle": "term_w", "run": "run_a", "worktree": wt}])
    with open(os.path.join(a.home, "events.jsonl"), "a") as f:
        f.write(json.dumps({"tipo": "despacho", "run": "run_a", "task": "task_feat", "dispatch": "ctx_term_w", "titulo": "Algo"}) + "\n")
    body_text = os.path.join(a.tmp.name, "corpo.md")
    open(body_text, "w").write(BODY143)
    a.body_text = body_text
    return a


def _open_pr(a, *extra, body_text=None):
    return a.orq("pr", "abrir", "ctx_term_w", "--titulo", "feat: add algo", "--corpo", body_text or a.body_text, *extra)


def _log143(a, item_name):
    return [json.loads(l) for l in open(os.path.join(a.fake, item_name)).read().splitlines()] if os.path.exists(os.path.join(a.fake, item_name)) else []


def test_ticket143_pr_open_strips_prefix_pushes_opens_one_pr_per_environment_and_links_task():
    a = _open_pr143()
    r = _open_pr(a)
    assert r.returncode == 0, r.stderr
    git = _log143(a, "git.log")
    assert ["branch", "-m", "leodiegoo/feat/algo", "feat/algo"] in git, git
    assert git.index(["branch", "-m", "leodiegoo/feat/algo", "feat/algo"]) < next(n for n, c in enumerate(git) if c[0] == "push"), "renomeia antes do push"
    assert [c for c in git if c[0] == "push"] == [["push", "-u", "origin", "feat/algo"]]
    created_items = [c for c in _log143(a, "gh.log") if c[:2] == ["pr", "create"]]
    assert [c[c.index("--base") + 1] for c in created_items] == ["development", "staging"], created_items
    assert all(c[c.index("--head") + 1] == "feat/algo" and c[c.index("--body-file") + 1] == a.body_text for c in created_items)
    assert "https://github.com/acme/app/pull/300" in r.stdout and "https://github.com/acme/app/pull/301" in r.stdout, r.stdout
    item_list = _read_state(os.path.join(a.home, "prs.json"))["itens"]
    assert [(i["task"], i["base"]) for i in item_list] == [("task_feat", "development"), ("task_feat", "staging")], item_list


def test_ticket143_pr_open_stops_on_conflict_before_push():
    a = _open_pr143(conflict="origin/staging")
    r = _open_pr(a)
    assert r.returncode == 1 and "staging" in r.stderr and "src/a.js" in r.stderr, r
    assert not [c for c in _log143(a, "git.log") if c[0] == "push"] and not _log143(a, "gh.log"), "nada sobe com conflito"


def test_ticket143_pr_open_refuses_generator_footer_trailer_and_empty_body():
    a = _open_pr143()
    for bad in ("## Summary\nx\n\n\U0001F916 Generated with [Claude Code](https://claude.com/claude-code)\n", "x\n\nCo-Authored-By: Claude <n@a.com>\n", "  \n"):
        open(a.body_text, "w").write(bad)
        r = _open_pr(a)
        assert r.returncode == 1 and not _log143(a, "gh.log") and not _log143(a, "git.log"), (bad, r.stderr)
    open(a.body_text, "w").write(BODY143)
    r = a.orq("pr", "abrir", "ctx_term_w", "--titulo", "Add algo", "--corpo", a.body_text)
    assert r.returncode == 1 and "Conventional" in r.stderr, r


