# ---------- orq caixa (ticket 140) ----------

def _box140(a, runs=("run_a", "run_b"), bound="run_a"):
    """Runs in the fake Orca (one Run per terminal): the coordinator (term_coord) is bound to `bound`; orq runs from another shell (term_outro)."""
    _multi(a, {r: ("term_coord" if r == bound else None) for r in runs})
    os.makedirs(a.home, exist_ok=True)
    _write_state(os.path.join(a.home, "gerente.json"), {"coordenador": "term_coord", "gerente": "term_ger", "runs": []})
    a.env["ORCA_TERMINAL_HANDLE"] = "term_outro"  # the coordinator's terminal comes from orq's state, not from the env


def _global_box336(a):
    """Mirrors the fake mailbox into Orca's global inbox (`inbox --full`): the unread messages of every Run, as the real Orca lists them."""
    box = json.load(open(os.path.join(a.fake, "mailbox.json")))["msgs"]
    a.set("inbox.json", {"result": {"messages": [{k: v for k, v in m.items() if k not in ("status", "delivery", "gen")} | {"sequence": i + 1, "read": int(m["status"] == "acked")}
                                                   for i, m in enumerate(box)]}})


def test_ticket140_inbox_reads_and_acks_in_same_generation():
    a = Env()
    _box140(a)
    a.inbox(("worker_done", {"taskId": "task_1", "outcome": "succeeded"}))
    r = a.orq("caixa", "run_a", "--ack")
    assert r.returncode == 0, r.stderr
    assert "msg_1 worker_done" in r.stdout and "task_1" in r.stdout and "confirmadas" in r.stdout, r.stdout
    assert a.states() == {"msg_1": "acked"}
    assert {h for _, h in _log(a, "binds.log")} <= {"term_coord"}, "todo run-use sai com o --from do coordenador"


