# ---------- ticket 155: an obligation orq can prove closes on its own ----------

def _py155(a, code):
    """Runs `code` (Python, with orqlib imported) in the test environment's ORQ_HOME and returns the stdout."""
    r = subprocess.run([sys.executable, "-c", f"import sys; sys.path.insert(0, {HERE!r}); import orqlib as o; {code}"], capture_output=True, text=True, env=a.env, timeout=30)
    assert r.returncode == 0, r.stderr
    return r.stdout.strip()


def _cleaned155(a, **fields):
    _py155(a, f"o.append_event({{'tipo': 'pr', 'op': 'limpou', 'task': 'task_feat1', 'branch': 'feat/x', 'removidos': [], 'guardados': [], 'pulados': [], **{fields!r}}}); "
              f"o.cleaned_close(o.read_events()[-1])")


def test_ticket155_cleaned_with_removal_closes_cleanup_with_event_as_proof():
    a = _prs_env()
    e = _merge_main(a)
    _cleaned155(a, removidos=["worktree:feat/x", "local:feat/x", "remote:feat/x"])
    assert "limpeza" not in _find_obligation(a, e) and {"deploy", "comentario"} <= set(_find_obligation(a, e))
    (f,) = [x for x in a.events() if x["tipo"] == "obrigacao" and x["op"] == "feito"]
    assert f["chave"] == "limpeza" and "worktree:feat/x" in f["prova"], f


