# ---- ticket 157: implicit intake ----

def _intakes(a):
    return [e for e in a.events() if e["tipo"] == "intake"]


def test_ticket157_one_open_entry_and_dispatch_without_entry_writes_intake_task():
    a = Env(run="run_a")
    a.prompt("cria o ticket 05")
    r = _dispatch(a)
    assert r.returncode == 0, r.stderr
    (i,) = _intakes(a)
    assert (i["entrada"], i["efeito"], i["ref"], i["run"]) == ("e1", "tarefa", "task_novo1", "run_a"), i
