# ---- M6: orq doctor backlog ----

def test_ticket102_m6_doctor_backlog_without_diff_says_what_it_checked_and_with_diff_prints_the_fix():
    a = _env_tk()
    for t in ("Um", "Dois", "Tres", "Quatro"):
        _new(a, t)
    r = a.orq("doctor", "backlog")
    assert r.returncode == 0 and "consistent (4 tickets, 4 tasks checked)" in r.stdout, (r.stdout, r.stderr)
    bl = a.env["ORQ_BACKLOG"]
    backlog_mod.cli(bl, "done", "t01", "--no-prune")  # Done with the task open
    backlog_mod.cli(bl, "start", "t02")  # In flight without a dispatched worker
    ts = _tasks_fake(a)
    ts[2]["status"] = "completed"  # Queued with the task finished
    ts[3]["status"] = "dispatched"  # Queued with the task dispatched
    a.set("tasks_run_a.json", ts)
    open(os.path.join(a.env["ORQ_ISSUES"], "09-solto.md"), "w").write("# 09: solto\n")  # file without an item
    r = a.orq("doctor", "backlog")
    assert r.returncode == 1, r.stdout
    line_list = r.stdout.splitlines()
    assert len(line_list) == 5, r.stdout
    by = {l.split(":")[0]: l for l in line_list}
    assert "Done, but task task_tk1 is ready" in by["01"] and "task-update --id task_tk1 --status completed --run run_a" in by["01"]
    assert "In flight, but task task_tk2 is ready, with no dispatched worker" in by["02"] and "orq dispatch --run run_a --ticket 02" in by["02"]
    assert "Queued, but task task_tk3 is already completed" in by["03"] and "orq ticket close 03" in by["03"]
    assert "Queued, but task task_tk4 is dispatched" in by["04"] and f"TASKS_AXI_FILE={bl} tasks-axi start t04" in by["04"]
    assert "09-solto.md has no item" in by["09"] and "converte-backlog.py --completa" in by["09"]
    assert len(json.loads(a.orq("doctor", "backlog", "--json").stdout)["problemas"]) == 5


