# ---- M7: backlog per group ----

def _orq_group(a, **cfg):
    os.makedirs(os.path.join(a.home, "groups"), exist_ok=True)
    json.dump({"projetos": [], "prefixos": ["orq:"], **cfg}, open(os.path.join(a.home, "groups", "orq.json"), "w"))
    return os.path.join(a.tmp.name, "data", "grupos", "orq", "backlog.md")


def test_ticket102_m7_move_takes_the_linked_set_to_group_backlog_and_preserves_the_blockers():
    a = _env_tk()
    destination = _orq_group(a)
    _new(a, "Base")
    _new(a, "orq: B", "--blocked-by", "01")
    _new(a, "orq: C", "--blocked-by", "02")
    _new(a, "Solto")
    a.orq("ticket", "fechar", "01", "--answer", "ok")
    r = a.orq("backlog", "mover", "02", "03", "--grupo", "orq")
    assert r.returncode == 0, r.stderr
    assert json.loads(r.stdout) == {"grupo": "orq", "destino": destination, "tickets": ["t02", "t03"]}
    assert sorted(_bl_items(a)) == ["avisar-x", "freio-prod", "t01", "t04"]
    side = {i["id"]: i for i in backlog_mod.read_value(destination)}
    assert sorted(side) == ["t02", "t03"] and side["t03"]["bloqueios"] == ["t02"] and side["t02"]["bloqueios"] == [], "a aresta entre os dois ficou; a do bloqueador já Done saiu"
    assert _meta_tk(side["t02"])["orca"] == "task_tk2 run_a" and _meta_tk(side["t02"])["spec"] == "issues/02-orq-b.md", "o elo com o Orca e com o arquivo foi junto"
    assert _tk_list(a).splitlines() == ["04 Solto (ready-for-agent)"]
    assert open(os.path.join(os.path.dirname(destination), ".tasks.toml")).read().count("done_keep = 100000") == 1
    (ev,) = [e for e in a.events() if e["tipo"] == "backlog"]
    assert (ev["op"], ev["grupo"], ev["tickets"]) == ("mover", "orq", ["t02", "t03"])


def test_ticket102_m7_move_refuses_dangling_dependency_ticket_outside_queue_and_group_without_registration():
    a = _env_tk()
    destination = _orq_group(a)
    _new(a, "orq: A")
    _new(a, "orq: B", "--blocked-by", "01")
    before = open(a.env["ORQ_BACKLOG"]).read()
    r = a.orq("backlog", "mover", "01", "--grupo", "orq")
    assert r.returncode == 1 and "blocking" in r.stderr, r.stderr
    assert open(a.env["ORQ_BACKLOG"]).read() == before and backlog_mod.read_value(destination) == [], "nada se moveu"
    a.orq("ticket", "fechar", "01", "--answer", "ok")
    r = a.orq("backlog", "mover", "01", "--grupo", "orq")
    assert r.returncode == 1 and "only what is still queued moves" in r.stderr, r.stderr
    assert a.orq("despachar", "--run", "run_a", "--modelo", "claude-sonnet-5-5", "--effort", "medium", "--ticket", "02").returncode == 0
    r = a.orq("backlog", "mover", "02", "--grupo", "orq")
    assert r.returncode == 1 and "only what is still queued moves" in r.stderr
    assert a.orq("backlog", "mover", "02", "--grupo", "nao-existe").returncode == 1 and a.orq("backlog", "mover", "--grupo", "orq").returncode == 2


