# ---- the full conversion completes the backlog that exists ----

def test_ticket102_complete_adds_only_what_is_missing_and_checks_the_count_before_and_after():
    a = Env()
    _issues_101(a)
    a.set("../pendencias.json", {"itens": []})
    output = os.path.join(a.tmp.name, "data", "backlog.md")
    assert _convert(a, output).returncode == 0
    before = {i["id"]: i for i in backlog_mod.read_value(output)}
    for nn, title, status, bl, task in (("06", "orq: Novo livre", "ready-for-agent", "05", "task_n6"), ("07", "Novo andando", "claimed", "06", "task_n7"), ("08", "Novo feito", "resolved", "(nenhum)", "task_n8")):
        open(os.path.join(a.env["ORQ_ISSUES"], f"{nn}-x.md"), "w").write(f"# {nn}: {title}\n\nStatus: {status}\nBlocked by: {bl}\nRun: run_a\nTask: {task}\n\n## What to build\n\ncorpo\n")
    r = _convert(a, output, "--completa")
    assert r.returncode == 0, (r.stdout, r.stderr)
    assert "antes 5, depois 8 (+3: t06, t07, t08)" in r.stdout, r.stdout
    it = {i["id"]: i for i in backlog_mod.read_value(output)}
    assert {k: v for k, v in it.items() if k in before} == before, "o que já estava não foi tocado"
    assert (it["t06"]["estado"], it["t06"]["repo"], it["t06"]["bloqueios"]) == ("queued", "orq", ["t05"])
    assert (it["t07"]["estado"], it["t07"]["bloqueios"]) == ("in_flight", ["t06"]) and it["t08"]["estado"] == "done"
