def _old_doctor178(terminals, ticket_status="resolved", w_status="completed", max_age_hours=48, without_worker=False, extra=()):
    """Runs doctor_old over a dispatch from `max_age_hours` ago (ticket 14, task t14) with everything simulated; returns (result, release calls, events written)."""
    called_ids, written_items = [], []
    ev = [{"ts": now_iso(-max_age_hours * 3600), "tipo": "despacho", "dispatch": "ctx_old", "task": "t14", "ticket": "14", "run": "run_a", "terminal": "term_old"}, *extra]
    w = {"dispatchId": "ctx_old", "dispatchStatus": w_status, "agentTerminalHandle": "term_old"}
    swaps = {"read_events": lambda: ev, "_alive_terminals": lambda: terminals, "_all_workers": lambda run=None: [] if without_worker else [w],
              "tickets": lambda: [{"num": "14", "task": "t14", "status": ticket_status}], "release": lambda d, run=None: called_ids.append(d),
              "append_event": lambda e, new_id=False: written_items.append(e)}
    old_values = {k: getattr(orq_mod, k) for k in swaps}
    try:
        for k, v in swaps.items():
            setattr(orq_mod, k, v)
        return orq_mod.doctor_old(True), called_ids, written_items
    finally:
        for k, v in old_values.items():
            setattr(orq_mod, k, v)


def test_ticket178_old_dispatch_without_terminal_and_resolved_ticket_appears_and_leaves_live_ones():
    r, called_ids, _ = _old_doctor178({"term_outro"})
    assert [x["dispatch"] for x in r["antigos"]] == ["ctx_old"] and r["liberados"] == ["ctx_old"] and called_ids == ["ctx_old"], r
    assert "released: ctx_old" in orq_mod.doctor_old_text(r, True)


def test_ticket178_without_record_in_worker_list_writes_release_with_old_reason():
    r, called_ids, written_items = _old_doctor178({"term_outro"}, without_worker=True)
    assert not called_ids and [(g["tipo"], g["dispatch"], g["motivo"], g["fechado"]) for g in written_items] == [("liberar", "ctx_old", "antigo", True)], written_items


def test_ticket178_released_with_already_dead_terminal_leaves_live_ones_and_release_unknown_only_writes_event():
    assert not _old_doctor178({"term_outro"}, extra=[{"tipo": "liberar", "dispatch": "ctx_old", "estado": "already_released", "fechado": False}])[0]["antigos"]
    r, called_ids, written_items = _old_doctor178({"term_outro"}, extra=[{"tipo": "liberar", "dispatch": "ctx_old", "estado": "release_unknown", "fechado": False}])
    assert r["liberados"] == ["ctx_old"] and not called_ids and written_items[0]["motivo"] == "antigo", "não repete o worker-release"


