def _g176(repo, *a):
    subprocess.run(["git", "-C", repo, "-c", "user.name=t", "-c", "user.email=t@t", *a], check=True, capture_output=True)


def _scenario176():
    """repo with origin; worktrees: pronta (contained), fora (commit outside origin/main), suja (dirty), integracao (integra/x)."""
    tmp = tempfile.mkdtemp()
    origin = os.path.join(tmp, "origin.git")
    subprocess.run(["git", "init", "-q", "--bare", "-b", "main", origin], check=True)
    repo = _repo_with_branch(tmp)
    _g176(repo, "remote", "add", "origin", origin)
    root = os.path.join(tmp, "orq-wt")
    for item_name, b in (("1", "feat/pronta"), ("2", "feat/fora"), ("3", "feat/suja"), ("integracao", "integra/x")):
        _g176(repo, "worktree", "add", "-q", "-b", b, os.path.join(root, item_name))
    _g176(os.path.join(root, "1"), "commit", "-q", "--allow-empty", "-m", "a")
    _g176(os.path.join(root, "3"), "commit", "-q", "--allow-empty", "-m", "c")
    _g176(os.path.join(root, "2"), "commit", "-q", "--allow-empty", "-m", "b")
    _g176(repo, "merge", "-q", "--ff-only", "feat/pronta")
    _g176(repo, "merge", "-q", "--no-edit", "feat/suja")
    _g176(repo, "push", "-q", "origin", "main")
    _g176(repo, "fetch", "-q", "origin")
    open(os.path.join(root, "3", "novo.txt"), "w").write("x")
    return repo, root


def _k176(repo, **kw):
    """Two days ahead (nothing is recent), no resolved ticket or live dispatch, bundle next to the repo."""
    return {"now_at": time.time() + 172800, "resolved_tickets": set(), "live": set(), "backups": os.path.join(os.path.dirname(repo), "backups"), **kw}


def test_ticket176_cleans_only_worktree_whose_branch_is_in_origin_main():
    repo, root = _scenario176()
    os.remove(os.path.join(root, "3", "novo.txt"))  # the scenario's dirty one becomes clean: it goes out
    open(os.path.join(root, "2", "novo.txt"), "w").write("x")
    r = orq_mod.clean_orq_worktrees(repo, root, dry_run=True, **_k176(repo))
    assert sorted(os.path.basename(x["pasta"]) for x in r["removidas"]) == ["1", "3"] and os.path.isdir(os.path.join(root, "1")), r
    r = orq_mod.clean_orq_worktrees(repo, root, **_k176(repo))
    assert sorted(os.path.basename(x["pasta"]) for x in r["removidas"]) == ["1", "3"], r
    assert not os.path.exists(os.path.join(root, "1")) and os.path.isdir(os.path.join(root, "2"))
    branches = subprocess.run(["git", "-C", repo, "branch", "--format=%(refname:short)"], capture_output=True, text=True).stdout.split()
    assert "feat/pronta" not in branches and "feat/fora" in branches


def test_ticket176_branch_with_commit_outside_main_stays_with_reason():
    repo, root = _scenario176()
    r = orq_mod.clean_orq_worktrees(repo, root, **_k176(repo))
    stays = {os.path.basename(x["pasta"]): x["motivo"] for x in r["ficaram"]}
    assert "commit outside origin/main" in stays["2"] and os.path.isdir(os.path.join(root, "2")), stays


def test_ticket176_dirty_worktree_stays_even_with_integrated_branch():
    repo, root = _scenario176()
    r = orq_mod.clean_orq_worktrees(repo, root, **_k176(repo))
    assert {os.path.basename(x["pasta"]): x["motivo"] for x in r["ficaram"]}["3"] == "uncommitted changes"
    assert os.path.exists(os.path.join(root, "3", "novo.txt"))


def test_ticket176_integrator_worktree_stays():
    repo, root = _scenario176()
    r = orq_mod.clean_orq_worktrees(repo, root, **_k176(repo))
    assert {os.path.basename(x["pasta"]): x["motivo"] for x in r["ficaram"]}["integracao"] == "integrator worktree"
    assert os.path.isdir(os.path.join(root, "integracao"))


def _rewrite176(**kw):
    """scenario + worktree 4 (feat/reescrita) with a commit of subject "a" that origin/main has under a different hash."""
    repo, root = _scenario176()
    _g176(repo, "worktree", "add", "-q", "-b", "feat/reescrita", os.path.join(root, "4"), "main~2")
    _g176(os.path.join(root, "4"), "commit", "-q", "--allow-empty", "--date=2000-01-01T00:00:00", "-m", "a")  # outra data: hash diferente, mesmo assunto
    return repo, root, _k176(repo, resolved_tickets={"04"}, **kw)


def _stays176(r, item_name):
    return {os.path.basename(x["pasta"]): x["motivo"] for x in r["ficaram"]}.get(item_name)


def test_ticket176_rewritten_hash_with_resolved_ticket_leaves_with_bundle_before():
    repo, root, k = _rewrite176()
    r = orq_mod.clean_orq_worktrees(repo, root, **k)
    assert "4" in [os.path.basename(x["pasta"]) for x in r["removidas"]] and not os.path.exists(os.path.join(root, "4")), r
    assert r["bundle"] and os.path.basename(r["bundle"]).startswith("orq-wt-") and r["bundle"].endswith(".bundle")
    heads = subprocess.run(["git", "bundle", "list-heads", r["bundle"]], capture_output=True, text=True, cwd=repo).stdout
    assert "refs/heads/feat/reescrita" in heads, heads
    assert "feat/reescrita" not in subprocess.run(["git", "-C", repo, "branch", "--format=%(refname:short)"], capture_output=True, text=True).stdout.split()


def test_ticket176_rewritten_hash_with_open_ticket_or_subject_without_pair_stays():
    repo, root, k = _rewrite176()
    k["resolved_tickets"] = set()
    r = orq_mod.clean_orq_worktrees(repo, root, **k)
    assert "is not resolved" in _stays176(r, "4") and os.path.isdir(os.path.join(root, "4")) and r["bundle"] is None
    repo, root, k = _rewrite176()
    k["resolved_tickets"] = {"04", "02"}  # 2 (feat/fora) has the subject "b", which origin/main does not have
    r = orq_mod.clean_orq_worktrees(repo, root, **k)
    assert "no matching subject" in _stays176(r, "2") and os.path.isdir(os.path.join(root, "2"))


def test_ticket176_live_dispatch_and_recent_worktree_stay_even_if_integrated():
    repo, root, k = _rewrite176(live={"01", "04"})
    r = orq_mod.clean_orq_worktrees(repo, root, **k)
    assert _stays176(r, "1") == _stays176(r, "4") == "live dispatch for the ticket" and os.path.isdir(os.path.join(root, "1"))
    repo, root, k = _rewrite176(now_at=time.time())
    r = orq_mod.clean_orq_worktrees(repo, root, **k)
    assert _stays176(r, "1") == "created less than 24 h ago" and os.path.isdir(os.path.join(root, "1"))


