def _outputs(a):
    """The output of the main commands and the saved digest, to compare before and after the migration. Only what depends on the clock comes out
    (the fake Orca gives the dispatch `since` from the call time): ages, hours and the geradoEm."""
    def without_clock(txt):
        return re.sub(r"\b\d+(?:[.,]\d+)? ?(?:s|min|h|d)\b|\b\d{2}:\d{2}(?::\d{2})?\b", "<t>", txt)
    out = {c: without_clock(a.orq(*c.split()).stdout) for c in ("status", "summary", "agents --all", "digest")}
    out["agents --json"] = [{k: v for k, v in x.items() if k not in ("desde", "idade_s")} for x in json.loads(a.orq("agents", "--all", "--json").stdout)]
    d = json.load(open(os.path.join(a.home, "digest", "atual.json")))
    d.pop("geradoEm", None)
    return {**out, "atual.json": json.loads(without_clock(json.dumps(d, ensure_ascii=False)))}


def _migrate(a, *args, **env):
    return subprocess.run([sys.executable, MIGRATE_SCRIPT, *args], capture_output=True, text=True, env={**a.env, **env}, timeout=60)


def _copy(origin_name, destination):
    shutil.rmtree(destination, ignore_errors=True)
    shutil.copytree(origin_name, destination)


def test_map_en_is_injective_and_round_trips():
    for item_name, m in [("CHAVES_EN", orqlib.KEYS_EN), ("TIPOS_EN", orqlib.TYPES_EN), *orqlib.VALUES_EN.items()]:
        assert len(set(m.values())) == len(m), f"{item_name}: dois nomes pt dão o mesmo inglês"
    assert not set(orqlib.KEYS_EN.values()) & set(orqlib.KEYS_EN), "chave em inglês que também é chave pt: a leitura não saberia qual é"
    pt = {"tipo": "entrada", "texto": "liberar a fila", "efeito": "tarefa", "itens": [{"estado": "rodando", "titulo": "x"}], "ref": "task_1",
          "estado": "released", "pend_tipo": "decisao"}
    en = orqlib.to_en(pt)
    assert en == {"type": "entry", "text": "liberar a fila", "effect": "task", "items": [{"state": "running", "title": "x"}], "ref": "task_1",
                  "state": "released", "pending_type": "decision"}, en
    assert orqlib.to_pt(en) == pt and orqlib.to_pt(pt) == pt and orqlib.to_en(en) == en, "texto livre e valor do Orca não mudam"


def test_migrate_english_gives_the_same_output_for_status_summary_agents_and_digest():
    a = Env(run="run_a")
    _home_pt(a)
    snap_home, snap_fake = a.home + ".pt", a.fake + ".pt"
    _copy(a.home, snap_home)
    _copy(a.fake, snap_fake)
    before = _outputs(a)
    _copy(snap_home, a.home)
    _copy(snap_fake, a.fake)
    workers = json.load(open(os.path.join(a.fake, "workers.json")))
    a.set("workers.json", [{**w, "status": "completed"} for w in workers])  # the workers stop for the migration and come back afterwards
    r = _migrate(a)
    assert r.returncode == 0, r.stderr
    a.set("workers.json", workers)
    assert "events.jsonl: 14 linhas, 14 em pt" in r.stdout and "chaves pt sem tradução: nenhuma" in r.stdout, r.stdout
    names = set(os.listdir(a.home))
    assert {"open.json", "merge-queue.json", "turns.json", "integrate-queue.json", "dispatch-queue.json", "machine.json"} <= names, names
