            assert os.path.exists(os.path.join(w.home, "backup-pt-2026-09-05")) and not os.path.exists(os.path.join(w.home, "avisos", "old.txt")), "the safe tier ran anyway"
            orq_mod.machine_level = lambda *a, **k: ("ok", None)
